insert into _new (name, file, body_part, en, es) values
  ('Abrazo al Fitball (Estiramiento)', 'exercise-ball-hug.gif', 'back', '["Sit on the stability ball with your feet flat on the ground and your back straight.", "Hold the stability ball with both hands, hugging it close to your chest.", "Engage your core muscles and slowly lean back, keeping your back straight and your feet planted on the ground.", "Continue leaning back until you feel a stretch in your back muscles.", "Hold the position for a few seconds, then slowly return to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en el balón de estabilidad con los pies planos en el suelo y la espalda recta.", "Sujeta el balón de estabilidad con ambas manos, abrazándolo cerca del pecho.", "Activa los músculos del core y reclínate lentamente hacia atrás, manteniendo la espalda recta y los pies apoyados en el suelo.", "Continúa reclinándote hacia atrás hasta sentir un estiramiento en los músculos de la espalda.", "Mantén la posición durante unos segundos, luego vuelve lentamente a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Arquero de Pie (Movilidad)', 'standing-archer.gif', 'back', '["Stand with your feet shoulder-width apart and your knees slightly bent.", "Extend your arms straight out in front of you at shoulder height, parallel to the ground.", "Rotate your torso to the right, keeping your arms extended and your back straight.", "As you rotate, extend your right arm forward and your left arm back, mimicking the motion of drawing a bowstring.", "Hold the position for a moment, then return to the starting position.", "Repeat the motion, this time rotating your torso to the left and extending your left arm forward and your right arm back.", "Continue alternating sides for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.", "Extiende los brazos rectos hacia adelante a la altura de los hombros, paralelos al suelo.", "Gira el torso hacia la derecha, manteniendo los brazos extendidos y la espalda recta.", "Mientras giras, extiende el brazo derecho hacia adelante y el brazo izquierdo hacia atrás, imitando el movimiento de tensar un arco.", "Mantén la posición por un momento y luego vuelve a la posición inicial.", "Repite el movimiento, esta vez girando el torso hacia la izquierda y extendiendo el brazo izquierdo hacia adelante y el brazo derecho hacia atrás.", "Continúa alternando lados durante el número de repeticiones deseado."]'),
  ('Back Lever (Palanca Dorsal)', 'back-lever.gif', 'back', '["Start by hanging from a pull-up bar with an overhand grip, hands slightly wider than shoulder-width apart.", "Engage your core and pull your shoulder blades down and back.", "Bend your knees and tuck them towards your chest.", "Slowly lift your legs up, keeping them straight, until your body is parallel to the ground.", "Hold this position for a few seconds, then slowly lower your legs back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Comienza colgándote de una barra de dominadas con un agarre prono, con las manos un poco más separadas que el ancho de los hombros.", "Activa el core y lleva los omóplatos hacia abajo y atrás.", "Flexiona las rodillas y llévalas hacia el pecho.", "Levanta lentamente las piernas, manteniéndolas rectas, hasta que el cuerpo quede paralelo al suelo.", "Mantén esta posición durante unos segundos, luego baja lentamente las piernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Dominada a 1 Brazo', 'one-arm-chin-up.gif', 'back', '["Stand facing a pull-up bar with your feet shoulder-width apart.", "Reach up and grab the bar with an underhand grip, with one hand gripping the bar and the other hand holding your wrist for support.", "Hang from the bar with your arm fully extended, keeping your body straight and your core engaged.", "Pull yourself up towards the bar by bending your elbow and squeezing your back muscles.", "Continue pulling until your chin is above the bar, then slowly lower yourself back down to the starting position.", "Repeat for the desired number of repetitions, then switch arms and repeat."]', '["Ponte de pie frente a una barra de dominadas con los pies separados a la altura de los hombros.", "Estírate y agarra la barra con un agarre supino, con una mano sujetando la barra y la otra sosteniendo la muñeca como apoyo.", "Cuélgate de la barra con el brazo completamente extendido, manteniendo el cuerpo recto y el core activado.", "Tira de tu cuerpo hacia la barra flexionando el codo y contrayendo los músculos de la espalda.", "Continúa subiendo hasta que la barbilla quede por encima de la barra, luego bájate lentamente de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de brazo y repite."]'),
  ('Dominada a 1 Mano con Lastre', 'weighted-one-hand-pull-up.gif', 'back', '["Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart.", "Hang from the bar with your arm fully extended and your body straight.", "Engage your core and pull your body up towards the bar by bending your elbow and squeezing your back muscles.", "Continue pulling until your chin is above the bar.", "Lower your body back down to the starting position with control.", "Repeat for the desired number of repetitions."]', '["Sujeta la barra de dominadas con un agarre prono, un poco más ancho que la altura de los hombros.", "Cuélgate de la barra con un brazo completamente extendido y el cuerpo recto.", "Activa el core y tira de tu cuerpo hacia arriba en dirección a la barra flexionando el codo y contrayendo los músculos de la espalda.", "Continúa subiendo hasta que la barbilla quede por encima de la barra.", "Baja el cuerpo de nuevo a la posición inicial con control.", "Repite el número de repeticiones deseado."]'),
  ('Dominada al Esternón Gironda', 'gironda-sternum-chin.gif', 'back', '["Stand facing a high bar with your feet shoulder-width apart.", "Reach up and grab the bar with an overhand grip, slightly wider than shoulder-width apart.", "Hang from the bar with your arms fully extended and your body straight.", "Engage your lats and biceps to pull your chest up towards the bar, leading with your sternum.", "Pause for a moment at the top, then slowly lower yourself back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie frente a una barra alta con los pies separados a la altura de los hombros.", "Estira los brazos hacia arriba y agarra la barra con agarre prono, ligeramente más ancho que la altura de los hombros.", "Cuélgate de la barra con los brazos completamente extendidos y el cuerpo recto.", "Activa los dorsales y los bíceps para llevar el pecho hacia la barra, guiando con el esternón.", "Haz una pausa breve en la parte más alta, luego baja lentamente de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Dominada Arquero', 'archer-pull-up.gif', 'back', '["Start by hanging from a pull-up bar with an overhand grip, slightly wider than shoulder-width apart.", "Engage your core and pull your shoulder blades down and back.", "As you pull yourself up, bend one arm and bring your elbow towards your side, while keeping the other arm straight.", "Continue pulling until your chin is above the bar and your bent arm is fully flexed.", "Lower yourself back down with control, straightening the bent arm and repeating the movement on the other side.", "Alternate sides with each repetition."]', '["Comienza colgándote de una barra de dominadas con un agarre prono, un poco más separado que el ancho de los hombros.", "Activa el core y lleva los omóplatos hacia abajo y atrás.", "Mientras te elevas, flexiona un brazo y lleva el codo hacia el costado, manteniendo el otro brazo recto.", "Continúa subiendo hasta que la barbilla quede por encima de la barra y el brazo flexionado esté completamente doblado.", "Bájate de nuevo con control, estirando el brazo flexionado y repitiendo el movimiento del otro lado.", "Alterna los lados en cada repetición."]'),
  ('Dominada Asistida con Banda Elástica', 'band-assisted-pull-up.gif', 'back', '["Attach the band to a pull-up bar or sturdy anchor point.", "Step onto the band and grip the bar with your palms facing away from you, hands slightly wider than shoulder-width apart.", "Hang with your arms fully extended, keeping your core engaged and your shoulders down and back.", "Pull your body up towards the bar by squeezing your shoulder blades together and driving your elbows down towards your hips.", "Continue pulling until your chin is above the bar, then slowly lower yourself back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Sujeta la banda a una barra de dominadas o a un punto de anclaje resistente.", "Pisa la banda y agarra la barra con las palmas mirando hacia afuera, con las manos un poco más separadas que el ancho de los hombros.", "Cuélgate con los brazos completamente extendidos, manteniendo el core activado y los hombros abajo y atrás.", "Sube el cuerpo hacia la barra juntando los omóplatos y llevando los codos hacia abajo, en dirección a las caderas.", "Continúa subiendo hasta que la barbilla quede por encima de la barra, luego bájate lentamente de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Dominada Asistida en Máquina (de Pie)', 'assisted-standing-pull-up.gif', 'back', '["Adjust the machine to your desired weight and height settings.", "Stand facing the machine with your feet shoulder-width apart.", "Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.", "Engage your lats and biceps, and pull yourself up towards the handles.", "Pause for a moment at the top, squeezing your back muscles.", "Slowly lower yourself back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta la máquina a los valores de peso y altura deseados.", "Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.", "Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros.", "Activa los dorsales y los bíceps, y levántate hacia las agarraderas.", "Haz una pausa por un momento en la parte superior, apretando los músculos de la espalda.", "Bájate lentamente de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Dominada Asistida en Máquina con Agarre Neutro Cerrado', 'assisted-parallel-close-grip-pull-up.gif', 'back', '["Adjust the machine to your desired weight and height.", "Place your hands on the parallel bars with a close grip, palms facing each other.", "Hang from the bars with your arms fully extended and your feet off the ground.", "Engage your back muscles and pull your body up towards the bars, keeping your elbows close to your body.", "Continue pulling until your chin is above the bars.", "Pause for a moment at the top, then slowly lower your body back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta la máquina al peso y la altura deseados.", "Coloca las manos en las barras paralelas con un agarre cerrado, con las palmas mirándose entre sí.", "Cuélgate de las barras con los brazos completamente extendidos y los pies sin tocar el suelo.", "Activa los músculos de la espalda y lleva el cuerpo hacia arriba hacia las barras, manteniendo los codos cerca del cuerpo.", "Continúa subiendo hasta que la barbilla quede por encima de las barras.", "Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Dominada Asistida en Máquina con Agarre Prono', 'assisted-pull-up.gif', 'back', '["Adjust the machine to your desired weight and height settings.", "Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.", "Hang with your arms fully extended and your feet off the ground.", "Engage your back muscles and pull your body up towards the handles, keeping your elbows close to your body.", "Continue pulling until your chin is above the handles.", "Pause for a moment at the top, then slowly lower your body back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta la máquina a los valores de peso y altura deseados.", "Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros.", "Cuélgate con los brazos completamente extendidos y los pies sin tocar el suelo.", "Activa los músculos de la espalda y lleva el cuerpo hacia arriba hacia las agarraderas, manteniendo los codos cerca del cuerpo.", "Continúa subiendo hasta que la barbilla quede por encima de las agarraderas.", "Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Dominada con Agarre al Ancho de Hombros', 'shoulder-grip-pull-up.gif', 'back', '["Grab the pull-up bar with a shoulder-width grip, palms facing away from you.", "Hang freely with your arms fully extended.", "Engage your back muscles and pull your body up towards the bar until your chin is above the bar.", "Pause for a moment at the top, then slowly lower your body back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Sujeta la barra de dominadas con un agarre a la altura de los hombros, con las palmas mirando hacia fuera.", "Cuélgate libremente con los brazos completamente extendidos.", "Activa los músculos de la espalda y tira de tu cuerpo hacia la barra hasta que la barbilla quede por encima de ella.", "Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Dominada con Agarre Mixto', 'mixed-grip-chin-up.gif', 'back', '["Grab the pull-up bar with an underhand grip (palms facing towards you) and your hands slightly wider than shoulder-width apart.", "Hang from the bar with your arms fully extended and your feet off the ground.", "Engage your back muscles and pull your body up towards the bar, leading with your chest.", "Continue pulling until your chin is above the bar.", "Pause for a moment at the top, then slowly lower your body back down to the starting position with control.", "Repeat for the desired number of repetitions."]', '["Agarra la barra de dominadas con un agarre supino (las palmas hacia ti) y las manos un poco más separadas que la anchura de los hombros.", "Cuélgate de la barra con los brazos completamente extendidos y los pies fuera del suelo.", "Activa los músculos de la espalda y tira de tu cuerpo hacia la barra, llevando el pecho por delante.", "Continúa subiendo hasta que la barbilla quede por encima de la barra.", "Haz una pausa por un momento en la parte alta y luego baja lentamente tu cuerpo, con control, hasta la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Dominada con Lastre', 'weighted-pull-up.gif', 'back', '["Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart.", "Hang from the bar with your arms fully extended and your body straight.", "Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body.", "Continue pulling until your chin is above the bar.", "Pause for a moment at the top, then slowly lower your body back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Sujeta la barra de dominadas con un agarre prono, un poco más ancho que la altura de los hombros.", "Cuélgate de la barra con los brazos completamente extendidos y el cuerpo recto.", "Activa los músculos de la espalda y tira de tu cuerpo hacia arriba, hacia la barra, manteniendo los codos cerca del cuerpo.", "Continúa subiendo hasta que la barbilla quede por encima de la barra.", "Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Dominada de Lado a Lado', 'side-to-side-chin.gif', 'back', '["Stand with your feet shoulder-width apart and your knees slightly bent.", "Grasp a pull-up bar with an overhand grip, hands slightly wider than shoulder-width apart.", "Hang from the bar with your arms fully extended and your body relaxed.", "Pull yourself up by bending your elbows and bringing your chin towards the bar, while keeping your body straight.", "Once your chin is above the bar, lower yourself back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.", "Sujeta una barra de dominadas con un agarre prono, con las manos un poco más separadas que el ancho de los hombros.", "Cuélgate de la barra con los brazos completamente extendidos y el cuerpo relajado.", "Levántate doblando los codos y llevando la barbilla hacia la barra, manteniendo el cuerpo recto.", "Una vez que la barbilla esté por encima de la barra, bájate de nuevo a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Dominada en L', 'l-pull-up.gif', 'back', '["Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart.", "Hang with your arms fully extended and your body straight.", "Engage your lats and biceps to pull your body up towards the bar, keeping your elbows close to your body.", "Continue pulling until your chin is above the bar.", "Pause for a moment at the top, then slowly lower your body back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Sujeta la barra de dominadas con un agarre prono, un poco más ancho que la altura de los hombros.", "Cuélgate con los brazos completamente extendidos y el cuerpo recto.", "Activa los dorsales y los bíceps para llevar el cuerpo hacia arriba en dirección a la barra, manteniendo los codos cerca del cuerpo.", "Continúa subiendo hasta que la barbilla quede por encima de la barra.", "Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Dominada Escapular', 'scapular-pull-up.gif', 'back', '["Start by hanging from a pull-up bar with your palms facing away from you and your arms fully extended.", "Retract your shoulder blades by pulling them down and back.", "Engage your back muscles and pull your body up towards the bar, focusing on squeezing your shoulder blades together.", "Pause for a moment at the top of the movement, then slowly lower your body back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Comienza colgándote de una barra de dominadas con las palmas hacia afuera y los brazos completamente extendidos.", "Retrae las escápulas llevándolas hacia abajo y atrás.", "Activa los músculos de la espalda y tira de tu cuerpo hacia la barra, enfocándote en juntar las escápulas.", "Haz una pausa breve en la parte superior del movimiento, luego baja lentamente el cuerpo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Dominada Rocky (Tras Nuca y al Pecho)', 'rocky-pull-up-pulldown.gif', 'back', '["Stand in front of a pull-up bar with your feet shoulder-width apart.", "Reach up and grab the bar with an overhand grip, slightly wider than shoulder-width apart.", "Hang from the bar with your arms fully extended and your body straight.", "Engage your back muscles and pull your body up towards the bar, leading with your chest.", "Pause for a moment at the top, then slowly lower your body back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie frente a una barra de dominadas con los pies separados a la altura de los hombros.", "Estira los brazos hacia arriba y agarra la barra con agarre prono, ligeramente más ancho que la altura de los hombros.", "Cuélgate de la barra con los brazos completamente extendidos y el cuerpo recto.", "Activa los músculos de la espalda y tira de tu cuerpo hacia la barra, llevando el pecho por delante.", "Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Dominada Supina Asistida en Máquina (de Pie)', 'assisted-standing-chin-up.gif', 'back', '["Adjust the machine to your desired assistance level.", "Stand on the foot platform and grip the handles with an overhand grip, slightly wider than shoulder-width apart.", "Keep your chest up and shoulders back, engage your core, and slightly bend your knees.", "Pull your body up by flexing your elbows and driving your elbows down towards your sides.", "Continue pulling until your chin is above the bar.", "Pause for a moment at the top, then slowly lower your body back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta la máquina al nivel de asistencia deseado.", "Sube a la plataforma para los pies y agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros.", "Mantén el pecho arriba y los hombros atrás, activa el core y flexiona ligeramente las rodillas.", "Levanta el cuerpo flexionando los codos y llevándolos hacia abajo, en dirección a los costados.", "Continúa subiendo hasta que la barbilla quede por encima de la barra.", "Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Dominada Supina Cerrada con Lastre', 'weighted-close-grip-chin-up-on-dip-cage.gif', 'back', '["Stand in front of the dip cage and grab the parallel bars with an underhand grip, hands shoulder-width apart.", "Hang from the bars with your arms fully extended, feet off the ground, and body straight.", "Engage your back muscles and pull your body up towards the bars, keeping your elbows close to your sides.", "Continue pulling until your chin is above the bars, then pause for a moment.", "Slowly lower your body back down to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."]', '["Ponte de pie frente a la jaula de fondos y agarra las barras paralelas con un agarre supino, con las manos separadas a la altura de los hombros.", "Cuélgate de las barras con los brazos completamente extendidos, los pies levantados del suelo y el cuerpo recto.", "Activa los músculos de la espalda y tira de tu cuerpo hacia arriba en dirección a las barras, manteniendo los codos cerca de los costados.", "Continúa tirando hasta que tu barbilla quede por encima de las barras, luego haz una pausa de un momento.", "Baja lentamente el cuerpo de nuevo a la posición inicial, extendiendo completamente los brazos.", "Repite el número de repeticiones deseado."]'),
  ('Dominada Tras Nuca', 'rear-pull-up.gif', 'back', '["Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart.", "Hang from the bar with your arms fully extended and your body straight.", "Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body.", "Continue pulling until your chin is above the bar.", "Pause for a moment at the top, then slowly lower your body back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Sujeta la barra de dominadas con un agarre prono, un poco más ancho que la altura de los hombros.", "Cuélgate de la barra con los brazos completamente extendidos y el cuerpo recto.", "Activa los músculos de la espalda y tira de tu cuerpo hacia arriba, hacia la barra, manteniendo los codos cerca del cuerpo.", "Continúa subiendo hasta que la barbilla quede por encima de la barra.", "Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Dominada Tras Nuca con Agarre Abierto', 'wide-grip-rear-pull-up.gif', 'back', '["Grab the pull-up bar with a wide overhand grip, hands slightly wider than shoulder-width apart.", "Hang from the bar with your arms fully extended and your body straight.", "Engage your back muscles and pull your body up towards the bar, leading with your chest.", "Continue pulling until your chin is above the bar.", "Pause for a moment at the top, then slowly lower your body back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Agarra la barra de dominadas con un agarre prono amplio, las manos un poco más separadas que la anchura de los hombros.", "Cuélgate de la barra con los brazos completamente extendidos y el cuerpo recto.", "Activa los músculos de la espalda y tira de tu cuerpo hacia la barra, llevando el pecho por delante.", "Continúa subiendo hasta que la barbilla quede por encima de la barra.", "Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Dominadas con Agarre Neutro Cerrado', 'chin-ups-narrow-parallel-grip.gif', 'back', '["Hang from a pull-up bar with a narrow parallel grip, palms facing towards you.", "Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body.", "Continue pulling until your chin is above the bar.", "Pause for a moment at the top, then slowly lower your body back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Cuélgate de una barra de dominadas con un agarre paralelo estrecho, con las palmas hacia ti.", "Activa los músculos de la espalda y tira de tu cuerpo hacia arriba, hacia la barra, manteniendo los codos cerca del cuerpo.", "Continúa subiendo hasta que la barbilla quede por encima de la barra.", "Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Dominadas con Pies Apoyados en Banco', 'bench-pull-ups.gif', 'back', '["Position yourself under a bar or a sturdy horizontal surface that is at chest height.", "Grab the bar or surface with an overhand grip, slightly wider than shoulder-width apart.", "Hang with your arms fully extended and your body straight.", "Pull your chest towards the bar or surface by squeezing your shoulder blades together and bending your elbows.", "Continue pulling until your chin is above the bar or surface.", "Lower yourself back down to the starting position with control.", "Repeat for the desired number of repetitions."]', '["Colócate debajo de una barra o una superficie horizontal resistente que esté a la altura del pecho.", "Sujeta la barra o la superficie con agarre prono, un poco más separado que el ancho de los hombros.", "Cuélgate con los brazos completamente extendidos y el cuerpo recto.", "Lleva el pecho hacia la barra o la superficie juntando los omóplatos y flexionando los codos.", "Continúa tirando hasta que la barbilla quede por encima de la barra o la superficie.", "Baja de nuevo a la posición inicial con control.", "Repite el número de repeticiones deseado."]'),
  ('Elevaciones Alternas de Brazos sobre Fitball', 'exercise-ball-alternating-arm-ups.gif', 'back', '["Sit on the stability ball with your feet flat on the ground and your back straight.", "Hold a dumbbell in each hand with your palms facing inwards and your arms extended down by your sides.", "Engage your core and slowly lift one arm up towards your shoulder, keeping your elbow slightly bent.", "Pause for a moment at the top, then slowly lower your arm back down to the starting position.", "Repeat the movement with the other arm.", "Continue alternating arms for the desired number of repetitions."]', '["Siéntate en el balón de estabilidad con los pies planos en el suelo y la espalda recta.", "Sujeta una mancuerna en cada mano con las palmas hacia adentro y los brazos extendidos hacia abajo a los lados.", "Activa el core y levanta lentamente un brazo hacia el hombro, manteniendo el codo ligeramente flexionado.", "Haz una pausa breve en la parte más alta, luego baja lentamente el brazo de vuelta a la posición inicial.", "Repite el movimiento con el otro brazo.", "Continúa alternando los brazos durante el número de repeticiones deseado."]'),
  ('Elevación de Codos (Flexión Inversa)', 'elbow-lift-reverse-push-up.gif', 'back', '["Start by lying face down on the ground with your legs extended and your hands placed directly under your shoulders.", "Engage your core and press through your palms to lift your upper body off the ground, keeping your elbows close to your sides.", "Pause at the top for a moment, squeezing your upper back muscles.", "Slowly lower your body back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Comienza tumbado boca abajo en el suelo con las piernas extendidas y las manos colocadas justo debajo de los hombros.", "Activa el core y presiona con las palmas para levantar la parte superior del cuerpo del suelo, manteniendo los codos cerca de los costados.", "Haz una pausa por un momento en la parte superior, apretando los músculos de la espalda alta.", "Baja lentamente el cuerpo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación de Piernas Boca Abajo sobre Fitball', 'exercise-ball-prone-leg-raise.gif', 'back', '["Lie face down on a mat with your legs extended and your toes resting on top of the stability ball.", "Place your hands on the ground, shoulder-width apart, and engage your core muscles.", "Keeping your legs straight, slowly lift them off the ground, using your lower back and glutes to raise them as high as possible.", "Pause for a moment at the top, then slowly lower your legs back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate boca abajo sobre una esterilla con las piernas extendidas y los dedos de los pies apoyados sobre el balón de estabilidad.", "Coloca las manos en el suelo, separadas a la altura de los hombros, y activa el abdomen.", "Manteniendo las piernas rectas, levántalas lentamente del suelo, usando la zona lumbar y los glúteos para elevarlas tan alto como sea posible.", "Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación en Y con Mancuernas en Banco Inclinado', 'dumbbell-incline-y-raise.gif', 'back', '["Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing inwards.", "Lean forward slightly and let your arms hang straight down, keeping a slight bend in your elbows.", "Raise your arms out to the sides and up in a Y shape until they are parallel to the ground.", "Pause for a moment at the top, then slowly lower your arms back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta un banco inclinado a un ángulo de 45 grados y siéntate en él con una mancuerna en cada mano, con las palmas hacia adentro.", "Inclínate ligeramente hacia adelante y deja que los brazos cuelguen rectos hacia abajo, manteniendo una ligera flexión en los codos.", "Levanta los brazos hacia los lados y hacia arriba formando una Y hasta que queden paralelos al suelo.", "Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevador en Anillas', 'elevator.gif', 'back', null, null),
  ('Encogimientos con Mancuernas en Banco Declinado', 'dumbbell-decline-shrug.gif', 'back', '["Set up a decline bench at a 45-degree angle.", "Lie face down on the bench with your chest and stomach resting against it.", "Hold a dumbbell in each hand with your arms fully extended towards the floor.", "Keeping your arms straight, raise your shoulders towards your ears as high as possible.", "Hold the contraction for a moment, then slowly lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta un banco declinado a un ángulo de 45 grados.", "Túmbate boca abajo en el banco con el pecho y el abdomen apoyados contra él.", "Sostén una mancuerna en cada mano con los brazos completamente extendidos hacia el suelo.", "Manteniendo los brazos rectos, levanta los hombros hacia las orejas lo más alto posible.", "Mantén la contracción por un momento, luego baja lentamente las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Encogimientos con Mancuernas en Banco Inclinado', 'dumbbell-incline-shrug.gif', 'back', '["Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand.", "Place your feet flat on the ground and let your arms hang straight down with your palms facing your body.", "Keeping your arms straight, shrug your shoulders up towards your ears as high as possible.", "Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta un banco inclinado a un ángulo de 45 grados y siéntate en él con una mancuerna en cada mano.", "Coloca los pies planos sobre el suelo y deja que los brazos cuelguen rectos hacia abajo con las palmas hacia el cuerpo.", "Manteniendo los brazos rectos, encoge los hombros hacia las orejas lo más alto posible.", "Mantén la contracción por un momento, luego baja lentamente los hombros de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Encogimientos de Hombros con Banda Elástica', 'band-shrug.gif', 'back', '["Stand with your feet shoulder-width apart and place the band under your feet, holding the ends with your hands.", "Keep your arms straight and relaxed, and let the band hang in front of your thighs.", "Engage your traps by shrugging your shoulders upward, lifting the band as high as possible.", "Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y coloca la banda bajo los pies, sosteniendo los extremos con las manos.", "Mantén los brazos rectos y relajados, y deja que la banda cuelgue frente a los muslos.", "Activa los trapecios encogiendo los hombros hacia arriba, levantando la banda lo más alto posible.", "Mantén la contracción por un momento, luego baja lentamente los hombros de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Encogimientos de Hombros con Barra', 'barbell-shrug.gif', 'back', '["Stand with your feet shoulder-width apart and hold a barbell in front of you with an overhand grip.", "Keep your arms straight and your back straight throughout the exercise.", "Lift your shoulders up towards your ears as high as possible, squeezing your traps at the top.", "Hold for a moment, then slowly lower your shoulders back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra frente a ti con un agarre pronado.", "Mantén los brazos rectos y la espalda recta durante todo el ejercicio.", "Levanta los hombros hacia las orejas lo más alto posible, apretando los trapecios en la parte alta.", "Mantén la posición por un momento y luego baja lentamente los hombros de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Encogimientos de Hombros en Máquina Smith', 'smith-shrug.gif', 'back', '["Stand with your feet shoulder-width apart and your knees slightly bent.", "Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart.", "Keep your arms straight and your shoulders relaxed.", "Lift your shoulders up towards your ears, squeezing your traps at the top.", "Hold for a moment, then slowly lower your shoulders back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.", "Agarra la barra con un agarre pronado, con las manos un poco más separadas que el ancho de los hombros.", "Mantén los brazos rectos y los hombros relajados.", "Levanta los hombros hacia las orejas, contrayendo los trapecios en la parte alta.", "Mantén la posición por un momento y luego baja lentamente los hombros de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Encogimientos de Hombros en Polea', 'cable-shrug.gif', 'back', '["Stand facing the cable machine with your feet shoulder-width apart.", "Grasp the cable handles with an overhand grip and let your arms hang down in front of you.", "Keeping your arms straight, shrug your shoulders up towards your ears.", "Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.", "Sujeta las agarraderas del cable con un agarre prono y deja que los brazos cuelguen frente a ti.", "Manteniendo los brazos rectos, encoge los hombros hacia las orejas.", "Mantén la contracción por un momento, luego baja lentamente los hombros de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Encogimientos en Máquina sin Agarre', 'lever-gripless-shrug.gif', 'back', '["Adjust the seat height and position yourself on the leverage machine.", "Grasp the handles with your palms facing inwards and your arms fully extended.", "Keeping your back straight, exhale and elevate your shoulders as high as possible.", "Hold the contraction for a brief moment, then inhale and slowly lower your shoulders back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta la altura del asiento y colócate en la máquina de palanca.", "Sujeta las asas con las palmas hacia adentro y los brazos completamente extendidos.", "Manteniendo la espalda recta, exhala y eleva los hombros tan alto como sea posible.", "Mantén la contracción por un momento breve, luego inhala y baja lentamente los hombros de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Esfinge (Estiramiento)', 'sphinx.gif', 'back', '["Lie face down on the ground with your forearms flat on the floor, elbows directly under your shoulders.", "Engage your core and lift your chest off the ground, keeping your forearms and toes on the floor.", "Hold this position for a few seconds, making sure to keep your neck in a neutral position.", "Slowly lower your chest back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate boca abajo en el suelo con los antebrazos planos sobre el piso y los codos justo debajo de los hombros.", "Activa el core y levanta el pecho del suelo, manteniendo los antebrazos y los dedos de los pies en el piso.", "Mantén esta posición durante unos segundos, asegurándote de mantener el cuello en una posición neutral.", "Baja lentamente el pecho de nuevo a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Estiramiento de Columna Sentado', 'spine-stretch.gif', 'back', '["Sit on the ground with your legs extended in front of you.", "Place your hands on the ground behind you, fingers pointing towards your body.", "Engage your core and slowly lean back, keeping your back straight.", "Continue leaning back until you feel a stretch in your spine.", "Hold the stretch for a few seconds, then slowly return to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en el suelo con las piernas extendidas frente a ti.", "Coloca las manos en el suelo detrás de ti, con los dedos apuntando hacia tu cuerpo.", "Activa el core e inclínate lentamente hacia atrás, manteniendo la espalda recta.", "Sigue inclinándote hacia atrás hasta que sientas un estiramiento en la columna.", "Mantén el estiramiento durante unos segundos, luego regresa lentamente a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Estiramiento de Dorsal a 1 Brazo contra la Pared', 'one-arm-against-wall.gif', 'back', '["Stand facing a wall with your feet shoulder-width apart.", "Extend one arm straight out in front of you and place your palm against the wall.", "Engage your core and lean your body forward, keeping your arm straight and your back flat.", "Slowly push against the wall with your palm, activating your lat muscles.", "Hold the position for a few seconds, then release and repeat with the other arm."]', '["Ponte de pie frente a una pared con los pies separados a la altura de los hombros.", "Extiende un brazo recto hacia adelante y coloca la palma contra la pared.", "Activa el core e inclina el cuerpo hacia adelante, manteniendo el brazo recto y la espalda plana.", "Empuja lentamente la pared con la palma, activando los dorsales.", "Mantén la posición durante unos segundos, luego suelta y repite con el otro brazo."]'),
  ('Estiramiento de Dorsal con Fitball', 'exercise-ball-lat-stretch.gif', 'back', '["Sit on a stability ball with your feet flat on the ground and your back straight.", "Hold a dumbbell in one hand and extend your arm straight up overhead.", "Slowly lean to the opposite side, feeling a stretch in your lat muscle.", "Hold the stretch for 20-30 seconds, then return to the starting position.", "Repeat on the other side."]', '["Siéntate sobre un balón de estabilidad con los pies apoyados en el suelo y la espalda recta.", "Sujeta una mancuerna con una mano y extiende el brazo recto por encima de la cabeza.", "Inclínate lentamente hacia el lado opuesto, sintiendo un estiramiento en el músculo dorsal.", "Mantén el estiramiento durante 20-30 segundos, luego vuelve a la posición inicial.", "Repite del otro lado."]'),
  ('Estiramiento de Dorsal de Rodillas', 'kneeling-lat-stretch.gif', 'back', '["Kneel on the ground with your knees hip-width apart and your toes pointing back.", "Extend your arms overhead and interlace your fingers.", "Keeping your back straight, slowly lean to the right side, feeling a stretch in your left lat muscle.", "Hold the stretch for 20-30 seconds, then return to the starting position.", "Repeat the stretch on the left side, leaning to the left and feeling a stretch in your right lat muscle.", "Continue alternating sides for the desired number of repetitions."]', '["Arrodíllate en el suelo con las rodillas separadas a la altura de las caderas y los dedos de los pies apuntando hacia atrás.", "Extiende los brazos por encima de la cabeza y entrelaza los dedos.", "Manteniendo la espalda recta, inclínate lentamente hacia el lado derecho, sintiendo un estiramiento en el dorsal izquierdo.", "Mantén el estiramiento durante 20-30 segundos, luego vuelve a la posición inicial.", "Repite el estiramiento en el lado izquierdo, inclinándote hacia la izquierda y sintiendo un estiramiento en el dorsal derecho.", "Continúa alternando lados durante el número de repeticiones deseado."]'),
  ('Estiramiento de Espalda Alta', 'upper-back-stretch.gif', 'back', '["Stand up straight with your feet shoulder-width apart.", "Extend your arms straight in front of you, parallel to the ground.", "Interlace your fingers and rotate your palms away from your body.", "Slowly raise your arms overhead, keeping them straight and parallel to each other.", "As you raise your arms, squeeze your shoulder blades together.", "Hold the stretch for 15-30 seconds, then release and repeat."]', '["Ponte de pie con la espalda recta y los pies separados a la altura de los hombros.", "Extiende los brazos rectos frente a ti, paralelos al suelo.", "Entrelaza los dedos y gira las palmas alejándolas de tu cuerpo.", "Eleva lentamente los brazos por encima de la cabeza, manteniéndolos rectos y paralelos entre sí.", "Mientras elevas los brazos, aprieta los omóplatos entre sí.", "Mantén el estiramiento de 15 a 30 segundos, luego suelta y repite."]'),
  ('Estiramiento de Espalda con Rodillo', 'roller-back-stretch.gif', 'back', '["Start by sitting on the ground with your legs extended in front of you.", "Place the roller perpendicular to your body, just below your glutes.", "Slowly roll your body backwards, allowing the roller to move up your back.", "Continue rolling until the roller reaches your upper back.", "Pause for a moment, then slowly roll back to the starting position.", "Repeat for the desired number of repetitions."]', '["Comienza sentándote en el suelo con las piernas extendidas frente a ti.", "Coloca el rodillo perpendicular a tu cuerpo, justo debajo de los glúteos.", "Rueda lentamente el cuerpo hacia atrás, dejando que el rodillo se desplace hacia arriba por tu espalda.", "Continúa rodando hasta que el rodillo llegue a la parte superior de tu espalda.", "Haz una pausa por un momento y luego rueda lentamente de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Estiramiento de Pectoral por Detrás de la Espalda', 'back-pec-stretch.gif', 'back', '["Stand tall with your feet shoulder-width apart.", "Extend your arms straight out in front of you, parallel to the ground.", "Cross your arms in front of your body, with your right arm over your left arm.", "Interlock your fingers and rotate your palms away from your body.", "Slowly raise your arms up and away from your body, feeling a stretch in your back and chest.", "Hold the stretch for 15-30 seconds, then release.", "Repeat on the opposite side."]', '["Ponte de pie con la espalda recta y los pies separados a la altura de los hombros.", "Extiende los brazos rectos frente a ti, paralelos al suelo.", "Cruza los brazos frente al cuerpo, con el brazo derecho sobre el brazo izquierdo.", "Entrelaza los dedos y gira las palmas alejándolas del cuerpo.", "Levanta lentamente los brazos hacia arriba y alejándolos del cuerpo, sintiendo un estiramiento en la espalda y el pecho.", "Mantén el estiramiento durante 15-30 segundos, luego suelta.", "Repite del lado opuesto."]'),
  ('Estiramiento Lateral de Dorsal con Rodillo', 'roller-side-lat-stretch.gif', 'back', '["Stand with your feet shoulder-width apart and hold the roller with both hands in front of your body.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight.", "Extend your arms forward and roll the roller down towards your feet, feeling a stretch in your lats.", "Hold the stretch for a few seconds, then slowly roll the roller back up to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y sujeta el rodillo con ambas manos frente al cuerpo.", "Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.", "Extiende los brazos hacia delante y rueda el rodillo hacia los pies, sintiendo un estiramiento en los dorsales.", "Mantén el estiramiento durante unos segundos, luego rueda el rodillo lentamente de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Estiramiento Lateral de Dorsal Tumbado sobre Fitball', 'exercise-ball-lying-side-lat-stretch.gif', 'back', '["Lie on your side with your legs extended and your head supported by the stability ball.", "Place your top arm on the ball for stability.", "Reach your top arm overhead and allow your torso to rotate slightly.", "Feel the stretch in your lat muscles on the side of your body.", "Hold the stretch for 20-30 seconds, then switch sides and repeat."]', '["Túmbate de lado con las piernas extendidas y la cabeza apoyada sobre el balón de estabilidad.", "Coloca el brazo de arriba sobre el balón para mantener la estabilidad.", "Extiende el brazo de arriba por encima de la cabeza y permite que tu torso gire ligeramente.", "Siente el estiramiento en los músculos dorsales del costado de tu cuerpo.", "Mantén el estiramiento durante 20-30 segundos, luego cambia de lado y repite."]'),
  ('Estiramiento Lateral de Pie', 'standing-lateral-stretch.gif', 'back', '["Stand with your feet shoulder-width apart and your knees slightly bent.", "Extend your arms straight out to the sides, parallel to the ground.", "Slowly lean your upper body to one side, feeling a stretch in your side and lats.", "Hold the stretch for 15-30 seconds.", "Return to the starting position and repeat on the other side.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.", "Extiende los brazos hacia los lados, paralelos al suelo.", "Inclina lentamente la parte superior del cuerpo hacia un lado, sintiendo un estiramiento en el costado y los dorsales.", "Mantén el estiramiento durante 15-30 segundos.", "Regresa a la posición inicial y repite del otro lado.", "Repite el número de repeticiones deseado."]'),
  ('Estiramiento Lateral Tumbado en el Suelo', 'side-lying-floor-stretch.gif', 'back', '["Lie on your side with your legs straight and your bottom arm extended straight overhead.", "Bend your top knee and place your foot on the ground in front of your bottom leg.", "Reach your top arm over your head and grab onto something stable, like a wall or a piece of furniture.", "Slowly lift your bottom leg off the ground, keeping it straight, until you feel a stretch in your side.", "Hold the stretch for 20-30 seconds, then slowly lower your leg back down.", "Repeat on the other side."]', '["Túmbate de lado con las piernas rectas y el brazo de abajo extendido recto por encima de la cabeza.", "Dobla la rodilla de arriba y coloca el pie en el suelo frente a la pierna de abajo.", "Extiende el brazo de arriba por encima de la cabeza y agárrate a algo estable, como una pared o un mueble.", "Levanta lentamente la pierna de abajo del suelo, manteniéndola recta, hasta sentir un estiramiento en el costado.", "Mantén el estiramiento durante 20-30 segundos, luego baja lentamente la pierna de nuevo.", "Repite del otro lado."]'),
  ('Estiramiento Lumbar con Fitball (Pirámide)', 'exercise-ball-lower-back-stretch-pyramid.gif', 'back', '["Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.", "Slowly walk your feet forward, rolling the ball down your back until your lower back is resting on the ball.", "Place your hands behind your head or cross them over your chest.", "Engage your core and slowly lower your upper body towards the ground, allowing your lower back to stretch over the ball.", "Hold the stretch for a few seconds, then slowly return to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en el balón de estabilidad con los pies planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados.", "Camina lentamente hacia adelante con los pies, haciendo rodar el balón por tu espalda hasta que tu zona lumbar quede apoyada sobre el balón.", "Coloca las manos detrás de la cabeza o crúzalas sobre el pecho.", "Activa el core y baja lentamente la parte superior del cuerpo hacia el suelo, permitiendo que tu zona lumbar se estire sobre el balón.", "Mantén el estiramiento durante unos segundos, luego regresa lentamente a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Estiramiento Lumbar Sentado', 'seated-lower-back-stretch.gif', 'back', '["Sit on the edge of a chair with your feet flat on the ground.", "Place your hands on your thighs or on the sides of the chair for support.", "Slowly lean forward from your hips, keeping your back straight.", "Feel the stretch in your lower back and hold for 20-30 seconds.", "Slowly return to the starting position and repeat for the desired number of repetitions."]', '["Siéntate en el borde de una silla con los pies planos sobre el suelo.", "Coloca las manos sobre los muslos o a los lados de la silla para apoyarte.", "Inclínate lentamente hacia delante desde la cadera, manteniendo la espalda recta.", "Siente el estiramiento en la zona lumbar y mantén la posición durante 20-30 segundos.", "Regresa lentamente a la posición inicial y repite el número de repeticiones deseado."]'),
  ('Extensión Lumbar en el Suelo', 'lower-back-curl.gif', 'back', '["Lie flat on your stomach with your legs extended and your arms by your sides.", "Engage your glutes and hamstrings, and slowly lift your upper body off the ground, curling your back upwards.", "Pause for a moment at the top, then slowly lower your upper body back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate boca abajo con las piernas extendidas y los brazos a los lados del cuerpo.", "Activa los glúteos y los isquiotibiales, y eleva lentamente la parte superior del cuerpo del suelo, curvando la espalda hacia arriba.", "Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Extensión Lumbar en Máquina', 'lever-back-extension.gif', 'back', '["Adjust the machine to fit your body size and range of motion.", "Sit on the machine with your back against the pad and your feet secured.", "Place your hands on the handles or grip bars.", "Engage your core and slowly lean forward, allowing your back to round slightly.", "Pause for a moment at the bottom position, feeling a stretch in your lower back.", "Using your back muscles, slowly raise your torso back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta la máquina según el tamaño de tu cuerpo y tu rango de movimiento.", "Siéntate en la máquina con la espalda apoyada en la almohadilla y los pies asegurados.", "Coloca las manos en las asas o en las barras de agarre.", "Activa el core e inclínate lentamente hacia adelante, permitiendo que la espalda se redondee ligeramente.", "Haz una pausa breve en la posición baja, sintiendo un estiramiento en la zona lumbar.", "Usando los músculos de la espalda, levanta lentamente el torso de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Extensión Lumbar sobre Fitball', 'back-extension-on-exercise-ball.gif', 'back', '["Place the stability ball on the ground and lie face down on top of it, with your hips resting on the ball and your feet against a wall or other stable surface.", "Position your hands behind your head or crossed over your chest.", "Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line from your head to your heels.", "Pause for a moment at the top, then slowly lower your upper body back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Coloca el balón de estabilidad en el suelo y túmbate boca abajo sobre él, con las caderas apoyadas en el balón y los pies contra una pared u otra superficie estable.", "Coloca las manos detrás de la cabeza o cruzadas sobre el pecho.", "Activa el core y levanta lentamente la parte superior del cuerpo del balón, extendiendo la espalda hasta que tu cuerpo forme una línea recta desde la cabeza hasta los talones.", "Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Extensión Lumbar sobre Fitball con Brazos Extendidos', 'exercise-ball-back-extension-with-arms-extended.gif', 'back', '["Place the stability ball on the ground and lie face down on top of it, with your hips resting on the ball and your feet against a wall for stability.", "Extend your arms straight out in front of you, with your palms facing down.", "Engage your core and slowly lift your upper body off the ball, keeping your back straight and your neck in line with your spine.", "Pause for a moment at the top, then slowly lower your upper body back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Coloca el balón de estabilidad en el suelo y túmbate boca abajo sobre él, con las caderas apoyadas en el balón y los pies contra una pared para mayor estabilidad.", "Extiende los brazos rectos hacia adelante, con las palmas hacia abajo.", "Activa el core y levanta lentamente la parte superior del cuerpo del balón, manteniendo la espalda recta y el cuello alineado con la columna.", "Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Extensión Lumbar sobre Fitball con Manos tras la Cabeza', 'exercise-ball-back-extension-with-hands-behind-head.gif', 'back', '["Place the stability ball on the ground and lie face down on top of it with your hips resting on the ball.", "Position your feet against a wall or other stable surface for support.", "Cross your arms behind your head, with your hands touching the back of your head.", "Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line from your head to your hips.", "Pause for a moment at the top of the movement, then slowly lower your upper body back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Coloca el balón de estabilidad en el suelo y túmbate boca abajo sobre él con las caderas apoyadas en el balón.", "Coloca los pies contra una pared u otra superficie estable para apoyarte.", "Cruza los brazos detrás de la cabeza, con las manos tocando la parte de atrás de la cabeza.", "Activa el core y levanta lentamente la parte superior del cuerpo del balón, extendiendo la espalda hasta que tu cuerpo forme una línea recta desde la cabeza hasta las caderas.", "Haz una pausa breve en la parte alta del movimiento, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Extensión Lumbar sobre Fitball con Rodillas Elevadas', 'exercise-ball-back-extension-with-knees-off-ground.gif', 'back', '["Place the stability ball on the ground and lie face down on top of it, with your hips resting on the ball and your feet against a wall for stability.", "Position your hands behind your head or crossed over your chest.", "Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line from your head to your heels.", "Pause for a moment at the top, then slowly lower your upper body back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Coloca el balón de estabilidad en el suelo y túmbate boca abajo sobre él, con las caderas apoyadas en el balón y los pies contra una pared para mayor estabilidad.", "Coloca las manos detrás de la cabeza o cruzadas sobre el pecho.", "Activa el core y levanta lentamente la parte superior del cuerpo del balón, extendiendo la espalda hasta que tu cuerpo forme una línea recta desde la cabeza hasta los talones.", "Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Extensión Lumbar sobre Fitball con Rotación', 'exercise-ball-back-extension-with-rotation.gif', 'back', '["Start by lying face down on the stability ball with your hips resting on the ball and your feet firmly planted on the ground.", "Place your hands behind your head or cross them over your chest.", "Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line from your head to your heels.", "Pause for a moment at the top, then slowly rotate your torso to one side, keeping your hips and legs stable.", "Return to the center and repeat the rotation to the other side.", "Lower your upper body back down to the starting position and repeat for the desired number of repetitions."]', '["Comienza tumbado boca abajo sobre el balón de estabilidad, con las caderas apoyadas en el balón y los pies firmemente apoyados en el suelo.", "Coloca las manos detrás de la cabeza o crúzalas sobre el pecho.", "Activa el core y levanta lentamente la parte superior del cuerpo del balón, extendiendo la espalda hasta que tu cuerpo forme una línea recta desde la cabeza hasta los talones.", "Haz una pausa por un momento en la parte superior, luego gira lentamente el torso hacia un lado, manteniendo las caderas y las piernas estables.", "Vuelve al centro y repite el giro hacia el otro lado.", "Baja la parte superior del cuerpo de vuelta a la posición inicial y repite el número de repeticiones deseado."]'),
  ('Fondos Escapulares', 'scapula-dips.gif', 'back', '["Start by standing with your feet shoulder-width apart and your arms extended in front of you.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight.", "Lower your body by bending your elbows and retracting your shoulder blades, as if you are trying to squeeze a pencil between them.", "Pause for a moment at the bottom, then push through your hands to extend your elbows and return to the starting position.", "Repeat for the desired number of repetitions."]', '["Comienza de pie con los pies separados a la altura de los hombros y los brazos extendidos frente a ti.", "Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.", "Baja el cuerpo doblando los codos y retrayendo las escápulas, como si intentaras apretar un lápiz entre ellas.", "Haz una pausa por un momento en la posición baja, luego empuja con las manos para extender los codos y volver a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Front Lever (Repeticiones)', 'front-lever-reps.gif', 'back', '["Hang from a pull-up bar with an overhand grip, palms facing away from you.", "Engage your core and pull your shoulder blades down and back.", "Keeping your body straight, lift your legs up until they are parallel to the ground.", "Hold this position for as long as you can, aiming for 10-20 seconds.", "Slowly lower your legs back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Cuélgate de una barra de dominadas con agarre prono, palmas hacia afuera.", "Activa el core y lleva los omóplatos hacia abajo y atrás.", "Manteniendo el cuerpo recto, levanta las piernas hasta que queden paralelas al suelo.", "Mantén esta posición todo el tiempo que puedas, intentando llegar a 10-20 segundos.", "Baja lentamente las piernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Hiperextensión con Lastre sobre Fitball', 'weighted-hyperextension-on-stability-ball.gif', 'back', '["Position yourself face down on a stability ball with your hips resting on the ball and your feet against a wall for stability.", "Place your hands behind your head or cross them over your chest.", "Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line.", "Pause for a moment at the top, then slowly lower your upper body back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Colócate boca abajo sobre un balón de estabilidad con las caderas apoyadas en el balón y los pies contra una pared para mayor estabilidad.", "Coloca las manos detrás de la cabeza o crúzalas sobre el pecho.", "Activa el core y levanta lentamente la parte superior del cuerpo del balón, extendiendo la espalda hasta que tu cuerpo forme una línea recta.", "Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Inclinación Pélvica de Pie', 'standing-pelvic-tilt.gif', 'back', '["Stand with your feet shoulder-width apart and your knees slightly bent.", "Place your hands on your hips or let them hang by your sides.", "Engage your core muscles and tilt your pelvis forward, pushing your lower back towards the wall behind you.", "Hold the position for a few seconds, then release and return to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.", "Coloca las manos sobre las caderas o déjalas colgar a los lados.", "Activa los músculos del core e inclina la pelvis hacia adelante, empujando la zona lumbar hacia la pared detrás de ti.", "Mantén la posición durante unos segundos, luego suelta y vuelve a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Jalón a 1 Brazo de Rodillas con Banda Elástica', 'band-kneeling-one-arm-pulldown.gif', 'back', '["Attach the band to a sturdy anchor point above your head.", "Kneel down and hold the band with one hand, palm facing down.", "Extend your arm fully overhead, keeping your elbow slightly bent.", "Engage your lat muscles and pull the band down towards your side, bringing your elbow towards your ribcage.", "Pause for a moment at the bottom, then slowly release the tension and return to the starting position.", "Repeat for the desired number of repetitions, then switch sides."]', '["Sujeta la banda a un punto de anclaje resistente por encima de tu cabeza.", "Arrodíllate y sostén la banda con una mano, con la palma hacia abajo.", "Extiende el brazo por completo por encima de la cabeza, manteniendo el codo ligeramente flexionado.", "Activa los dorsales y tira de la banda hacia el costado, llevando el codo hacia las costillas.", "Haz una pausa por un momento en la parte inferior, luego suelta lentamente la tensión y regresa a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de lado."]'),
  ('Jalón a 1 Brazo en Máquina con Agarre Abierto', 'lever-one-arm-lateral-wide-pulldown.gif', 'back', '["Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor.", "Grasp the handle with an overhand grip and fully extend your arm, keeping a slight bend in your elbow.", "Pull the handle down and across your body towards your opposite hip, squeezing your lat muscle at the bottom of the movement.", "Slowly return the handle to the starting position, fully extending your arm.", "Repeat for the desired number of repetitions, then switch sides."]', '["Ajusta la altura del asiento y colócate en la máquina con el pecho contra la almohadilla y los pies planos en el suelo.", "Sujeta el asa con un agarre prono y extiende el brazo por completo, manteniendo una ligera flexión en el codo.", "Tira del asa hacia abajo y a través del cuerpo en dirección a la cadera opuesta, apretando el dorsal en la parte baja del movimiento.", "Devuelve lentamente el asa a la posición inicial, extendiendo el brazo por completo.", "Repite el número de repeticiones deseado, luego cambia de lado."]'),
  ('Jalón a 1 Brazo en Polea', 'cable-one-arm-pulldown.gif', 'back', '["Attach a single handle to a high pulley cable machine.", "Stand facing the machine with your feet shoulder-width apart.", "Grasp the handle with an overhand grip and extend your arm fully.", "Keep your back straight and your core engaged.", "Pull the handle down towards your side while keeping your elbow close to your body.", "Pause for a moment at the bottom of the movement, squeezing your lat muscle.", "Slowly release the handle back to the starting position.", "Repeat for the desired number of repetitions.", "Switch sides and repeat the exercise with the other arm."]', '["Sujeta una agarradera individual a una máquina de cable con polea alta.", "Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.", "Sujeta la agarradera con un agarre prono y extiende el brazo por completo.", "Mantén la espalda recta y el core activado.", "Jala la agarradera hacia abajo en dirección al costado, manteniendo el codo cerca del cuerpo.", "Haz una pausa por un momento en la parte baja del movimiento, apretando el dorsal.", "Suelta lentamente la agarradera de vuelta a la posición inicial.", "Repite el número de repeticiones deseado.", "Cambia de lado y repite el ejercicio con el otro brazo."]'),
  ('Jalón al Pecho Alterno en Polea', 'alternate-lateral-pulldown.gif', 'back', '["Sit on the cable machine with your back straight and feet flat on the ground.", "Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.", "Lean back slightly and pull the handles towards your chest, squeezing your shoulder blades together.", "Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en la máquina de cable con la espalda recta y los pies apoyados en el suelo.", "Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros.", "Inclínate ligeramente hacia atrás y lleva las agarraderas hacia el pecho, juntando los omóplatos.", "Haz una pausa por un momento en el punto máximo del movimiento, luego suelta lentamente las agarraderas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Jalón al Pecho en Máquina con Agarre Supino', 'reverse-grip-machine-lat-pulldown.gif', 'back', '["Adjust the seat height and position yourself on the machine with your knees under the pads and your feet flat on the ground.", "Grasp the handles with an underhand grip, slightly wider than shoulder-width apart.", "Sit upright with your chest out and shoulders back, maintaining a slight arch in your lower back.", "Pull the handles down towards your chest, squeezing your shoulder blades together.", "Pause for a moment at the bottom of the movement, then slowly release the handles back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta la altura del asiento y colócate en la máquina con las rodillas debajo de las almohadillas y los pies planos en el suelo.", "Sujeta las asas con un agarre supino, un poco más separadas que la altura de los hombros.", "Siéntate erguido con el pecho hacia afuera y los hombros hacia atrás, manteniendo un ligero arco en la zona lumbar.", "Tira de las asas hacia el pecho, juntando las escápulas.", "Haz una pausa breve en la parte baja del movimiento, luego suelta lentamente las asas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Jalón al Pecho en Máquina de Discos con Agarre Supino', 'lever-reverse-grip-lateral-pulldown.gif', 'back', '["Adjust the seat height and position yourself on the machine with your knees under the pads and your feet flat on the ground.", "Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.", "Sit upright with your chest out and shoulders back, maintaining a slight arch in your lower back.", "Pull the handles down towards your chest, leading with your elbows and squeezing your shoulder blades together.", "Pause for a moment at the bottom of the movement, then slowly release the handles back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta la altura del asiento y colócate en la máquina con las rodillas debajo de las almohadillas y los pies planos en el suelo.", "Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros.", "Siéntate erguido con el pecho hacia afuera y los hombros hacia atrás, manteniendo un ligero arco en la zona lumbar.", "Tira de las asas hacia el pecho, liderando con los codos y juntando los omóplatos.", "Haz una pausa breve en la parte baja del movimiento, luego suelta lentamente las asas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Jalón al Pecho en Polea con Agarre Neutro Doble', 'twin-handle-parallel-grip-lat-pulldown.gif', 'back', '["Adjust the seat height and position yourself facing the cable machine.", "Grasp the handles with an overhand grip, hands shoulder-width apart.", "Sit down and position your thighs under the thigh pads, keeping your feet flat on the floor.", "Lean back slightly and keep your chest up, maintaining a neutral spine.", "Pull the handles down towards your upper chest, squeezing your shoulder blades together.", "Pause for a moment at the bottom of the movement, feeling the contraction in your lats.", "Slowly release the handles and return to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta la altura del asiento y colócate de frente a la máquina de cable.", "Agarra las asas con un agarre prono, con las manos separadas a la altura de los hombros.", "Siéntate y coloca los muslos debajo de las almohadillas para muslos, manteniendo los pies planos sobre el suelo.", "Inclínate ligeramente hacia atrás y mantén el pecho elevado, conservando una columna neutral.", "Tira de las asas hacia la parte superior del pecho, apretando los omóplatos entre sí.", "Haz una pausa por un momento en la parte inferior del movimiento, sintiendo la contracción en los dorsales.", "Suelta lentamente las asas y vuelve a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Jalón al Pecho en Polea con Agarre Supino', 'cable-underhand-pulldown.gif', 'back', '["Adjust the cable machine so that the pulldown bar is at a height above your head.", "Sit down on the seat and grab the pulldown bar with an underhand grip, hands slightly wider than shoulder-width apart.", "Keep your back straight and lean back slightly.", "Pull the bar down towards your chest, squeezing your shoulder blades together.", "Pause for a moment at the bottom of the movement, then slowly release the bar back up to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta la máquina de cable de modo que la barra de jalón quede a una altura por encima de tu cabeza.", "Siéntate y agarra la barra de jalón con un agarre supino, con las manos un poco más separadas que el ancho de los hombros.", "Mantén la espalda recta e inclínate ligeramente hacia atrás.", "Jala la barra hacia el pecho, apretando los omóplatos entre sí.", "Haz una pausa por un momento en la parte baja del movimiento y luego suelta lentamente la barra de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Jalón al Pecho en Polea con Barra en V', 'cable-lateral-pulldown-with-v-bar.gif', 'back', '["Sit down on the cable pulldown machine and grab the v-bar attachment with an overhand grip.", "Adjust the knee pad so that your thighs are secured under it.", "Keep your back straight and lean back slightly.", "Pull the v-bar down towards your upper chest while keeping your elbows close to your body.", "Squeeze your back muscles at the bottom of the movement.", "Slowly return the v-bar to the starting position and repeat for the desired number of repetitions."]', '["Siéntate en la máquina de jalón de cable y agarra el accesorio en V con un agarre prono.", "Ajusta la almohadilla de rodillas para que tus muslos queden asegurados debajo de ella.", "Mantén la espalda recta e inclínate ligeramente hacia atrás.", "Jala el accesorio en V hacia la parte superior del pecho manteniendo los codos cerca del cuerpo.", "Aprieta los músculos de la espalda en la parte baja del movimiento.", "Regresa lentamente el accesorio en V a la posición inicial y repite el número de repeticiones deseado."]'),
  ('Jalón al Pecho en Polea con Barra Pro Lat', 'cable-pulldown-pro-lat-bar.gif', 'back', '["Adjust the seat height so that your thighs are parallel to the ground and your feet are flat on the floor.", "Grasp the lat bar with an overhand grip, slightly wider than shoulder-width apart.", "Sit down and lean back slightly, keeping your chest up and your back straight.", "Pull the bar down towards your chest, squeezing your shoulder blades together.", "Pause for a moment at the bottom of the movement, then slowly release the bar back up to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta la altura del asiento para que tus muslos queden paralelos al suelo y tus pies queden apoyados planos en el suelo.", "Sujeta la barra de jalón con un agarre prono, un poco más separado que el ancho de los hombros.", "Siéntate e inclínate ligeramente hacia atrás, manteniendo el pecho elevado y la espalda recta.", "Jala la barra hacia el pecho, apretando los omóplatos entre sí.", "Haz una pausa por un momento en la parte baja del movimiento y luego suelta lentamente la barra de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Jalón al Pecho en Polea con Cuerda', 'cable-lateral-pulldown-with-rope-attachment.gif', 'back', '["Attach a rope attachment to the cable machine at a high position.", "Stand facing the machine with your feet shoulder-width apart.", "Grasp the rope with an overhand grip, palms facing each other.", "Keep your back straight and lean slightly back.", "Pull the rope down towards your sides, squeezing your shoulder blades together.", "Pause for a moment at the bottom of the movement.", "Slowly release the tension and allow the rope to return to the starting position.", "Repeat for the desired number of repetitions."]', '["Sujeta un accesorio de cuerda a la máquina de cable en una posición alta.", "Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.", "Sujeta la cuerda con un agarre prono, con las palmas una frente a la otra.", "Mantén la espalda recta e inclínate ligeramente hacia atrás.", "Jala la cuerda hacia los costados, apretando los omóplatos entre sí.", "Haz una pausa por un momento en la parte baja del movimiento.", "Libera lentamente la tensión y permite que la cuerda vuelva a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Jalón con Banda Anclada Atrás y Agarre Cerrado', 'band-fixed-back-close-grip-pulldown.gif', 'back', '["Attach the band to a fixed point above you, such as a pull-up bar or sturdy beam.", "Sit down on a bench or chair facing the band, with your feet flat on the ground and your knees bent.", "Grasp the band with a close grip, palms facing towards you.", "Keep your back straight and engage your core.", "Pull the band down towards your chest, squeezing your shoulder blades together.", "Pause for a moment at the bottom of the movement, feeling the contraction in your lats.", "Slowly release the band back to the starting position, maintaining control throughout the movement.", "Repeat for the desired number of repetitions."]', '["Sujeta la banda a un punto fijo por encima de ti, como una barra de dominadas o una viga resistente.", "Siéntate en un banco o silla frente a la banda, con los pies apoyados en el suelo y las rodillas flexionadas.", "Agarra la banda con un agarre cerrado, con las palmas hacia ti.", "Mantén la espalda recta y activa el core.", "Tira de la banda hacia el pecho, juntando los omóplatos.", "Haz una pausa por un momento en la parte inferior del movimiento, sintiendo la contracción en los dorsales.", "Suelta lentamente la banda de vuelta a la posición inicial, manteniendo el control durante todo el movimiento.", "Repite el número de repeticiones deseado."]'),
  ('Jalón con Banda Anclada Atrás y Agarre Supino', 'band-fixed-back-underhand-pulldown.gif', 'back', '["Attach the band to a sturdy anchor point above your head.", "Stand facing the anchor point with your feet shoulder-width apart.", "Grasp the band with an underhand grip, hands slightly wider than shoulder-width apart.", "Step back to create tension in the band, keeping your arms fully extended.", "Engage your core and squeeze your shoulder blades together.", "Pull the band down towards your chest, leading with your elbows.", "Pause for a moment at the bottom of the movement, feeling the contraction in your lats.", "Slowly release the tension in the band and return to the starting position.", "Repeat for the desired number of repetitions."]', '["Sujeta la banda a un punto de anclaje resistente por encima de tu cabeza.", "Ponte de pie frente al punto de anclaje con los pies separados a la altura de los hombros.", "Agarra la banda con un agarre supino, con las manos un poco más separadas que el ancho de los hombros.", "Da un paso atrás para generar tensión en la banda, manteniendo los brazos completamente extendidos.", "Activa el core y junta los omóplatos.", "Tira de la banda hacia el pecho, guiando el movimiento con los codos.", "Haz una pausa por un momento en la parte inferior del movimiento, sintiendo la contracción en los dorsales.", "Suelta lentamente la tensión de la banda y regresa a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Jalón con Banda Elástica y Agarre Cerrado', 'band-close-grip-pulldown.gif', 'back', '["Attach the band to a high anchor point, such as a pull-up bar or sturdy beam.", "Stand facing the anchor point and grab the band with an underhand grip, hands shoulder-width apart.", "Step back to create tension in the band, keeping your feet hip-width apart.", "Engage your core and keep your back straight as you pull the band down towards your chest, squeezing your shoulder blades together.", "Pause for a moment at the bottom of the movement, then slowly release the band back to the starting position.", "Repeat for the desired number of repetitions."]', '["Sujeta la banda a un punto de anclaje alto, como una barra de dominadas o una viga resistente.", "Ponte de pie frente al punto de anclaje y agarra la banda con un agarre supino, con las manos separadas a la altura de los hombros.", "Da un paso atrás para generar tensión en la banda, manteniendo los pies separados a la altura de las caderas.", "Activa el core y mantén la espalda recta mientras tiras de la banda hacia el pecho, juntando los omóplatos.", "Haz una pausa por un momento en la parte inferior del movimiento, luego suelta lentamente la banda de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Jalón con Banda Elástica y Agarre Supino', 'band-underhand-pulldown.gif', 'back', '["Attach the band to a high anchor point, such as a pull-up bar or sturdy beam.", "Stand facing the anchor point with your feet shoulder-width apart.", "Grasp the band with an underhand grip, hands slightly wider than shoulder-width apart.", "Extend your arms fully overhead, keeping your elbows slightly bent.", "Engage your lats and pull the band down towards your chest, squeezing your shoulder blades together.", "Pause for a moment at the bottom of the movement, then slowly release the tension and return to the starting position.", "Repeat for the desired number of repetitions."]', '["Sujeta la banda a un punto de anclaje alto, como una barra de dominadas o una viga resistente.", "Ponte de pie frente al punto de anclaje con los pies separados a la altura de los hombros.", "Agarra la banda con un agarre supino, con las manos un poco más separadas que el ancho de los hombros.", "Extiende completamente los brazos por encima de la cabeza, manteniendo los codos ligeramente flexionados.", "Activa los dorsales y tira de la banda hacia abajo en dirección al pecho, juntando los omóplatos.", "Haz una pausa breve en la parte baja del movimiento, luego libera lentamente la tensión y vuelve a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Jalón con Brazos Rectos en Polea', 'cable-straight-arm-pulldown.gif', 'back', '["Attach a straight bar to the high pulley of a cable machine.", "Stand facing the machine with your feet shoulder-width apart.", "Grasp the bar with an overhand grip, keeping your arms straight and your palms facing down.", "Engage your lats and pull the bar down towards your thighs, keeping your arms straight throughout the movement.", "Pause for a moment at the bottom, then slowly return the bar to the starting position.", "Repeat for the desired number of repetitions."]', '["Coloca una barra recta en la polea alta de una máquina de cable.", "Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.", "Sujeta la barra con un agarre prono, manteniendo los brazos rectos y las palmas hacia abajo.", "Activa los dorsales y tira de la barra hacia abajo, hacia los muslos, manteniendo los brazos rectos durante todo el movimiento.", "Haz una pausa por un momento en la parte baja y luego regresa lentamente la barra a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Jalón con Brazos Rectos en Polea con Cuerda', 'cable-straight-arm-pulldown-with-rope.gif', 'back', '["Attach a rope to the cable machine at the highest setting.", "Stand facing the machine with your feet shoulder-width apart.", "Grasp the rope with both hands, palms facing down.", "Extend your arms fully in front of you, keeping your elbows slightly bent.", "Engage your lats and slowly pull the rope down towards your thighs, keeping your arms straight.", "Pause for a moment at the bottom, then slowly release the tension and return to the starting position.", "Repeat for the desired number of repetitions."]', '["Sujeta una cuerda a la máquina de cable en el ajuste más alto.", "Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.", "Agarra la cuerda con ambas manos, con las palmas hacia abajo.", "Extiende completamente los brazos frente a ti, manteniendo los codos ligeramente flexionados.", "Activa los dorsales y tira lentamente de la cuerda hacia abajo, hacia los muslos, manteniendo los brazos rectos.", "Haz una pausa por un momento en la parte inferior, luego suelta lentamente la tensión y regresa a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Jalón con Brazos Rectos en Polea en Banco Inclinado', 'cable-incline-pushdown-0172.gif', 'back', '["Attach a straight bar to a high pulley cable machine.", "Stand facing away from the machine with your feet shoulder-width apart.", "Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart.", "Lean forward slightly and keep your back straight.", "Pull the bar down towards your thighs by extending your elbows.", "Pause for a moment at the bottom, then slowly return the bar to the starting position.", "Repeat for the desired number of repetitions."]', '["Sujeta una barra recta a una máquina de cable con polea alta.", "Ponte de pie de espaldas a la máquina con los pies separados a la altura de los hombros.", "Sujeta la barra con un agarre prono, con las manos un poco más separadas que el ancho de los hombros.", "Inclínate ligeramente hacia adelante y mantén la espalda recta.", "Jala la barra hacia abajo en dirección a tus muslos extendiendo los codos.", "Haz una pausa por un momento en la parte baja y luego regresa lentamente la barra a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Jalón Cruzado en Polea Doble', 'cable-cross-over-lateral-pulldown.gif', 'back', '["Attach a cable handle to each side of a cable machine at shoulder height.", "Stand in the middle of the machine with your feet shoulder-width apart.", "Grasp the handles with an overhand grip and step back to create tension in the cables.", "Lean forward slightly from the hips, keeping your back straight and your chest up.", "Pull the handles down and across your body, squeezing your shoulder blades together.", "Pause for a moment at the bottom of the movement, then slowly return to the starting position.", "Repeat for the desired number of repetitions."]', '["Coloca una agarradera de cable en cada lado de una máquina de cable a la altura de los hombros.", "Ponte de pie en el centro de la máquina con los pies separados a la altura de los hombros.", "Sujeta las agarraderas con agarre prono y da un paso hacia atrás para crear tensión en los cables.", "Inclínate ligeramente hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado.", "Tira de las agarraderas hacia abajo y a través del cuerpo, juntando los omóplatos.", "Haz una pausa breve en la parte más baja del movimiento, luego vuelve lentamente a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Jalón en Polea Doble de Recorrido Completo', 'cable-lat-pulldown-full-range-of-motion.gif', 'back', '["Sit on the lat pulldown machine with your knees positioned under the pads.", "Grasp the cable bar with an overhand grip, slightly wider than shoulder-width apart.", "Lean back slightly and keep your chest up, maintaining a slight arch in your lower back.", "Pull the bar down towards your upper chest, squeezing your shoulder blades together.", "Pause for a moment at the bottom of the movement, then slowly release the bar back to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en la máquina de jalón al pecho con las rodillas colocadas debajo de las almohadillas.", "Sujeta la barra del cable con un agarre prono, un poco más separado que el ancho de los hombros.", "Inclínate ligeramente hacia atrás y mantén el pecho elevado, conservando un ligero arco en la zona lumbar.", "Jala la barra hacia la parte superior del pecho, apretando los omóplatos entre sí.", "Haz una pausa por un momento en la parte baja del movimiento y luego suelta lentamente la barra de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('London Bridge (Cuerda)', 'london-bridge.gif', 'back', '["Attach the rope to a high anchor point.", "Stand facing away from the anchor point with your feet shoulder-width apart.", "Grasp the rope with an overhand grip, palms facing down.", "Lean forward slightly, keeping your back straight and core engaged.", "Pull the rope towards your body, squeezing your shoulder blades together.", "Pause for a moment at the peak of the movement, then slowly release the tension and return to the starting position.", "Repeat for the desired number of repetitions."]', '["Sujeta la cuerda a un punto de anclaje alto.", "Ponte de pie de espaldas al punto de anclaje con los pies separados a la altura de los hombros.", "Agarra la cuerda con un agarre prono, con las palmas hacia abajo.", "Inclínate ligeramente hacia adelante, manteniendo la espalda recta y el core activado.", "Tira de la cuerda hacia tu cuerpo, juntando las escápulas.", "Haz una pausa por un momento en el punto más alto del movimiento, luego libera lentamente la tensión y regresa a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Muscle-Up con Impulso (Kipping)', 'kipping-muscle-up.gif', 'back', '["Start by hanging from a pull-up bar with an overhand grip, hands slightly wider than shoulder-width apart.", "Engage your core and use a swinging motion to generate momentum.", "As you swing forward, pull your chest towards the bar, using your lats and biceps to initiate the movement.", "Continue the upward motion until your chest reaches the bar, then transition into a dip position by pushing down on the bar and extending your arms.", "Lower yourself back down to the starting position by bending your arms and controlling the descent.", "Repeat for the desired number of repetitions."]', '["Comienza colgándote de una barra de dominadas con un agarre prono, con las manos un poco más separadas que el ancho de los hombros.", "Activa el core y usa un movimiento de balanceo para generar impulso.", "Mientras te balanceas hacia adelante, tira del pecho hacia la barra, usando los dorsales y los bíceps para iniciar el movimiento.", "Continúa el movimiento ascendente hasta que el pecho llegue a la barra, luego pasa a una posición de fondos empujando hacia abajo en la barra y extendiendo los brazos.", "Bájate de vuelta a la posición inicial flexionando los brazos y controlando el descenso.", "Repite el número de repeticiones deseado."]'),
  ('Muscle-Up en Anillas', 'muscle-up.gif', 'back', '["Start by hanging from a pull-up bar with your palms facing away from you and your arms fully extended.", "Engage your core and pull your body up towards the bar, leading with your chest.", "As you reach the top of the movement, transition your grip so that your palms are facing towards you.", "Continue pulling yourself up until your chest is above the bar and your arms are fully flexed.", "Reverse the movement by slowly lowering yourself back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Comienza colgándote de una barra de dominadas con las palmas hacia afuera y los brazos completamente extendidos.", "Activa el core y tira de tu cuerpo hacia arriba, hacia la barra, guiando con el pecho.", "Al llegar a la parte alta del movimiento, cambia el agarre de modo que las palmas queden hacia ti.", "Sigue tirando hacia arriba hasta que el pecho quede por encima de la barra y los brazos estén completamente flexionados.", "Invierte el movimiento bajando lentamente de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Muscle-Up en Anillas con Lastre', 'weighted-muscle-up.gif', 'back', '["Start by hanging from a pull-up bar with your palms facing away from you and your hands slightly wider than shoulder-width apart.", "Engage your core and pull your body up towards the bar, leading with your chest.", "As you reach the top of the movement, transition your grip so that your palms are facing towards you.", "Continue pulling yourself up until your chest reaches the bar, then pause for a moment.", "Slowly lower yourself back down to the starting position, maintaining control throughout the movement.", "Repeat for the desired number of repetitions."]', '["Comienza colgándote de una barra de dominadas con las palmas mirando hacia afuera y las manos un poco más separadas que la anchura de los hombros.", "Activa el core y tira de tu cuerpo hacia arriba, hacia la barra, guiando con el pecho.", "Al llegar a la parte alta del movimiento, cambia el agarre de modo que las palmas queden hacia ti.", "Continúa subiendo hasta que el pecho llegue a la barra, luego haz una pausa de un momento.", "Baja lentamente de nuevo a la posición inicial, manteniendo el control durante todo el movimiento.", "Repite el número de repeticiones deseado."]'),
  ('Muscle-Up en Barra', 'muscle-up-on-vertical-bar.gif', 'back', '["Start by hanging from a vertical bar with your palms facing away from you and your arms fully extended.", "Engage your core and pull your body up towards the bar, leading with your chest.", "As you pull yourself up, lean back slightly and bring your elbows towards your sides.", "Continue pulling until your chest reaches the bar and your elbows are fully bent.", "Pause for a moment at the top, then slowly lower yourself back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Comienza colgándote de una barra vertical con las palmas hacia afuera y los brazos completamente extendidos.", "Activa el core y tira de tu cuerpo hacia arriba, hacia la barra, guiando con el pecho.", "Al subir tu cuerpo, inclínate ligeramente hacia atrás y lleva los codos hacia los costados.", "Sigue tirando hasta que el pecho llegue a la barra y los codos estén completamente flexionados.", "Haz una pausa breve en la parte más alta, luego baja lentamente de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Muscle-Up en Barra con Lastre', 'weighted-muscle-up-on-bar.gif', 'back', '["Start by hanging from a pull-up bar with your palms facing away from you and your hands slightly wider than shoulder-width apart.", "Engage your core and pull your shoulder blades down and back.", "Bend your elbows and pull your chest towards the bar, keeping your body straight.", "Once your chest reaches the bar, push down with your hands and drive your elbows back, lifting your body above the bar.", "Pause at the top of the movement, then slowly lower yourself back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Comienza colgándote de una barra de dominadas con las palmas mirando hacia afuera y las manos un poco más separadas que la anchura de los hombros.", "Activa el core y lleva los omóplatos hacia abajo y atrás.", "Flexiona los codos y tira del pecho hacia la barra, manteniendo el cuerpo recto.", "Cuando tu pecho llegue a la barra, empuja hacia abajo con las manos y lleva los codos hacia atrás, elevando el cuerpo por encima de la barra.", "Haz una pausa en la parte más alta del movimiento, luego baja lentamente de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Perro Boca Arriba (Yoga)', 'upward-facing-dog.gif', 'back', '["Lie face down on the floor with your legs extended behind you.", "Place your hands on the floor next to your lower ribs, fingers pointing forward.", "Press your hands firmly into the floor and straighten your arms, lifting your torso and thighs off the ground.", "Roll your shoulders back and down, opening your chest and lifting your gaze towards the ceiling.", "Hold this position for a few breaths, then slowly lower your body back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate boca abajo en el suelo con las piernas extendidas detrás de ti.", "Coloca las manos en el suelo junto a las costillas inferiores, con los dedos apuntando hacia adelante.", "Presiona las manos firmemente contra el suelo y estira los brazos, levantando el torso y los muslos del suelo.", "Lleva los hombros hacia atrás y hacia abajo, abriendo el pecho y elevando la mirada hacia el techo.", "Mantén esta posición durante unas cuantas respiraciones, luego baja lentamente el cuerpo de nuevo a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Plancha Lateral con Apertura Posterior con Mancuerna', 'dumbbell-side-plank-with-rear-fly.gif', 'back', '["Start by lying on your side with your legs extended and stacked on top of each other.", "Place your forearm on the ground directly below your shoulder, keeping your elbow bent at a 90-degree angle.", "Hold a dumbbell in your top hand, with your arm extended straight down towards the ground.", "Engage your core and lift your hips off the ground, creating a straight line from your head to your heels.", "While maintaining the side plank position, lift the dumbbell up towards the ceiling, squeezing your shoulder blades together.", "Lower the dumbbell back down to the starting position.", "Repeat for the desired number of repetitions, then switch sides."]', '["Comienza tumbado de lado con las piernas extendidas y apiladas una sobre la otra.", "Coloca el antebrazo en el suelo, justo debajo del hombro, manteniendo el codo flexionado en un ángulo de 90 grados.", "Sujeta una mancuerna con la mano de arriba, con el brazo extendido recto hacia el suelo.", "Activa el core y levanta las caderas del suelo, formando una línea recta desde la cabeza hasta los talones.", "Manteniendo la posición de plancha lateral, levanta la mancuerna hacia el techo, apretando los omóplatos entre sí.", "Baja la mancuerna de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de lado."]'),
  ('Pullover con Barra', 'barbell-pullover.gif', 'back', '["Lie flat on a bench with your head at one end and your feet on the floor.", "Hold a barbell with a shoulder-width grip and extend your arms straight above your chest.", "Keeping your arms straight, lower the barbell behind your head in a controlled manner until you feel a stretch in your lats.", "Pause for a moment, then raise the barbell back to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate boca arriba en un banco con la cabeza en un extremo y los pies en el suelo.", "Sujeta una barra con un agarre a la altura de los hombros y extiende los brazos rectos por encima del pecho.", "Manteniendo los brazos rectos, baja la barra detrás de la cabeza de forma controlada hasta sentir un estiramiento en los dorsales.", "Haz una pausa breve y luego levanta la barra de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Pullover con Barra y Agarre Abierto en Banco Declinado', 'barbell-decline-wide-grip-pullover.gif', 'back', '["Lie on a decline bench with your head lower than your hips and your feet secured.", "Hold a barbell with a wide grip and extend your arms straight above your chest.", "Lower the barbell behind your head in a controlled manner, keeping your arms straight.", "Pause for a moment, then raise the barbell back to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate en un banco declinado con la cabeza más baja que las caderas y los pies sujetos.", "Sujeta una barra con un agarre amplio y extiende los brazos rectos por encima del pecho.", "Baja la barra detrás de la cabeza de forma controlada, manteniendo los brazos rectos.", "Haz una pausa breve y luego levanta la barra de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Pullover con Barra y Brazos Flexionados', 'barbell-bent-arm-pullover.gif', 'back', '["Lie flat on a bench with your head at one end and your feet on the floor.", "Hold a barbell with a shoulder-width grip and extend your arms straight above your chest.", "Lower the barbell behind your head while keeping your arms slightly bent.", "Pause for a moment, then raise the barbell back to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate boca arriba en un banco con la cabeza en un extremo y los pies en el suelo.", "Sujeta una barra con un agarre a la altura de los hombros y extiende los brazos rectos por encima del pecho.", "Baja la barra detrás de la cabeza manteniendo los brazos ligeramente flexionados.", "Haz una pausa breve y luego levanta la barra de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Pullover con Barra y Brazos Flexionados en Banco Declinado', 'barbell-decline-bent-arm-pullover.gif', 'back', '["Lie down on a decline bench with your head lower than your hips and your feet secured.", "Hold a barbell with a pronated grip (palms facing away from you) and extend your arms straight above your chest.", "Lower the barbell behind your head in a controlled manner, keeping your arms slightly bent.", "Pause for a moment, then raise the barbell back to the starting position by contracting your lats.", "Repeat for the desired number of repetitions."]', '["Túmbate en un banco declinado con la cabeza más baja que las caderas y los pies sujetos.", "Sujeta una barra con un agarre pronado (palmas mirando hacia afuera) y extiende los brazos rectos por encima del pecho.", "Baja la barra detrás de la cabeza de forma controlada, manteniendo los brazos ligeramente flexionados.", "Haz una pausa breve y luego levanta la barra de vuelta a la posición inicial contrayendo los dorsales.", "Repite el número de repeticiones deseado."]'),
  ('Pullover con Barra y Press', 'barbell-pullover-to-press.gif', 'back', '["Lie flat on a bench with your head at one end and your feet on the ground.", "Hold the barbell with a pronated grip (palms facing away from you) and extend your arms straight above your chest.", "Keeping your arms straight, lower the barbell behind your head in an arc-like motion until you feel a stretch in your lats.", "Pause for a moment, then reverse the motion and press the barbell back to the starting position above your chest.", "Repeat for the desired number of repetitions."]', '["Túmbate boca arriba en un banco con la cabeza en un extremo y los pies en el suelo.", "Sujeta una barra con un agarre pronado (palmas mirando hacia afuera) y extiende los brazos rectos por encima del pecho.", "Manteniendo los brazos rectos, baja la barra detrás de la cabeza con un movimiento en forma de arco hasta sentir un estiramiento en los dorsales.", "Haz una pausa breve, luego invierte el movimiento y empuja la barra de vuelta a la posición inicial por encima del pecho.", "Repite el número de repeticiones deseado."]'),
  ('Pullover con Barra Z y Brazos Flexionados', 'ez-bar-lying-bent-arms-pullover.gif', 'back', '["Lie flat on a bench with your head at one end and your feet on the floor.", "Hold the EZ barbell with a pronated grip (palms facing away from you) and your hands shoulder-width apart.", "Extend your arms straight above your chest, keeping a slight bend in your elbows.", "Lower the barbell in an arc motion behind your head, maintaining the slight bend in your elbows.", "Pause for a moment, then return the barbell to the starting position by reversing the arc motion.", "Repeat for the desired number of repetitions."]', '["Túmbate boca arriba en un banco con la cabeza en un extremo y los pies en el suelo.", "Sostén la barra EZ con agarre prono (palmas hacia afuera) y las manos separadas a la altura de los hombros.", "Extiende los brazos rectos por encima del pecho, manteniendo una ligera flexión en los codos.", "Baja la barra describiendo un arco detrás de la cabeza, manteniendo la ligera flexión en los codos.", "Haz una pausa breve, luego regresa la barra a la posición inicial invirtiendo el movimiento del arco.", "Repite el número de repeticiones deseado."]'),
  ('Pullover en Máquina', 'lever-pullover.gif', 'back', '["Adjust the seat and handles of the leverage machine to a comfortable position.", "Sit on the machine with your back against the pad and grasp the handles with an overhand grip.", "Keep your arms slightly bent and your core engaged.", "Slowly pull the handles towards your chest, squeezing your lats.", "Pause for a moment at the peak contraction, then slowly return to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta el asiento y las asas de la máquina de palanca a una posición cómoda.", "Siéntate en la máquina con la espalda apoyada en la almohadilla y sujeta las asas con un agarre prono.", "Mantén los brazos ligeramente flexionados y el core activado.", "Tira lentamente de las asas hacia el pecho, apretando los dorsales.", "Haz una pausa breve en el punto máximo de contracción, luego vuelve lentamente a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Recepción y Lanzamiento por Encima de la Cabeza con Balón Medicinal', 'medicine-ball-catch-and-overhead-throw.gif', 'back', '["Stand with your feet shoulder-width apart, holding a medicine ball in both hands at chest level.", "Bend your knees slightly and engage your core.", "Lower your body into a squat position, keeping your back straight and chest up.", "Explosively extend your hips and legs, while simultaneously throwing the medicine ball overhead.", "Release the ball at the top of the movement and catch it on the way down.", "Lower your body back into the squat position and repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo un balón medicinal con ambas manos a la altura del pecho.", "Flexiona ligeramente las rodillas y activa el core.", "Baja el cuerpo a una posición de sentadilla, manteniendo la espalda recta y el pecho hacia arriba.", "Extiende explosivamente las caderas y las piernas, mientras lanzas simultáneamente el balón medicinal por encima de la cabeza.", "Suelta el balón en la parte más alta del movimiento y atrápalo cuando vaya bajando.", "Baja de nuevo el cuerpo a la posición de sentadilla y repite el número de repeticiones deseado."]'),
  ('Remo a 1 Brazo con Kettlebell', 'kettlebell-one-arm-row.gif', 'back', '["Stand with your feet shoulder-width apart, holding a kettlebell in one hand with an overhand grip.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight and your core engaged.", "Pull the kettlebell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.", "Pause for a moment at the top, then slowly lower the kettlebell back down to the starting position.", "Repeat for the desired number of repetitions, then switch sides and repeat with the other arm."]', '["Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano en agarre prono.", "Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado.", "Tira de la pesa rusa hacia el pecho, manteniendo el codo cerca del cuerpo y juntando los omóplatos.", "Haz una pausa breve en lo alto, luego baja lentamente la pesa rusa de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de lado y repite con el otro brazo."]'),
  ('Remo a 1 Brazo con Mancuerna en Banco Inclinado y Agarre Supino', 'dumbbell-reverse-grip-incline-bench-one-arm-row.gif', 'back', '["Set up an incline bench at a 45-degree angle.", "Place a dumbbell on the floor next to the bench.", "Stand facing the bench with your feet shoulder-width apart.", "Bend at the waist and place your left knee and left hand on the bench for support.", "Pick up the dumbbell with your right hand using a reverse grip (palm facing down).", "Keep your back straight and your core engaged.", "Pull the dumbbell up towards your chest, keeping your elbow close to your body.", "Squeeze your back muscles at the top of the movement.", "Lower the dumbbell back down to the starting position in a controlled manner.", "Repeat for the desired number of repetitions.", "Switch sides and repeat the exercise with your left arm."]', '["Coloca un banco inclinado a un ángulo de 45 grados.", "Coloca una mancuerna en el suelo junto al banco.", "Ponte de pie frente al banco con los pies separados a la altura de los hombros.", "Inclínate desde la cintura y coloca la rodilla izquierda y la mano izquierda sobre el banco para apoyarte.", "Toma la mancuerna con la mano derecha usando un agarre inverso (con la palma hacia abajo).", "Mantén la espalda recta y el core activado.", "Tira de la mancuerna hacia el pecho, manteniendo el codo cerca del cuerpo.", "Aprieta los músculos de la espalda en la parte superior del movimiento.", "Baja la mancuerna de nuevo a la posición inicial de manera controlada.", "Repite el número de repeticiones deseado.", "Cambia de lado y repite el ejercicio con el brazo izquierdo."]'),
  ('Remo a 1 Brazo con Toalla', 'one-arm-towel-row.gif', 'back', '["Stand with your feet shoulder-width apart, knees slightly bent, and hold a towel with one hand.", "Bend forward at the waist, keeping your back straight and your core engaged.", "Extend your arm fully, allowing the towel to hang in front of you.", "Pull the towel towards your chest, squeezing your shoulder blades together.", "Pause for a moment at the top, then slowly lower the towel back to the starting position.", "Repeat for the desired number of repetitions, then switch arms."]', '["Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sujeta una toalla con una mano.", "Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y el core activado.", "Extiende completamente el brazo, dejando que la toalla cuelgue frente a ti.", "Tira de la toalla hacia el pecho, juntando los omóplatos.", "Haz una pausa breve en la parte más alta, luego baja lentamente la toalla de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de brazo."]'),
  ('Remo a 1 Brazo de Pie en Espaldera', 'bodyweight-standing-one-arm-row.gif', 'back', '["Stand with your feet shoulder-width apart, knees slightly bent, and hold a dumbbell in one hand.", "Bend forward at the hips, keeping your back straight and your core engaged.", "Let the dumbbell hang straight down in front of you, with your arm fully extended.", "Pull the dumbbell up towards your chest, keeping your elbow close to your body.", "Squeeze your shoulder blades together at the top of the movement.", "Lower the dumbbell back down to the starting position.", "Repeat for the desired number of repetitions, then switch sides."]', '["Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sujeta una mancuerna con una mano.", "Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado.", "Deja que la mancuerna cuelgue recta frente a ti, con el brazo completamente extendido.", "Tira de la mancuerna hacia el pecho, manteniendo el codo cerca del cuerpo.", "Junta los omóplatos en la parte superior del movimiento.", "Baja la mancuerna de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de lado."]'),
  ('Remo a 1 Brazo de Pie en Espaldera con Agarre Cerrado', 'bodyweight-standing-close-grip-one-arm-row.gif', 'back', '["Stand with your feet shoulder-width apart, knees slightly bent, and hold a dumbbell in one hand with a neutral grip.", "Bend forward at the hips, keeping your back straight and your core engaged.", "Pull the dumbbell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.", "Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.", "Repeat for the desired number of repetitions, then switch sides."]', '["Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sujeta una mancuerna en una mano con agarre neutro.", "Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado.", "Tira de la mancuerna hacia el pecho, manteniendo el codo cerca del cuerpo y juntando los omóplatos.", "Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de lado."]'),
  ('Remo a 1 Brazo de Pie en Espaldera con Toalla', 'bodyweight-standing-one-arm-row-with-towel.gif', 'back', '["Stand with your feet shoulder-width apart, knees slightly bent, and hold a towel with one hand.", "Bend forward at the hips, keeping your back straight and your core engaged.", "Pull the towel towards your chest, squeezing your shoulder blades together.", "Pause for a moment at the top, then slowly lower the towel back to the starting position.", "Repeat for the desired number of repetitions, then switch to the other arm."]', '["Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sujeta una toalla con una mano.", "Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado.", "Tira de la toalla hacia el pecho, juntando los omóplatos.", "Haz una pausa breve en la parte más alta, luego baja lentamente la toalla de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia al otro brazo."]'),
  ('Remo a 1 Brazo en Máquina Smith', 'smith-one-arm-row.gif', 'back', '["Adjust the height of the smith machine bar to waist level.", "Stand facing the smith machine with your feet shoulder-width apart.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight.", "Grasp the bar with one hand using an overhand grip, with your palm facing down.", "Keep your elbow close to your body and pull the bar towards your waist, squeezing your shoulder blades together.", "Pause for a moment at the top of the movement, then slowly lower the bar back to the starting position.", "Repeat for the desired number of repetitions, then switch to the other arm."]', '["Ajusta la altura de la barra de la máquina Smith a la altura de la cintura.", "Ponte de pie frente a la máquina Smith con los pies separados a la altura de los hombros.", "Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.", "Sujeta la barra con una mano usando un agarre prono, con la palma hacia abajo.", "Mantén el codo cerca del cuerpo y tira de la barra hacia la cintura, juntando las escápulas.", "Haz una pausa por un momento en la parte alta del movimiento, luego baja lentamente la barra de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia al otro brazo."]'),
  ('Remo Alto a 1 Brazo de Rodillas en Polea', 'cable-one-arm-straight-back-high-row-kneeling.gif', 'back', '["Attach a handle to a cable machine at waist height.", "Kneel down facing the cable machine and grab the handle with one hand.", "Keep your back straight and your core engaged.", "Pull the handle towards your chest, squeezing your shoulder blades together.", "Pause for a moment at the top of the movement.", "Slowly release the handle back to the starting position.", "Repeat for the desired number of repetitions.", "Switch sides and repeat the exercise with the other arm."]', '["Sujeta una agarradera a una máquina de cable a la altura de la cintura.", "Ponte de rodillas frente a la máquina de cable y agarra la agarradera con una mano.", "Mantén la espalda recta y el core activado.", "Jala la agarradera hacia el pecho, apretando los omóplatos entre sí.", "Haz una pausa breve en la parte alta del movimiento.", "Suelta lentamente la agarradera de vuelta a la posición inicial.", "Repite el número de repeticiones deseado.", "Cambia de lado y repite el ejercicio con el otro brazo."]'),
  ('Remo Alto a 1 Brazo en Máquina', 'lever-one-arm-lateral-high-row.gif', 'back', '["Adjust the seat height and position yourself facing the machine.", "Grasp the handle with one hand and keep your back straight.", "Pull the handle towards your body, keeping your elbow close to your side.", "Squeeze your back muscles at the top of the movement.", "Slowly release the handle back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta la altura del asiento y colócate frente a la máquina.", "Sujeta el asa con una mano y mantén la espalda recta.", "Tira del asa hacia el cuerpo, manteniendo el codo cerca del costado.", "Aprieta los músculos de la espalda en la parte superior del movimiento.", "Suelta lentamente la agarradera de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Remo Alto de Rodillas en Polea', 'cable-high-row-kneeling.gif', 'back', '["Attach a straight bar to a cable machine at chest height.", "Kneel down in front of the cable machine and grab the bar with an overhand grip, hands shoulder-width apart.", "Sit back on your heels, keeping your back straight and your core engaged.", "Pull the bar towards your upper abdomen, squeezing your shoulder blades together.", "Pause for a moment at the top of the movement, then slowly release the bar back to the starting position.", "Repeat for the desired number of repetitions."]', '["Sujeta una barra recta a una máquina de cable a la altura del pecho.", "Ponte de rodillas frente a la máquina de cable y agarra la barra con un agarre prono, con las manos separadas a la altura de los hombros.", "Siéntate sobre los talones, manteniendo la espalda recta y el core activado.", "Jala la barra hacia la parte superior del abdomen, apretando los omóplatos entre sí.", "Haz una pausa por un momento en la parte más alta del movimiento y luego suelta lentamente la barra de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Remo Alto Sentado en Polea con Agarre Supino y Espalda Recta', 'cable-reverse-grip-straight-back-seated-high-row.gif', 'back', '["Sit on the seat facing the cable machine with your feet flat on the floor.", "Grasp the cable attachment with an underhand grip, palms facing up, and your hands shoulder-width apart.", "Keep your back straight and lean slightly forward from your hips.", "Pull the cable towards your torso by retracting your shoulder blades and squeezing your back muscles.", "Pause for a moment at the peak of the contraction, then slowly release the cable back to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate frente a la máquina de cable con los pies apoyados planos en el suelo.", "Sujeta el accesorio del cable con un agarre supino, con las palmas hacia arriba y las manos separadas a la altura de los hombros.", "Mantén la espalda recta e inclínate ligeramente hacia adelante desde las caderas.", "Jala el cable hacia el torso retrayendo los omóplatos y apretando los músculos de la espalda.", "Haz una pausa breve en el punto máximo de la contracción, luego suelta lentamente el cable de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Remo Alto Sentado en Polea con Barra en V', 'cable-seated-high-row-v-bar.gif', 'back', '["Sit on the cable machine with your feet flat on the floor and your knees slightly bent.", "Grasp the v-bar attachment with an overhand grip, palms facing each other, and your hands shoulder-width apart.", "Keep your back straight and lean slightly forward from the hips.", "Pull the v-bar towards your torso by retracting your shoulder blades and squeezing your back muscles.", "Pause for a moment at the peak of the contraction, then slowly release the tension and return to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en la máquina de cable con los pies apoyados planos en el suelo y las rodillas ligeramente flexionadas.", "Sujeta el accesorio en V con un agarre prono, con las palmas una frente a la otra y las manos separadas a la altura de los hombros.", "Mantén la espalda recta e inclínate ligeramente hacia adelante desde las caderas.", "Jala el accesorio en V hacia el torso retrayendo los omóplatos y apretando los músculos de la espalda.", "Haz una pausa por un momento en el punto más alto de la contracción, luego libera lentamente la tensión y regresa a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Remo Bajo a 1 Brazo de Pie con Banda Elástica', 'band-one-arm-standing-low-row.gif', 'back', '["Attach the band to a stable anchor point at waist height.", "Stand facing the anchor point with your feet shoulder-width apart.", "Hold the band with one hand, palm facing inward, and step back to create tension in the band.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight.", "Pull the band towards your waist, squeezing your shoulder blades together.", "Pause for a moment at the top of the movement, then slowly release the band back to the starting position.", "Repeat for the desired number of repetitions, then switch sides."]', '["Sujeta la banda a un punto de anclaje estable a la altura de la cintura.", "Ponte de pie frente al punto de anclaje con los pies separados a la altura de los hombros.", "Sostén la banda con una mano, con la palma hacia adentro, y da un paso atrás para generar tensión en la banda.", "Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.", "Tira de la banda hacia la cintura, juntando los omóplatos.", "Haz una pausa por un momento en la parte superior del movimiento, luego suelta lentamente la banda de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de lado."]'),
  ('Remo con Barra en Banco Inclinado', 'barbell-incline-row-0049.gif', 'back', '["Set up an incline bench at a 45-degree angle.", "Lie face down on the bench with your chest against the pad and your feet flat on the ground.", "Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.", "Keep your back straight and your core engaged.", "Pull the barbell towards your chest, squeezing your shoulder blades together.", "Pause for a moment at the top, then slowly lower the barbell back to the starting position.", "Repeat for the desired number of repetitions."]', '["Coloca un banco inclinado a un ángulo de 45 grados.", "Túmbate boca abajo en el banco con el pecho apoyado en el respaldo y los pies planos sobre el suelo.", "Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.", "Mantén la espalda recta y el core activado.", "Tira de la barra hacia el pecho, juntando los omóplatos.", "Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Remo con Barra en Banco Inclinado y Agarre Supino', 'barbell-reverse-grip-incline-bench-row.gif', 'back', '["Set up an incline bench at a 45-degree angle.", "Sit on the bench facing the backrest with your chest against it.", "Grab the barbell with a reverse grip (palms facing down) and hands slightly wider than shoulder-width apart.", "Keep your back straight and core engaged.", "Pull the barbell towards your upper abdomen, squeezing your shoulder blades together.", "Pause for a moment at the top of the movement.", "Slowly lower the barbell back to the starting position.", "Repeat for the desired number of repetitions."]', '["Coloca un banco inclinado a un ángulo de 45 grados.", "Siéntate en el banco frente al respaldo con el pecho apoyado contra él.", "Sujeta la barra con un agarre invertido (palmas hacia abajo) y las manos un poco más separadas que el ancho de los hombros.", "Mantén la espalda recta y el core activado.", "Tira de la barra hacia la parte superior del abdomen, juntando los omóplatos.", "Haz una pausa breve en la parte alta del movimiento.", "Baja lentamente la barra de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Remo con Mancuernas en Banco Inclinado y Agarre Supino', 'dumbbell-reverse-grip-incline-bench-two-arm-row.gif', 'back', '["Set up an incline bench at a 45-degree angle.", "Sit on the bench with your chest against the backrest and your feet flat on the ground.", "Hold a dumbbell in each hand with an underhand grip.", "Lean forward and let your arms hang straight down, fully extended.", "Pull the dumbbells up towards your chest, squeezing your shoulder blades together.", "Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Coloca un banco inclinado a un ángulo de 45 grados.", "Siéntate en el banco con el pecho apoyado en el respaldo y los pies planos en el suelo.", "Sujeta una mancuerna en cada mano con agarre supino.", "Inclínate hacia adelante y deja que tus brazos cuelguen rectos hacia abajo, completamente extendidos.", "Tira de las mancuernas hacia arriba, hacia el pecho, apretando los omóplatos entre sí.", "Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Remo de Deltoides Posterior Tumbado con Mancuernas', 'dumbbell-lying-rear-delt-row.gif', 'back', '["Lie face down on a flat bench with a dumbbell in each hand, palms facing inwards.", "Extend your arms straight down towards the floor, keeping a slight bend in your elbows.", "Engaging your back muscles, lift the dumbbells up towards your chest, squeezing your shoulder blades together.", "Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate boca abajo en un banco plano con una mancuerna en cada mano, con las palmas hacia adentro.", "Extiende los brazos rectos hacia el suelo, manteniendo una ligera flexión en los codos.", "Activando los músculos de la espalda, levanta las mancuernas hacia el pecho, juntando los omóplatos.", "Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Remo de Pie con Giro en Polea con Barra en V', 'cable-standing-twist-row-v-bar.gif', 'back', '["Attach a v-bar attachment to a cable machine at chest height.", "Stand facing the cable machine with your feet shoulder-width apart.", "Grasp the v-bar with an overhand grip, palms facing down.", "Take a step back to create tension in the cable.", "Keep your back straight and core engaged throughout the exercise.", "Pull the v-bar towards your torso by retracting your shoulder blades and bending your elbows.", "As you pull, twist your torso to one side, squeezing your shoulder blades together.", "Pause for a moment at the top of the movement, feeling the contraction in your upper back.", "Slowly release the tension and return to the starting position, untwisting your torso.", "Repeat the movement for the desired number of repetitions, alternating the twisting direction with each rep."]', '["Coloca un accesorio en V en una máquina de cable a la altura del pecho.", "Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.", "Agarra el accesorio en V con un agarre prono, con las palmas hacia abajo.", "Da un paso atrás para crear tensión en el cable.", "Mantén la espalda recta y el core activado durante todo el ejercicio.", "Tira del accesorio en V hacia tu torso retrayendo los omóplatos y flexionando los codos.", "Mientras tiras, gira el torso hacia un lado, apretando los omóplatos entre sí.", "Haz una pausa breve en la parte alta del movimiento, sintiendo la contracción en la parte alta de la espalda.", "Suelta lentamente la tensión y regresa a la posición inicial, deshaciendo el giro del torso.", "Repite el movimiento el número de repeticiones deseado, alternando la dirección del giro en cada repetición."]'),
  ('Remo de Pie en Espaldera', 'bodyweight-standing-row.gif', 'back', '["Stand with your feet shoulder-width apart and knees slightly bent.", "Grasp a bar or handles with an overhand grip, palms facing down.", "Keep your back straight and core engaged.", "Pull the bar or handles towards your body, squeezing your shoulder blades together.", "Pause for a moment at the top of the movement.", "Slowly release and extend your arms back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.", "Sujeta una barra o las agarraderas con agarre prono, palmas hacia abajo.", "Mantén la espalda recta y el core activado.", "Tira de la barra o las agarraderas hacia el cuerpo, juntando los omóplatos.", "Haz una pausa breve en la parte alta del movimiento.", "Suelta lentamente y extiende los brazos de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Remo de Pie en Espaldera con Agarre Cerrado', 'bodyweight-standing-close-grip-row.gif', 'back', '["Stand with your feet shoulder-width apart and knees slightly bent.", "Bend forward at the waist, keeping your back straight and your core engaged.", "Extend your arms straight in front of you, gripping the bar or handles with a close grip.", "Pull the bar or handles towards your body, squeezing your shoulder blades together.", "Pause for a moment at the top of the movement, then slowly release and return to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.", "Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y el core activado.", "Extiende los brazos rectos frente a ti, sujetando la barra o las agarraderas con un agarre cerrado.", "Tira de la barra o las agarraderas hacia el cuerpo, juntando los omóplatos.", "Haz una pausa breve en la parte más alta del movimiento, luego suelta lentamente y vuelve a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Remo de Pie en Espaldera con Toalla', 'bodyweight-standing-row-with-towel.gif', 'back', '["Stand with your feet shoulder-width apart and hold a towel in front of you with both hands.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight.", "Pull the towel towards your chest, squeezing your shoulder blades together.", "Pause for a moment at the top, then slowly release the tension and return to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y sujeta una toalla frente a ti con ambas manos.", "Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.", "Tira de la toalla hacia el pecho, juntando los omóplatos.", "Haz una pausa por un momento en la parte superior, luego suelta lentamente la tensión y regresa a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Remo de Pie en Polea con Barra en V', 'cable-standing-row-v-bar.gif', 'back', '["Stand facing the cable machine with your feet shoulder-width apart.", "Grasp the v-bar attachment with an overhand grip, palms facing down.", "Keep your back straight and your core engaged.", "Pull the v-bar towards your body, squeezing your shoulder blades together.", "Pause for a moment at the peak of the movement, then slowly release the tension and return to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.", "Agarra el accesorio en V con un agarre prono, con las palmas hacia abajo.", "Mantén la espalda recta y el core activado.", "Tira del accesorio en V hacia tu cuerpo, apretando los omóplatos entre sí.", "Haz una pausa por un momento en el punto más alto del movimiento, luego libera lentamente la tensión y regresa a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Remo en Anillas', 'suspended-row.gif', 'back', '["Set up a suspension trainer at an appropriate height.", "Stand facing the anchor point with your feet shoulder-width apart.", "Hold the handles with an overhand grip, palms facing each other.", "Lean back, keeping your body straight and your heels on the ground.", "Pull your chest towards the handles, squeezing your shoulder blades together.", "Pause for a moment at the top, then slowly lower yourself back to the starting position.", "Repeat for the desired number of repetitions."]', '["Coloca un entrenador de suspensión a una altura adecuada.", "Ponte de pie frente al punto de anclaje con los pies separados a la altura de los hombros.", "Sostén las asas con un agarre prono, con las palmas mirándose entre sí.", "Inclínate hacia atrás, manteniendo el cuerpo recto y los talones en el suelo.", "Tira del pecho hacia las asas, apretando los omóplatos entre sí.", "Haz una pausa breve en la parte más alta, luego baja lentamente de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Remo en Barra T con Agarre Supino', 'lever-t-bar-reverse-grip-row.gif', 'back', '["Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor.", "Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.", "Keep your back straight and engage your core.", "Pull the handles towards your chest, squeezing your shoulder blades together.", "Pause for a moment at the top of the movement, then slowly release and extend your arms back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta la altura del asiento y colócate en la máquina con el pecho contra la almohadilla y los pies planos en el suelo.", "Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros.", "Mantén la espalda recta y activa el core.", "Tira de las asas hacia el pecho, juntando los omóplatos.", "Haz una pausa breve en la parte alta del movimiento, luego suelta lentamente y extiende los brazos de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Remo en Barra T con Pecho Apoyado', 'lever-reverse-t-bar-row.gif', 'back', '["Adjust the seat height and footplate position on the leverage machine.", "Sit on the machine with your chest against the pad and your feet flat on the footplate.", "Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.", "Keep your back straight and engage your core.", "Pull the handles towards your chest, squeezing your shoulder blades together.", "Pause for a moment at the top of the movement, then slowly release and extend your arms back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta la altura del asiento y la posición de la placa para los pies en la máquina de palanca.", "Siéntate en la máquina con el pecho contra la almohadilla y los pies planos sobre la placa para los pies.", "Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros.", "Mantén la espalda recta y activa el core.", "Tira de las asas hacia el pecho, juntando los omóplatos.", "Haz una pausa breve en la parte alta del movimiento, luego suelta lentamente y extiende los brazos de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Remo en Cuclillas en Espaldera', 'bodyweight-squatting-row.gif', 'back', '["Stand with your feet shoulder-width apart, holding onto a sturdy object or suspension trainer with your arms extended.", "Lower your body into a squat position, keeping your back straight and your knees behind your toes.", "From the squat position, pull your body up towards the object or suspension trainer, squeezing your shoulder blades together.", "Pause for a moment at the top, then slowly lower your body back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, sujetando un objeto resistente o un entrenador de suspensión con los brazos extendidos.", "Baja el cuerpo hacia una posición de sentadilla, manteniendo la espalda recta y las rodillas detrás de las puntas de los pies.", "Desde la posición de sentadilla, tira del cuerpo hacia arriba en dirección al objeto o al entrenador de suspensión, juntando los omóplatos.", "Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Remo en Cuclillas en Espaldera con Toalla', 'bodyweight-squatting-row-with-towel.gif', 'back', '["Stand with your feet shoulder-width apart, holding a towel in front of you with your palms facing down.", "Bend your knees and lower your body into a squat position, keeping your back straight and your chest up.", "As you lower into the squat, simultaneously pull the towel towards your chest, squeezing your shoulder blades together.", "Pause for a moment at the bottom of the squat, then slowly return to the starting position while extending your arms.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, sujetando una toalla frente a ti con las palmas hacia abajo.", "Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla, manteniendo la espalda recta y el pecho elevado.", "Mientras bajas a la sentadilla, tira simultáneamente de la toalla hacia el pecho, juntando los omóplatos.", "Haz una pausa breve en la parte más baja de la sentadilla, luego vuelve lentamente a la posición inicial mientras extiendes los brazos.", "Repite el número de repeticiones deseado."]'),
  ('Remo en Polea con Cuerda en Banco Inclinado', 'cable-rope-extension-incline-bench-row.gif', 'back', '["Set up an incline bench at a 45-degree angle and attach a cable machine to the low pulley.", "Attach a rope handle to the cable machine and sit on the incline bench facing the machine.", "Grab the rope handle with an overhand grip and lean forward, keeping your back straight.", "Extend your arms fully, pulling the rope towards your upper chest while keeping your elbows close to your body.", "Squeeze your shoulder blades together at the end of the movement.", "Slowly release the tension and return to the starting position.", "Repeat for the desired number of repetitions."]', '["Coloca un banco inclinado a un ángulo de 45 grados y sujeta una máquina de cable a la polea baja.", "Sujeta una agarradera de cuerda a la máquina de cable y siéntate en el banco inclinado frente a la máquina.", "Agarra la agarradera de cuerda con un agarre prono e inclínate hacia adelante, manteniendo la espalda recta.", "Extiende los brazos por completo, jalando la cuerda hacia la parte superior del pecho mientras mantienes los codos cerca del cuerpo.", "Aprieta los omóplatos al final del movimiento.", "Libera lentamente la tensión y vuelve a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Remo en Polea con Rotación de Palma', 'cable-palm-rotational-row.gif', 'back', '["Attach a handle to a cable machine at waist height.", "Stand facing the machine with your feet shoulder-width apart.", "Grasp the handle with an overhand grip, palms facing down.", "Step back to create tension on the cable, keeping your back straight and knees slightly bent.", "Pull the handle towards your body, rotating your palms to face upwards as you do so.", "Squeeze your shoulder blades together at the end of the movement.", "Slowly release the handle back to the starting position.", "Repeat for the desired number of repetitions."]', '["Sujeta una agarradera a una máquina de cable a la altura de la cintura.", "Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.", "Sujeta la agarradera con un agarre prono, con las palmas hacia abajo.", "Retrocede un paso para crear tensión en el cable, manteniendo la espalda recta y las rodillas ligeramente flexionadas.", "Jala la agarradera hacia el cuerpo, rotando las palmas hacia arriba mientras lo haces.", "Aprieta los omóplatos al final del movimiento.", "Suelta lentamente la agarradera de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Remo en Polea en Banco Inclinado', 'cable-incline-bench-row.gif', 'back', '["Set up an incline bench at a 45-degree angle and attach a cable handle to the low pulley.", "Sit on the bench facing the cable machine with your feet flat on the floor and your knees slightly bent.", "Grasp the cable handle with an overhand grip and extend your arms fully in front of you.", "Lean forward from your hips while keeping your back straight and your core engaged.", "Pull the cable handle towards your chest by retracting your shoulder blades and bending your elbows.", "Squeeze your back muscles at the top of the movement, then slowly extend your arms back to the starting position.", "Repeat for the desired number of repetitions."]', '["Coloca un banco inclinado a un ángulo de 45 grados y sujeta una agarradera de cable a la polea baja.", "Siéntate en el banco frente a la máquina de cable con los pies apoyados planos en el suelo y las rodillas ligeramente flexionadas.", "Sujeta la agarradera del cable con un agarre prono y extiende los brazos completamente frente a ti.", "Inclínate hacia adelante desde las caderas manteniendo la espalda recta y el core activado.", "Jala la agarradera del cable hacia el pecho retrayendo los omóplatos y flexionando los codos.", "Aprieta los músculos de la espalda en la parte más alta del movimiento y luego extiende lentamente los brazos de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Remo en Sentadilla en Polea con Cuerda', 'cable-squat-row-with-rope-attachment.gif', 'back', '["Attach a rope to a cable machine at waist height.", "Stand facing the cable machine with your feet shoulder-width apart.", "Bend your knees and lower your body into a squat position, keeping your back straight and chest up.", "Grasp the rope with an overhand grip, with your hands shoulder-width apart.", "Engage your core and pull the rope towards your body, squeezing your shoulder blades together.", "Keep your elbows close to your body and continue pulling until your hands reach your chest.", "Pause for a moment at the top of the movement, then slowly release the rope and extend your arms back to the starting position.", "Repeat for the desired number of repetitions."]', '["Sujeta una cuerda a una máquina de cable a la altura de la cintura.", "Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.", "Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla, manteniendo la espalda recta y el pecho elevado.", "Agarra la cuerda con un agarre prono, con las manos separadas a la altura de los hombros.", "Activa el core y tira de la cuerda hacia tu cuerpo, apretando los omóplatos entre sí.", "Mantén los codos cerca del cuerpo y continúa tirando hasta que las manos lleguen a tu pecho.", "Haz una pausa breve en la parte alta del movimiento, luego suelta lentamente la cuerda y extiende los brazos de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Remo Inclinado a 1 Brazo con Barra', 'barbell-one-arm-bent-over-row.gif', 'back', '["Stand with your feet shoulder-width apart, knees slightly bent, and hold a barbell with one hand using an overhand grip.", "Bend forward at the hips, keeping your back straight and your head in a neutral position.", "Pull the barbell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.", "Lower the barbell back down to the starting position in a controlled manner.", "Repeat for the desired number of repetitions, then switch to the other arm."]', '["Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sujeta una barra con una mano usando un agarre pronado.", "Inclínate hacia delante desde las caderas, manteniendo la espalda recta y la cabeza en posición neutral.", "Tira de la barra hacia el pecho, manteniendo el codo cerca del cuerpo y juntando los omóplatos.", "Baja la barra de vuelta a la posición inicial de forma controlada.", "Repite el número de repeticiones deseado, luego cambia al otro brazo."]'),
  ('Remo Inclinado a 1 Brazo con Barra Landmine', 'lever-one-arm-bent-over-row.gif', 'back', '["Stand with your feet shoulder-width apart, knees slightly bent, and hold a barbell with an overhand grip.", "Bend forward at the hips, keeping your back straight and your head up.", "Let the barbell hang in front of you with your arms fully extended.", "Pull the barbell up towards your chest, keeping your elbows close to your body.", "Squeeze your shoulder blades together at the top of the movement.", "Lower the barbell back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sujeta una barra con agarre prono.", "Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y la cabeza erguida.", "Deja que la barra cuelgue frente a ti con los brazos completamente extendidos.", "Tira de la barra hacia el pecho, manteniendo los codos cerca del cuerpo.", "Junta los omóplatos en la parte superior del movimiento.", "Baja la barra de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Remo Inclinado a 1 Brazo en Polea', 'cable-one-arm-bent-over-row.gif', 'back', '["Stand facing a cable machine with your feet shoulder-width apart.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight.", "Grasp the cable handle with one hand, palm facing inward, and extend your arm fully.", "Pull the cable handle towards your body, keeping your elbow close to your side, until your hand reaches your lower chest.", "Pause for a moment, then slowly extend your arm back to the starting position.", "Repeat for the desired number of repetitions, then switch sides."]', '["Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros.", "Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.", "Sujeta la agarradera del cable con una mano, con la palma hacia adentro, y extiende el brazo por completo.", "Jala la agarradera del cable hacia el cuerpo, manteniendo el codo cerca del costado, hasta que la mano llegue a la parte baja del pecho.", "Haz una pausa por un momento y luego extiende lentamente el brazo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de lado."]'),
  ('Remo Inclinado Alterno con Kettlebell', 'kettlebell-alternating-row.gif', 'back', '["Stand with your feet shoulder-width apart, knees slightly bent, and hold a kettlebell in each hand with your palms facing your body.", "Bend forward at the hips, keeping your back straight and your core engaged.", "Pull one kettlebell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.", "Lower the kettlebell back down to the starting position and repeat with the other arm.", "Continue alternating arms for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sostén una pesa rusa en cada mano con las palmas hacia el cuerpo.", "Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado.", "Tira de una pesa rusa hacia el pecho, manteniendo el codo cerca del cuerpo y apretando los omóplatos entre sí.", "Baja la pesa rusa de nuevo a la posición inicial y repite con el otro brazo.", "Continúa alternando los brazos durante el número de repeticiones deseado."]'),
  ('Remo Inclinado con Barra Landmine', 'lever-bent-over-row.gif', 'back', '["Stand with your feet shoulder-width apart and knees slightly bent.", "Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart.", "Bend forward at the hips, keeping your back straight and chest up.", "Pull the barbell towards your lower chest, squeezing your shoulder blades together.", "Pause for a moment at the top, then slowly lower the barbell back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.", "Sujeta la barra con un agarre pronado, manos un poco más separadas que el ancho de los hombros.", "Inclínate hacia delante desde las caderas, manteniendo la espalda recta y el pecho elevado.", "Tira de la barra hacia la parte inferior del pecho, juntando los omóplatos.", "Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Remo Inclinado con Barra y Agarre Supino', 'barbell-reverse-grip-bent-over-row.gif', 'back', '["Stand with your feet shoulder-width apart and knees slightly bent.", "Hold a barbell with an overhand grip, palms facing down, and hands slightly wider than shoulder-width apart.", "Bend forward at the hips, keeping your back straight and chest up, until your torso is almost parallel to the floor.", "Pull the barbell towards your lower chest, squeezing your shoulder blades together.", "Pause for a moment at the top, then slowly lower the barbell back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.", "Sujeta una barra con un agarre pronado, palmas hacia abajo, y las manos un poco más separadas que el ancho de los hombros.", "Inclínate hacia delante desde las caderas, manteniendo la espalda recta y el pecho elevado, hasta que el torso quede casi paralelo al suelo.", "Tira de la barra hacia la parte inferior del pecho, juntando los omóplatos.", "Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Remo Inclinado con Barra Z y Agarre Supino', 'ez-bar-reverse-grip-bent-over-row.gif', 'back', '["Stand with your feet shoulder-width apart and knees slightly bent.", "Hold the ez barbell with an underhand grip, palms facing up, and hands shoulder-width apart.", "Bend forward at the hips, keeping your back straight and chest up, until your torso is almost parallel to the floor.", "Pull the ez barbell towards your lower chest, squeezing your shoulder blades together.", "Pause for a moment at the top, then slowly lower the ez barbell back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.", "Sostén la barra EZ con agarre supino, palmas hacia arriba, y las manos separadas a la altura de los hombros.", "Inclínate hacia delante desde las caderas, manteniendo la espalda recta y el pecho elevado, hasta que el torso quede casi paralelo al suelo.", "Tira de la barra EZ hacia la parte baja del pecho, apretando los omóplatos entre sí.", "Haz una pausa breve en la parte superior, luego baja lentamente la barra EZ a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Remo Inclinado con Kettlebells', 'kettlebell-two-arm-row.gif', 'back', '["Stand with your feet shoulder-width apart, knees slightly bent, and hold a kettlebell in each hand with your palms facing your body.", "Bend forward at the hips, keeping your back straight and your core engaged.", "Pull the kettlebells up towards your chest, squeezing your shoulder blades together.", "Pause for a moment at the top, then slowly lower the kettlebells back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sostén una pesa rusa en cada mano con las palmas hacia el cuerpo.", "Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado.", "Tira de las pesas rusas hacia el pecho, juntando los omóplatos.", "Haz una pausa breve en lo alto, luego baja lentamente las pesas rusas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Remo Inclinado con Mancuernas', 'dumbbell-bent-over-row.gif', 'back', '["Stand with your feet shoulder-width apart, knees slightly bent, and hold a dumbbell in each hand with your palms facing your body.", "Bend forward at the hips, keeping your back straight and your core engaged.", "Let your arms hang straight down towards the floor, with your elbows slightly bent.", "Pull the dumbbells up towards your chest, squeezing your shoulder blades together.", "Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sujeta una mancuerna en cada mano con las palmas hacia tu cuerpo.", "Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado.", "Deja que los brazos cuelguen rectos hacia el suelo, con los codos ligeramente flexionados.", "Tira de las mancuernas hacia arriba, hacia el pecho, apretando los omóplatos entre sí.", "Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Remo Inclinado con Mancuernas y Agarre Supino', 'dumbbell-reverse-grip-row-female.gif', 'back', '["Stand with your feet shoulder-width apart and knees slightly bent.", "Hold a dumbbell in each hand with an overhand grip, palms facing your body.", "Bend forward at the waist, keeping your back straight and your core engaged.", "Let your arms hang straight down, fully extended, with a slight bend in your elbows.", "Pull the dumbbells up towards your chest, squeezing your shoulder blades together.", "Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.", "Sujeta una mancuerna en cada mano con agarre prono, con las palmas hacia tu cuerpo.", "Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y el core activado.", "Deja que tus brazos cuelguen rectos hacia abajo, completamente extendidos, con una ligera flexión en los codos.", "Tira de las mancuernas hacia arriba, hacia el pecho, apretando los omóplatos entre sí.", "Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Remo Inclinado con Mancuernas y Rotación de Palma', 'dumbbell-palm-rotational-bent-over-row.gif', 'back', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.", "Bend forward at the hips, keeping your back straight and your knees slightly bent.", "Let your arms hang straight down, palms facing your body.", "Engage your core and pull the dumbbells up towards your chest, keeping your elbows close to your body.", "As you pull the dumbbells up, rotate your palms so they face away from your body.", "Squeeze your shoulder blades together at the top of the movement.", "Slowly lower the dumbbells back down to the starting position, rotating your palms back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con un agarre prono.", "Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y las rodillas ligeramente flexionadas.", "Deja que los brazos cuelguen rectos hacia abajo, con las palmas hacia tu cuerpo.", "Activa el core y tira de las mancuernas hacia tu pecho, manteniendo los codos cerca del cuerpo.", "Mientras subes las mancuernas, gira las palmas para que queden mirando hacia afuera, alejadas de tu cuerpo.", "Junta los omóplatos en la parte superior del movimiento.", "Baja lentamente las mancuernas hasta la posición inicial, girando las palmas de vuelta a su posición original.", "Repite el número de repeticiones deseado."]'),
  ('Remo Inclinado en Máquina Smith', 'smith-bent-over-row.gif', 'back', '["Set up the smith machine with the bar at hip height.", "Stand facing the bar with your feet shoulder-width apart.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight.", "Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart.", "Pull the bar towards your lower chest, squeezing your shoulder blades together.", "Pause for a moment at the top, then slowly lower the bar back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Configura la máquina Smith con la barra a la altura de la cadera.", "Ponte de pie frente a la barra con los pies separados a la altura de los hombros.", "Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.", "Sujeta la barra con un agarre prono, con las manos un poco más separadas que el ancho de los hombros.", "Tira de la barra hacia la parte baja del pecho, juntando las escápulas.", "Haz una pausa por un momento en la posición alta, luego baja lentamente la barra de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Remo Inclinado en Máquina Smith con Agarre Cerrado', 'smith-narrow-row.gif', 'back', '["Adjust the seat height and position yourself on the machine with your feet flat on the floor.", "Grasp the handles with an overhand grip, slightly narrower than shoulder-width apart.", "Keep your back straight and your chest up as you pull the handles towards your body, squeezing your shoulder blades together.", "Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta la altura del asiento y colócate en la máquina con los pies planos sobre el suelo.", "Sujeta las asas con un agarre prono, un poco más estrecho que el ancho de los hombros.", "Mantén la espalda recta y el pecho elevado mientras tiras de las asas hacia tu cuerpo, juntando las escápulas.", "Haz una pausa por un momento en el punto máximo del movimiento, luego suelta lentamente las agarraderas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Remo Inclinado en Máquina Smith con Agarre Supino', 'smith-reverse-grip-bent-over-row.gif', 'back', '["Set up the smith machine with the bar at hip height.", "Stand facing the bar with your feet shoulder-width apart.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight.", "Grasp the bar with an underhand grip, hands shoulder-width apart.", "Pull the bar towards your lower chest, squeezing your shoulder blades together.", "Pause for a moment at the top, then slowly lower the bar back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Configura la máquina Smith con la barra a la altura de la cadera.", "Ponte de pie frente a la barra con los pies separados a la altura de los hombros.", "Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.", "Sujeta la barra con agarre supino, manos separadas a la altura de los hombros.", "Tira de la barra hacia la parte baja del pecho, juntando las escápulas.", "Haz una pausa por un momento en la posición alta, luego baja lentamente la barra de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Remo Inclinado Landmine con Barra en V', 'lever-bent-over-row-with-v-bar.gif', 'back', '["Adjust the seat height and position yourself facing the machine.", "Grasp the v-bar with an overhand grip, keeping your back straight and your knees slightly bent.", "Pull the v-bar towards your abdomen, squeezing your shoulder blades together.", "Pause for a moment at the top of the movement, then slowly release the weight back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta la altura del asiento y colócate frente a la máquina.", "Sujeta la barra en V con un agarre prono, manteniendo la espalda recta y las rodillas ligeramente flexionadas.", "Tira de la barra en V hacia el abdomen, juntando los omóplatos.", "Haz una pausa breve en la parte alta del movimiento, luego suelta lentamente el peso de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Remo Invertido', 'inverted-row.gif', 'back', '["Set up a bar at waist height or use a suspension trainer.", "Stand facing the bar or suspension trainer, with your feet shoulder-width apart.", "Grab the bar or handles with an overhand grip, slightly wider than shoulder-width apart.", "Lean back, keeping your body straight and your heels on the ground.", "Pull your chest towards the bar or handles, squeezing your shoulder blades together.", "Pause for a moment at the top, then slowly lower yourself back to the starting position.", "Repeat for the desired number of repetitions."]', '["Coloca una barra a la altura de la cintura o usa un entrenador de suspensión.", "Ponte de pie frente a la barra o al entrenador de suspensión, con los pies separados a la altura de los hombros.", "Agarra la barra o las asas con agarre prono, ligeramente más ancho que la altura de los hombros.", "Inclínate hacia atrás, manteniendo el cuerpo recto y los talones en el suelo.", "Tira del pecho hacia la barra o las asas, apretando los omóplatos entre sí.", "Haz una pausa breve en la parte más alta, luego baja lentamente de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Remo Invertido con Correas', 'inverted-row-with-straps.gif', 'back', '["Set up a suspension trainer or straps at chest height.", "Stand facing the anchor point and grab the handles with an overhand grip.", "Walk your feet forward, leaning back until your body is at an angle.", "Keep your body straight and engage your core.", "Pull your chest towards the handles, squeezing your shoulder blades together.", "Pause for a moment at the top, then slowly lower yourself back to the starting position.", "Repeat for the desired number of repetitions."]', '["Coloca un entrenador de suspensión o correas a la altura del pecho.", "Ponte de pie frente al punto de anclaje y agarra las asas con agarre prono.", "Camina con los pies hacia adelante, inclinándote hacia atrás hasta que el cuerpo quede en ángulo.", "Mantén el cuerpo recto y activa el core.", "Tira del pecho hacia las asas, apretando los omóplatos entre sí.", "Haz una pausa breve en la parte más alta, luego baja lentamente de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Remo Invertido con Pies en Banco', 'inverted-row-on-bench.gif', 'back', '["Set up a bench at a height that allows your body to hang freely underneath it.", "Lie face up on the ground with your head towards the bench.", "Reach up and grab the bench with an overhand grip, slightly wider than shoulder-width apart.", "Position your body so that your heels are on the ground and your arms are fully extended.", "Engage your core and squeeze your shoulder blades together as you pull your chest up towards the bench.", "Pause for a moment at the top of the movement, then slowly lower your body back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Coloca un banco a una altura que permita que el cuerpo cuelgue libremente debajo de él.", "Túmbate boca arriba en el suelo con la cabeza hacia el banco.", "Estira los brazos hacia arriba y agarra el banco con agarre prono, ligeramente más ancho que la altura de los hombros.", "Coloca el cuerpo de manera que los talones queden en el suelo y los brazos completamente extendidos.", "Activa el core y aprieta los omóplatos entre sí mientras tiras del pecho hacia el banco.", "Haz una pausa breve en la parte superior del movimiento, luego baja lentamente el cuerpo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Remo Invertido con Rodillas Flexionadas', 'inverted-row-bent-knees.gif', 'back', '["Set up a bar at waist height and lie underneath it.", "Grab the bar with an overhand grip, slightly wider than shoulder-width apart.", "Position your body so that your heels are on the ground and your body is straight.", "Pull your chest up towards the bar by squeezing your shoulder blades together.", "Pause for a moment at the top, then slowly lower your body back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Coloca una barra a la altura de la cintura y túmbate debajo de ella.", "Agarra la barra con agarre prono, ligeramente más ancho que la altura de los hombros.", "Coloca el cuerpo de manera que los talones queden en el suelo y el cuerpo esté recto.", "Tira del pecho hacia arriba en dirección a la barra apretando los omóplatos entre sí.", "Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Remo Kayak Thibaudeau en Polea', 'cable-thibaudeau-kayak-row.gif', 'back', '["Attach a cable handle to a low pulley and sit facing the machine with your feet flat on the floor.", "Grasp the handle with your right hand and extend your arm fully, keeping a slight bend in your elbow.", "Lean forward from your hips, keeping your back straight and your abs engaged.", "Pull the handle towards your torso by retracting your shoulder blade and bending your elbow, keeping your arm close to your body.", "Squeeze your back muscles at the top of the movement, then slowly return to the starting position.", "Repeat for the desired number of repetitions, then switch sides and perform with your left arm."]', '["Coloca un mango de cable en una polea baja y siéntate frente a la máquina con los pies planos en el suelo.", "Agarra el mango con la mano derecha y extiende completamente el brazo, manteniendo una ligera flexión en el codo.", "Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el abdomen activado.", "Tira del mango hacia tu torso retrayendo el omóplato y flexionando el codo, manteniendo el brazo cerca del cuerpo.", "Aprieta los músculos de la espalda en la parte alta del movimiento, luego regresa lentamente a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de lado y realiza el ejercicio con el brazo izquierdo."]'),
  ('Remo Pendlay con Barra', 'barbell-pendlay-row.gif', 'back', '["Stand with your feet shoulder-width apart and your knees slightly bent.", "Bend forward at the hips, keeping your back straight and your chest up.", "Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.", "Pull the barbell towards your upper abdomen, squeezing your shoulder blades together.", "Lower the barbell back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.", "Inclínate hacia delante desde las caderas manteniendo la espalda recta y el pecho elevado.", "Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.", "Tira de la barra hacia la parte superior del abdomen, juntando los omóplatos.", "Baja la barra de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Remo Renegado Alterno con Kettlebell', 'kettlebell-alternating-renegade-row.gif', 'back', '["Start in a high plank position with your hands gripping the kettlebells and your feet hip-width apart.", "Engage your core and keep your body in a straight line from head to heels.", "Pull one kettlebell up towards your chest, keeping your elbow close to your body.", "Lower the kettlebell back down to the starting position and repeat with the other arm.", "Continue alternating arms for the desired number of repetitions."]', '["Comienza en posición de plancha alta con las manos sujetando las pesas rusas y los pies separados a la altura de las caderas.", "Activa el core y mantén el cuerpo en línea recta desde la cabeza hasta los talones.", "Tira de una pesa rusa hacia el pecho, manteniendo el codo cerca del cuerpo.", "Baja la pesa rusa de nuevo a la posición inicial y repite con el otro brazo.", "Continúa alternando los brazos durante el número de repeticiones deseado."]'),
  ('Remo Sentado a 1 Brazo con Giro con Banda Elástica', 'band-one-arm-twisting-seated-row.gif', 'back', '["Sit on a bench or chair with your feet flat on the ground and your back straight.", "Hold the band with one hand and extend your arm fully in front of you.", "Keeping your back straight, pull the band towards your body by bending your elbow and squeezing your shoulder blades together.", "At the same time, twist your torso towards the side of the pulling arm.", "Pause for a moment at the top, then slowly release the tension in the band and return to the starting position.", "Repeat for the desired number of repetitions, then switch to the other arm."]', '["Siéntate en un banco o silla con los pies apoyados en el suelo y la espalda recta.", "Sostén la banda con una mano y extiende el brazo completamente frente a ti.", "Manteniendo la espalda recta, tira de la banda hacia el cuerpo flexionando el codo y juntando los omóplatos.", "Al mismo tiempo, gira el torso hacia el lado del brazo que tira.", "Haz una pausa por un momento en la parte superior, luego suelta lentamente la tensión de la banda y regresa a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia al otro brazo."]'),
  ('Remo Sentado a la Altura del Pecho en Polea', 'cable-upper-row.gif', 'back', '["Attach a straight bar to a cable machine at chest height.", "Stand facing the machine with your feet shoulder-width apart.", "Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart.", "Keep your back straight and your core engaged.", "Pull the bar towards your upper chest, squeezing your shoulder blades together.", "Pause for a moment at the top of the movement.", "Slowly release the bar back to the starting position.", "Repeat for the desired number of repetitions."]', '["Sujeta una barra recta a una máquina de cable a la altura del pecho.", "Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.", "Sujeta la barra con un agarre prono, con las manos un poco más separadas que el ancho de los hombros.", "Mantén la espalda recta y el core activado.", "Jala la barra hacia la parte superior del pecho, apretando los omóplatos entre sí.", "Haz una pausa breve en la parte alta del movimiento.", "Suelta lentamente la barra de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Remo Sentado Alterno a 1 Brazo en Polea', 'cable-seated-one-arm-alternate-row.gif', 'back', '["Sit on a bench facing a cable machine with your feet flat on the ground and knees slightly bent.", "Grasp the handle with one hand and keep your arm fully extended in front of you.", "Pull the handle towards your body, retracting your shoulder blade and keeping your elbow close to your side.", "Pause for a moment at the top of the movement, squeezing your back muscles.", "Slowly release the handle back to the starting position.", "Repeat with the other arm.", "Alternate between arms for the desired number of repetitions."]', '["Siéntate en un banco frente a una máquina de cable con los pies apoyados planos en el suelo y las rodillas ligeramente flexionadas.", "Sujeta la agarradera con una mano y mantén el brazo completamente extendido frente a ti.", "Jala la agarradera hacia el cuerpo, retrayendo el omóplato y manteniendo el codo cerca del costado.", "Haz una pausa por un momento en la parte más alta del movimiento, apretando los músculos de la espalda.", "Suelta lentamente la agarradera de vuelta a la posición inicial.", "Repite con el otro brazo.", "Alterna entre los brazos el número de repeticiones deseado."]'),
  ('Remo Sentado Alterno en Máquina con Agarre Cerrado', 'lever-alternating-narrow-grip-seated-row.gif', 'back', '["Adjust the seat height and footplate position to ensure proper alignment.", "Sit on the machine with your back straight and feet flat on the footplate.", "Grasp the handles with a narrow grip, palms facing each other.", "Keep your chest up and shoulders back throughout the exercise.", "Pull one handle towards your torso while keeping the other handle stationary.", "Squeeze your shoulder blades together at the end of the movement.", "Slowly return the handle to the starting position and repeat with the other side.", "Continue alternating sides for the desired number of repetitions."]', '["Ajusta la altura del asiento y la posición de la placa para los pies para asegurar una alineación correcta.", "Siéntate en la máquina con la espalda recta y los pies planos sobre la placa para los pies.", "Sujeta las asas con un agarre estrecho, con las palmas una frente a la otra.", "Mantén el pecho elevado y los hombros hacia atrás durante todo el ejercicio.", "Tira de una asa hacia el torso mientras mantienes la otra asa inmóvil.", "Aprieta los omóplatos al final del movimiento.", "Devuelve lentamente el asa a la posición inicial y repite con el otro lado.", "Continúa alternando lados durante el número de repeticiones deseado."]'),
  ('Remo Sentado con Banda Elástica y Espalda Recta', 'resistance-band-seated-straight-back-row.gif', 'back', '["Sit on the floor with your legs extended and loop the resistance band around your feet.", "Hold the ends of the resistance band with your hands, palms facing each other.", "Keep your back straight and lean slightly back, engaging your core.", "Pull the resistance band towards your chest, squeezing your shoulder blades together.", "Pause for a moment at the top, then slowly release the tension and return to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en el suelo con las piernas extendidas y enrolla la banda elástica alrededor de los pies.", "Sostén los extremos de la banda elástica con las manos, con las palmas enfrentadas.", "Mantén la espalda recta e inclínate ligeramente hacia atrás, activando el core.", "Tira de la banda elástica hacia el pecho, juntando las escápulas.", "Haz una pausa por un momento en la parte superior, luego suelta lentamente la tensión y regresa a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Remo Sentado Cruzado en Polea con Cuerda', 'cable-rope-crossover-seated-row.gif', 'back', '["Sit on the rowing machine with your feet flat on the footrests and your knees slightly bent.", "Grasp the cable ropes with an overhand grip, palms facing each other.", "Lean back slightly, keeping your back straight and your core engaged.", "Pull the cable ropes towards your chest, squeezing your shoulder blades together.", "Pause for a moment at the peak of the movement, then slowly release the tension and return to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en la máquina de remo con los pies planos sobre los apoyapiés y las rodillas ligeramente flexionadas.", "Sujeta las cuerdas del cable con un agarre prono, con las palmas una frente a la otra.", "Inclínate ligeramente hacia atrás, manteniendo la espalda recta y el core activado.", "Jala las cuerdas del cable hacia el pecho, apretando los omóplatos entre sí.", "Haz una pausa por un momento en el punto más alto del movimiento, luego libera lentamente la tensión y regresa a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Remo Sentado Declinado en Polea con Agarre Abierto', 'cable-decline-seated-wide-grip-row.gif', 'back', '["Sit on the decline bench facing the cable machine with your feet securely placed on the footrests.", "Grasp the cable attachment with a wide overhand grip, palms facing down.", "Lean back slightly, keeping your back straight and your core engaged.", "Pull the cable towards your lower chest, squeezing your shoulder blades together.", "Pause for a moment at the peak of the contraction, then slowly release the cable back to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en el banco declinado frente a la máquina de cable con los pies firmemente colocados en los reposapiés.", "Sujeta el accesorio del cable con un agarre prono amplio, palmas hacia abajo.", "Inclínate ligeramente hacia atrás, manteniendo la espalda recta y el core activado.", "Tira del cable hacia la parte inferior del pecho, juntando los omóplatos.", "Haz una pausa breve en el punto máximo de la contracción, luego suelta lentamente el cable de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Remo Sentado Elevado en Polea con Cuerda', 'cable-rope-elevated-seated-row.gif', 'back', '["Sit on the elevated seat facing the cable machine.", "Grab the cable rope handles with an overhand grip, palms facing each other.", "Keep your back straight and lean slightly back, maintaining a slight bend in your knees.", "Pull the cable towards your body by retracting your shoulder blades and squeezing your back muscles.", "Pause for a moment at the fully contracted position.", "Slowly release the tension and extend your arms back to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en el asiento elevado frente a la máquina de cable.", "Agarra las agarraderas de cuerda con un agarre prono, con las palmas una frente a la otra.", "Mantén la espalda recta e inclínate ligeramente hacia atrás, conservando una ligera flexión en las rodillas.", "Jala el cable hacia el cuerpo retrayendo los omóplatos y apretando los músculos de la espalda.", "Haz una pausa por un momento en la posición de contracción completa.", "Libera lentamente la tensión y extiende los brazos de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Remo Sentado en el Suelo en Polea con Agarre Abierto', 'cable-floor-seated-wide-grip-row.gif', 'back', '["Sit on the floor with your legs extended and your back straight.", "Attach a cable handle to a low pulley and position the cable machine behind you.", "Grasp the handle with a wide overhand grip, palms facing down.", "Lean back slightly, keeping your back straight and your chest lifted.", "Pull the handle towards your waist, squeezing your shoulder blades together.", "Pause for a moment at the top of the movement, then slowly release the handle back to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en el suelo con las piernas extendidas y la espalda recta.", "Coloca una agarradera de cable en una polea baja y ubica la máquina de cable detrás de ti.", "Sujeta la agarradera con un agarre prono amplio, palmas hacia abajo.", "Inclínate ligeramente hacia atrás, manteniendo la espalda recta y el pecho elevado.", "Tira de la agarradera hacia la cintura, juntando los omóplatos.", "Haz una pausa breve en la parte más alta del movimiento, luego suelta lentamente la agarradera de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Remo Sentado en Máquina', 'lever-seated-row.gif', 'back', '["Adjust the seat height and footrests to a comfortable position.", "Sit on the machine with your chest against the pad and your feet on the footrests.", "Grasp the handles with an overhand grip, shoulder-width apart.", "Keep your back straight and your core engaged.", "Pull the handles towards your body, squeezing your shoulder blades together.", "Pause for a moment at the peak of the movement.", "Slowly release the handles and return to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta la altura del asiento y los apoyapiés a una posición cómoda.", "Siéntate en la máquina con el pecho apoyado en la almohadilla y los pies sobre los apoyapiés.", "Agarra las asas con un agarre prono, con las manos separadas a la altura de los hombros.", "Mantén la espalda recta y el core activado.", "Jala las agarraderas hacia el cuerpo, apretando los omóplatos entre sí.", "Haz una pausa breve en la parte alta del movimiento.", "Suelta lentamente las asas y vuelve a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Remo Sentado en Máquina con Agarre Cerrado', 'lever-narrow-grip-seated-row.gif', 'back', '["Adjust the seat height and footrests to ensure proper form.", "Sit on the machine with your feet flat on the footrests and your knees slightly bent.", "Grasp the handles with a narrow grip, palms facing each other.", "Keep your back straight and lean slightly forward.", "Pull the handles towards your torso, squeezing your shoulder blades together.", "Pause for a moment at the peak of the movement.", "Slowly release the handles and return to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta la altura del asiento y los apoyapiés para asegurar una postura correcta.", "Siéntate en la máquina con los pies planos sobre los apoyapiés y las rodillas ligeramente flexionadas.", "Sujeta las asas con un agarre estrecho, con las palmas una frente a la otra.", "Mantén la espalda recta e inclínate ligeramente hacia adelante.", "Tira de las asas hacia el torso, juntando los omóplatos.", "Haz una pausa breve en la parte alta del movimiento.", "Suelta lentamente las asas y vuelve a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Remo Sentado en Polea con Cuerda', 'cable-rope-seated-row.gif', 'back', '["Sit on the rowing machine with your feet flat on the footrests and knees slightly bent.", "Grasp the cable ropes with an overhand grip, palms facing each other.", "Keep your back straight and lean slightly forward, maintaining a slight bend in your elbows.", "Pull the cable ropes towards your body, squeezing your shoulder blades together.", "Pause for a moment at the peak of the movement, then slowly release the tension and return to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en la máquina de remo con los pies planos sobre los apoyapiés y las rodillas ligeramente flexionadas.", "Sujeta las cuerdas del cable con un agarre prono, con las palmas una frente a la otra.", "Mantén la espalda recta e inclínate ligeramente hacia adelante, manteniendo una ligera flexión en los codos.", "Jala las cuerdas del cable hacia el cuerpo, apretando los omóplatos entre sí.", "Haz una pausa por un momento en el punto más alto del movimiento, luego libera lentamente la tensión y regresa a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Remo Sentado en Polea con Espalda Recta', 'cable-straight-back-seated-row.gif', 'back', '["Sit on the cable row machine with your feet flat on the footrests and your knees slightly bent.", "Grasp the cable handles with an overhand grip, palms facing down.", "Keep your back straight and lean slightly forward from the hips.", "Pull the cable handles towards your body, squeezing your shoulder blades together.", "Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en la máquina de remo con cable con los pies planos sobre los apoyapiés y las rodillas ligeramente flexionadas.", "Agarra los mangos del cable con un agarre prono, con las palmas hacia abajo.", "Mantén la espalda recta e inclínate ligeramente hacia adelante desde las caderas.", "Tira de los mangos del cable hacia tu cuerpo, apretando los omóplatos entre sí.", "Haz una pausa por un momento en el punto máximo del movimiento, luego suelta lentamente las agarraderas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Remo Tumbado con Barra Curva', 'cambered-bar-lying-row.gif', 'back', '["Set up a barbell on the floor and lie face down on a bench with your chest just off the edge.", "Reach down and grab the barbell with an overhand grip, slightly wider than shoulder-width apart.", "With your legs straight and feet on the ground, lift the barbell off the floor by extending your arms.", "Pull the barbell towards your chest, squeezing your shoulder blades together.", "Lower the barbell back down to the starting position and repeat for the desired number of repetitions."]', '["Coloca una barra en el suelo y túmbate boca abajo en un banco con el pecho justo en el borde.", "Estírate hacia abajo y agarra la barra con un agarre prono, un poco más ancho que el ancho de los hombros.", "Con las piernas rectas y los pies en el suelo, levanta la barra del suelo extendiendo los brazos.", "Tira de la barra hacia el pecho, juntando los omóplatos.", "Baja la barra de vuelta a la posición inicial y repite el número de repeticiones deseado."]'),
  ('Remo Unilateral en Máquina', 'lever-unilateral-row.gif', 'back', '["Adjust the seat height and position yourself facing the machine.", "Grasp the handles with an overhand grip and keep your back straight.", "Pull the handles towards your body, squeezing your shoulder blades together.", "Pause for a moment at the peak of the movement, then slowly release and extend your arms back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta la altura del asiento y colócate frente a la máquina.", "Agarra las asas con un agarre prono y mantén la espalda recta.", "Jala las agarraderas hacia el cuerpo, apretando los omóplatos entre sí.", "Haz una pausa en el punto máximo del movimiento y luego suelta lentamente, extendiendo los brazos de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Remo Vertical en Máquina con Agarre Supino', 'lever-reverse-grip-vertical-row.gif', 'back', '["Adjust the seat height and footplate position to ensure proper alignment.", "Sit on the machine with your chest against the pad and your feet flat on the footplate.", "Grasp the handles with an underhand grip, palms facing up.", "Keep your back straight and engage your core.", "Pull the handles towards your chest, squeezing your shoulder blades together.", "Pause for a moment at the top of the movement, then slowly release and extend your arms back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta la altura del asiento y la posición de la placa para los pies para asegurar una alineación correcta.", "Siéntate en la máquina con el pecho contra la almohadilla y los pies planos sobre la placa para los pies.", "Sujeta las asas con un agarre supino, con las palmas hacia arriba.", "Mantén la espalda recta y activa el core.", "Tira de las asas hacia el pecho, juntando los omóplatos.", "Haz una pausa breve en la parte alta del movimiento, luego suelta lentamente y extiende los brazos de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Skin the Cat (Anillas)', 'skin-the-cat.gif', 'back', '["Start by hanging from a bar with your arms fully extended and your body relaxed.", "Engage your core and lift your legs up, bringing your knees towards your chest.", "Continue to lift your legs up and over your head, allowing your body to pass through the arms.", "Once your legs are fully extended over your head, begin to lower them back down towards the starting position.", "As you lower your legs, allow your body to pass back through the arms until you are hanging with your arms fully extended again.", "Repeat for the desired number of repetitions."]', '["Comienza colgándote de una barra con los brazos completamente extendidos y el cuerpo relajado.", "Activa el core y levanta las piernas, llevando las rodillas hacia el pecho.", "Continúa levantando las piernas por encima de la cabeza, permitiendo que el cuerpo pase entre los brazos.", "Una vez que las piernas estén completamente extendidas por encima de la cabeza, comienza a bajarlas de nuevo hacia la posición inicial.", "Mientras bajas las piernas, permite que el cuerpo pase de nuevo entre los brazos hasta quedar colgado con los brazos completamente extendidos otra vez.", "Repite el número de repeticiones deseado."]'),
  ('Slam con Balón Medicinal', 'medicine-ball-overhead-slam.gif', 'back', '["Stand with your feet shoulder-width apart, holding a medicine ball with both hands above your head.", "Engage your core and keep your back straight.", "Bend your knees slightly and forcefully slam the medicine ball down to the ground in front of you.", "As you slam the ball down, use your entire body to generate power, including your shoulders and core.", "Catch the ball on the bounce and repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo un balón medicinal con ambas manos por encima de la cabeza.", "Activa el core y mantén la espalda recta.", "Flexiona ligeramente las rodillas y lanza con fuerza el balón medicinal contra el suelo frente a ti.", "Al lanzar el balón al suelo, utiliza todo el cuerpo para generar potencia, incluidos los hombros y el core.", "Atrapa el balón al rebotar y repite el número de repeticiones deseado."]'),
  ('Tirón Alto Sumo con Kettlebell', 'kettlebell-sumo-high-pull.gif', 'back', '["Stand with your feet wider than shoulder-width apart, toes pointing outwards.", "Hold a kettlebell with both hands in front of your body, arms extended downwards.", "Bend your knees and lower your hips into a squat position, keeping your back straight.", "Drive through your heels and explosively extend your hips and knees, pulling the kettlebell up towards your chin.", "As you pull the kettlebell up, keep your elbows high and wide, and squeeze your shoulder blades together.", "Lower the kettlebell back down to the starting position and repeat for the desired number of repetitions."]', '["Ponte de pie con los pies más separados que el ancho de los hombros, con las puntas de los pies hacia afuera.", "Sujeta una pesa rusa con ambas manos frente al cuerpo, con los brazos extendidos hacia abajo.", "Flexiona las rodillas y baja las caderas hasta una posición de sentadilla, manteniendo la espalda recta.", "Empuja con los talones y extiende explosivamente las caderas y las rodillas, tirando de la pesa rusa hacia la barbilla.", "Mientras tiras de la pesa rusa hacia arriba, mantén los codos altos y abiertos, y junta los omóplatos.", "Baja la pesa rusa de vuelta a la posición inicial y repite el número de repeticiones deseado."]'),
  ('Tirón con Giro a 1 Brazo en Polea', 'cable-twisting-pull-0244.gif', 'back', '["Attach a cable handle to a low pulley and stand facing the machine.", "Grasp the handle with your left hand and step away from the machine, extending your arm fully.", "Position your feet shoulder-width apart, with your knees slightly bent.", "Keep your back straight and your core engaged throughout the exercise.", "Pull the handle towards your body, rotating your torso to the right as you do so.", "Squeeze your back muscles at the end of the movement.", "Slowly return to the starting position, keeping tension on the cable.", "Repeat for the desired number of repetitions, then switch sides and perform with your right hand."]', '["Coloca un mango de cable en una polea baja y ponte de pie frente a la máquina.", "Agarra el mango con la mano izquierda y aléjate de la máquina, extendiendo completamente el brazo.", "Coloca los pies separados a la altura de los hombros, con las rodillas ligeramente flexionadas.", "Mantén la espalda recta y el core activado durante todo el ejercicio.", "Tira del mango hacia tu cuerpo, rotando el torso hacia la derecha al hacerlo.", "Aprieta los músculos de la espalda al final del movimiento.", "Regresa lentamente a la posición inicial, manteniendo la tensión en el cable.", "Repite el número de repeticiones deseado, luego cambia de lado y realiza el ejercicio con la mano derecha."]'),
  ('Toque de Puntas con Ambas Manos', 'two-toe-touch-male.gif', 'back', '["Stand with your feet shoulder-width apart and your arms extended out to the sides.", "Bend forward at the waist, keeping your back straight and your knees slightly bent.", "Reach down towards your toes with both hands, keeping your legs straight.", "Pause for a moment at the bottom, then slowly return to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y los brazos extendidos hacia los lados.", "Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y las rodillas ligeramente flexionadas.", "Estira los brazos hacia la punta de los pies con ambas manos, manteniendo las piernas rectas.", "Haz una pausa por un momento en la parte inferior, luego regresa lentamente a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Trepa de Cuerda', 'rope-climb.gif', 'back', '["Stand facing the rope with your feet shoulder-width apart.", "Grab the rope with both hands, palms facing towards you.", "Bend your knees slightly and engage your core.", "Begin pulling yourself up the rope by alternating hand-over-hand movements.", "Use your legs to assist in the upward movement.", "Continue climbing until you reach the desired height or the top of the rope.", "To descend, reverse the hand-over-hand movement while controlling your descent.", "Repeat for the desired number of repetitions."]', '["Ponte de pie frente a la cuerda con los pies separados a la altura de los hombros.", "Sujeta la cuerda con ambas manos, con las palmas mirando hacia ti.", "Flexiona ligeramente las rodillas y activa el core.", "Comienza a subir por la cuerda alternando los movimientos de las manos.", "Usa las piernas para ayudar en el movimiento ascendente.", "Continúa trepando hasta alcanzar la altura deseada o la parte superior de la cuerda.", "Para descender, invierte el movimiento alterno de las manos mientras controlas tu descenso.", "Repite el número de repeticiones deseado."]'),
  ('Bicicleta con Brazos (Cross Trainer)', 'cycle-cross-trainer.gif', 'cardio', '["Adjust the seat height and position yourself on the cycle cross trainer.", "Place your feet on the pedals and grip the handlebars.", "Start pedaling in a smooth and controlled motion.", "Maintain a steady pace and increase the resistance if desired.", "Continue pedaling for the desired duration of your cardio workout."]', '["Ajusta la altura del asiento y colócate en la bicicleta elíptica.", "Coloca los pies en los pedales y sujeta el manillar.", "Comienza a pedalear con un movimiento suave y controlado.", "Mantén un ritmo constante y aumenta la resistencia si lo deseas.", "Continúa pedaleando durante la duración deseada de tu entrenamiento cardiovascular."]'),
  ('Bicicleta Estática a Ritmo Suave', 'stationary-bike-walk.gif', 'cardio', '["Adjust the seat height and position on the stationary bike to ensure proper alignment.", "Place your feet on the pedals and secure them with the straps if available.", "Start pedaling at a comfortable pace, keeping your back straight and core engaged.", "Maintain a steady rhythm and increase the resistance level if desired.", "Continue pedaling for the desired duration of your cardio workout.", "Cool down by gradually reducing your pace and resistance level.", "Stretch your leg muscles after the workout to prevent tightness and promote recovery."]', '["Ajusta la altura y la posición del asiento en la bicicleta estática para asegurar una alineación correcta.", "Coloca los pies sobre los pedales y sujétalos con las correas si están disponibles.", "Comienza a pedalear a un ritmo cómodo, manteniendo la espalda recta y el core activado.", "Mantén un ritmo constante y aumenta el nivel de resistencia si lo deseas.", "Continúa pedaleando durante la duración deseada de tu entrenamiento cardiovascular.", "Enfría reduciendo gradualmente tu ritmo y el nivel de resistencia.", "Estira los músculos de las piernas después del entrenamiento para prevenir la rigidez y favorecer la recuperación."]'),
  ('Burpee con Mancuernas', 'dumbbell-burpee.gif', 'cardio', '["Start in a standing position with your feet shoulder-width apart and a dumbbell in each hand.", "Lower your body into a squat position, placing the dumbbells on the ground in front of you.", "Kick your feet back into a push-up position, keeping your body in a straight line.", "Perform a push-up, bending your elbows and lowering your chest towards the ground.", "Jump your feet back towards your hands, landing in a squat position.", "Stand up explosively, lifting the dumbbells off the ground and bringing them to your shoulders.", "Press the dumbbells overhead, fully extending your arms.", "Lower the dumbbells back to your shoulders and repeat the entire sequence for the desired number of repetitions."]', '["Comienza de pie con los pies separados a la altura de los hombros y una mancuerna en cada mano.", "Baja el cuerpo a una posición de sentadilla, colocando las mancuernas en el suelo frente a ti.", "Lleva los pies hacia atrás a una posición de flexión de brazos, manteniendo el cuerpo en línea recta.", "Realiza una flexión de brazos, flexionando los codos y bajando el pecho hacia el suelo.", "Salta con los pies hacia tus manos, aterrizando en una posición de sentadilla.", "Ponte de pie de forma explosiva, levantando las mancuernas del suelo y llevándolas a los hombros.", "Empuja las mancuernas por encima de la cabeza, extendiendo completamente los brazos.", "Baja las mancuernas de vuelta a los hombros y repite toda la secuencia el número de repeticiones deseado."]'),
  ('Burpee con Salto de Tijera', 'jack-burpee.gif', 'cardio', '["Start in a standing position with your feet shoulder-width apart.", "Lower your body into a squat position, placing your hands on the ground in front of you.", "Kick your feet back, landing in a push-up position.", "Perform a push-up, lowering your chest to the ground and then pushing back up.", "Jump your feet forward, landing in a squat position.", "Jump up explosively, reaching your arms overhead.", "Land softly and immediately lower back into the squat position to begin the next repetition."]', '["Comienza de pie con los pies separados a la altura de los hombros.", "Baja el cuerpo a una posición de sentadilla, colocando las manos en el suelo frente a ti.", "Lanza los pies hacia atrás, aterrizando en posición de flexión de brazos.", "Realiza una flexión de brazos, bajando el pecho hacia el suelo y luego empujando de nuevo hacia arriba.", "Salta con los pies hacia adelante, aterrizando en posición de sentadilla.", "Salta hacia arriba explosivamente, llevando los brazos por encima de la cabeza.", "Aterriza suavemente y baja de inmediato a una posición de sentadilla para comenzar la siguiente repetición."]'),
  ('Caminar en Cinta Inclinada', 'walking-on-incline-treadmill.gif', 'cardio', '["Adjust the incline level on the treadmill to your desired intensity.", "Stand on the treadmill with your feet shoulder-width apart.", "Start walking at a comfortable pace, ensuring that you maintain proper form.", "Engage your core muscles and keep your back straight throughout the exercise.", "Continue walking on the incline treadmill for the desired duration of your cardio workout.", "Gradually decrease the incline and speed of the treadmill to cool down before stopping."]', '["Ajusta el nivel de inclinación de la cinta de correr a la intensidad deseada.", "Ponte de pie sobre la cinta de correr con los pies separados a la altura de los hombros.", "Comienza a caminar a un ritmo cómodo, asegurándote de mantener una forma correcta.", "Activa los músculos del core y mantén la espalda recta durante todo el ejercicio.", "Continúa caminando en la cinta inclinada durante la duración deseada de tu entrenamiento cardiovascular.", "Disminuye gradualmente la inclinación y la velocidad de la cinta para enfriar antes de detenerte."]'),
  ('Carrera Circular (Wheel Run)', 'wheel-run.gif', 'cardio', '["Start in a plank position with your hands on the wheel and your body straight.", "Engage your core and start rolling the wheel forward by extending your arms.", "Continue rolling until your body is fully extended and your arms are overhead.", "Reverse the movement by pulling the wheel back towards your body, using your core and arms.", "Repeat for the desired number of repetitions."]', '["Comienza en posición de plancha con las manos sobre el rodillo y el cuerpo recto.", "Activa el core y comienza a hacer rodar el rodillo hacia adelante extendiendo los brazos.", "Continúa rodando hasta que tu cuerpo quede completamente extendido y los brazos por encima de la cabeza.", "Invierte el movimiento tirando del rodillo de vuelta hacia tu cuerpo, usando el core y los brazos.", "Repite el número de repeticiones deseado."]'),
  ('Carrera de Zancada Corta', 'short-stride-run.gif', 'cardio', '["Find an open space or a treadmill to perform the exercise.", "Stand tall with your feet hip-width apart.", "Start jogging in place, lifting your knees high and pumping your arms.", "After a few seconds, start taking short strides forward, maintaining a quick pace.", "Continue running with short strides for the desired duration or distance."]', '["Busca un espacio abierto o una cinta de correr para realizar el ejercicio.", "Ponte de pie con los pies separados a la altura de la cadera.", "Comienza a trotar en el lugar, levantando las rodillas alto y moviendo los brazos.", "Después de unos segundos, comienza a dar pasos cortos hacia delante, manteniendo un ritmo rápido.", "Continúa corriendo con pasos cortos durante la duración o distancia deseada."]'),
  ('Elíptica', 'walk-elliptical-cross-trainer.gif', 'cardio', '["Adjust the resistance level and incline of the elliptical machine to your desired settings.", "Step onto the pedals of the machine and grip the handles lightly.", "Begin by pushing down with your feet and pulling the handles towards your body.", "Continue this motion, alternating between pushing and pulling, to simulate a walking or running motion.", "Maintain a steady pace and keep your core engaged throughout the exercise.", "Continue for the desired duration of your cardio workout.", "Gradually decrease the intensity and speed of the machine before stepping off."]', '["Ajusta el nivel de resistencia y la inclinación de la máquina elíptica a los valores deseados.", "Sube a los pedales de la máquina y agarra las asas con suavidad.", "Comienza empujando hacia abajo con los pies y tirando de las asas hacia tu cuerpo.", "Continúa con este movimiento, alternando entre empujar y tirar, para simular un movimiento de caminar o correr.", "Mantén un ritmo constante y conserva el core activado durante todo el ejercicio.", "Continúa durante la duración deseada de tu entrenamiento cardiovascular.", "Disminuye gradualmente la intensidad y la velocidad de la máquina antes de bajarte."]'),
  ('Escaladora (Stepmill)', 'walking-on-stepmill.gif', 'cardio', '["Adjust the stepmill machine to a comfortable level.", "Step onto the machine and place your hands on the handrails for support.", "Start walking by placing one foot on a step and then the other, alternating between legs.", "Maintain an upright posture and engage your core muscles.", "Continue walking for the desired duration or distance.", "Gradually increase the intensity or speed as you become more comfortable with the exercise.", "Remember to cool down and stretch after completing the exercise."]', '["Ajusta la máquina de escalones a un nivel cómodo.", "Sube a la máquina y coloca las manos sobre los pasamanos para apoyarte.", "Comienza a caminar colocando un pie en un escalón y luego el otro, alternando entre las piernas.", "Mantén una postura erguida y activa los músculos del core.", "Continúa caminando durante la duración o distancia deseada.", "Aumenta gradualmente la intensidad o la velocidad a medida que te sientas más cómodo con el ejercicio.", "Recuerda enfriar y estirar después de completar el ejercicio."]'),
  ('Escaladores (Mountain Climber)', 'mountain-climber.gif', 'cardio', '["Start in a high plank position with your hands directly under your shoulders and your body in a straight line.", "Engage your core and bring your right knee towards your chest, then quickly switch and bring your left knee towards your chest.", "Continue alternating legs in a running motion, keeping your hips low and your core engaged.", "Maintain a steady pace and breathe evenly throughout the exercise.", "Repeat for the desired number of repetitions."]', '["Comienza en una posición de plancha alta con las manos justo debajo de los hombros y el cuerpo en línea recta.", "Activa el core y lleva la rodilla derecha hacia el pecho, luego cambia rápidamente y lleva la rodilla izquierda hacia el pecho.", "Continúa alternando las piernas con un movimiento de carrera, manteniendo las caderas bajas y el core activado.", "Mantén un ritmo constante y respira de forma regular durante todo el ejercicio.", "Repite el número de repeticiones deseado."]'),
  ('Gateo de Oso (Bear Crawl)', 'bear-crawl.gif', 'cardio', '["Start on all fours with your hands directly under your shoulders and your knees directly under your hips.", "Lift your knees slightly off the ground, keeping your back flat and your core engaged.", "Move your right hand and left foot forward simultaneously, followed by your left hand and right foot.", "Continue crawling forward, alternating your hand and foot movements.", "Maintain a steady pace and keep your core tight throughout the exercise.", "Continue for the desired distance or time."]', '["Comienza apoyado sobre manos y rodillas, con las manos justo debajo de los hombros y las rodillas justo debajo de las caderas.", "Levanta las rodillas ligeramente del suelo, manteniendo la espalda plana y el core activado.", "Mueve la mano derecha y el pie izquierdo hacia adelante simultáneamente, seguido de la mano izquierda y el pie derecho.", "Continúa avanzando a gatas, alternando los movimientos de manos y pies.", "Mantén un ritmo constante y el core firme durante todo el ejercicio.", "Continúa durante la distancia o el tiempo deseado."]'),
  ('Giro 360 en Barra', 'swing-360.gif', 'cardio', '["Stand with your feet shoulder-width apart and knees slightly bent.", "Hold your arms straight out in front of you, parallel to the ground.", "Engage your core and swing your arms in a circular motion, rotating your torso as you do so.", "Continue the circular motion, swinging your arms and rotating your torso for the desired number of repetitions.", "Remember to breathe throughout the exercise."]', '["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.", "Mantén los brazos extendidos rectos frente a ti, paralelos al suelo.", "Activa el core y mueve los brazos en un movimiento circular, rotando el torso mientras lo haces.", "Continúa el movimiento circular, moviendo los brazos y rotando el torso el número de repeticiones deseado.", "Recuerda respirar durante todo el ejercicio."]'),
  ('Impulso a Carrera', 'push-to-run.gif', 'cardio', '["Start in a push-up position with your hands shoulder-width apart and your body in a straight line.", "Lower your chest towards the ground by bending your elbows, keeping your body straight.", "Push through your hands to extend your arms and return to the starting position.", "Quickly bring one knee towards your chest, then quickly switch and bring the other knee towards your chest.", "Continue alternating knees as fast as you can while maintaining good form.", "Continue for the desired duration or number of repetitions."]', '["Comienza en posición de flexión con las manos separadas a la altura de los hombros y el cuerpo en línea recta.", "Baja el pecho hacia el suelo flexionando los codos, manteniendo el cuerpo recto.", "Empuja con las manos para extender los brazos y volver a la posición inicial.", "Lleva rápidamente una rodilla hacia el pecho, luego cambia rápidamente y lleva la otra rodilla hacia el pecho.", "Continúa alternando las rodillas tan rápido como puedas manteniendo una buena forma.", "Continúa durante el tiempo o el número de repeticiones deseado."]'),
  ('Media Flexión de Rodillas Alterna', 'half-knee-bends-male.gif', 'cardio', '["Stand with your feet shoulder-width apart.", "Bend your knees and lower your body down as if you were sitting back into a chair.", "Keep your chest up and your weight in your heels.", "Pause for a moment at the bottom, then push through your heels to return to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros.", "Dobla las rodillas y baja el cuerpo como si te fueras a sentar en una silla.", "Mantén el pecho elevado y el peso en los talones.", "Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Paso Adelante y Atrás', 'back-and-forth-step.gif', 'cardio', '["Stand with your feet shoulder-width apart.", "Step forward with your right foot, bending your knee and lowering your body into a lunge position.", "Push off with your right foot and step back to the starting position.", "Repeat the movement with your left foot, alternating legs with each step.", "Continue stepping back and forth, maintaining a steady pace.", "Repeat for the desired duration or number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros.", "Da un paso adelante con el pie derecho, flexionando la rodilla y bajando el cuerpo hacia una posición de zancada.", "Empuja con el pie derecho y da un paso atrás para regresar a la posición inicial.", "Repite el movimiento con el pie izquierdo, alternando las piernas en cada paso.", "Continúa dando pasos hacia adelante y hacia atrás, manteniendo un ritmo constante.", "Repite durante la duración o el número de repeticiones deseado."]'),
  ('Paso de Esquiador', 'ski-step.gif', 'cardio', '["Stand with your feet shoulder-width apart.", "Bend your knees slightly and keep your back straight.", "Jump to the right, landing on your right foot while swinging your left leg behind your right leg.", "Immediately jump to the left, landing on your left foot while swinging your right leg behind your left leg.", "Continue alternating jumps from side to side, mimicking a skiing motion.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros.", "Dobla ligeramente las rodillas y mantén la espalda recta.", "Salta hacia la derecha, aterrizando sobre el pie derecho mientras balanceas la pierna izquierda detrás de la pierna derecha.", "Salta inmediatamente hacia la izquierda, aterrizando sobre el pie izquierdo mientras balanceas la pierna derecha detrás de la pierna izquierda.", "Continúa alternando los saltos de lado a lado, imitando un movimiento de esquí.", "Repite el número de repeticiones deseado."]'),
  ('Rodillas Altas contra la Pared', 'high-knee-against-wall.gif', 'cardio', '["Stand facing a wall with your feet hip-width apart.", "Place your hands on the wall for support.", "Engage your core and lift your right knee up towards your chest, while keeping your left foot on the ground.", "Quickly switch legs, bringing your left knee up towards your chest and lowering your right foot back down.", "Continue alternating legs in a running motion, bringing your knees up as high as possible.", "Maintain a fast pace and keep your upper body stable throughout the exercise.", "Repeat for the desired duration or number of repetitions."]', '["Ponte de pie frente a una pared con los pies separados a la altura de las caderas.", "Coloca las manos en la pared para mayor apoyo.", "Activa el core y levanta la rodilla derecha hacia el pecho, mientras mantienes el pie izquierdo en el suelo.", "Cambia rápidamente de pierna, llevando la rodilla izquierda hacia el pecho y bajando el pie derecho de nuevo.", "Continúa alternando las piernas con un movimiento de carrera, llevando las rodillas lo más alto posible.", "Mantén un ritmo rápido y la parte superior del cuerpo estable durante todo el ejercicio.", "Repite durante la duración o el número de repeticiones deseado."]'),
  ('Saltar la Cuerda', 'jump-rope.gif', 'cardio', '["Hold the handles of the jump rope with your hands, palms facing inward.", "Stand with your feet shoulder-width apart and knees slightly bent.", "Swing the rope over your head and jump over it as it comes towards your feet.", "Land softly on the balls of your feet and repeat the jump as the rope comes around again.", "Continue jumping for the desired duration or number of repetitions."]', '["Sujeta las asas de la cuerda de saltar con las manos, palmas hacia adentro.", "Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.", "Balancea la cuerda por encima de la cabeza y salta sobre ella cuando se acerque a los pies.", "Aterriza suavemente sobre la punta de los pies y repite el salto cuando la cuerda vuelva a pasar.", "Continúa saltando durante el tiempo o el número de repeticiones deseado."]'),
  ('Salto con Apertura de Piernas (Jack Jump)', 'jack-jump-male-3224.gif', 'cardio', '["Stand with your feet together and your arms by your sides.", "Jump up, spreading your feet apart and raising your arms above your head.", "As you land, quickly jump back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies juntos y los brazos a los costados.", "Salta, separando los pies y levantando los brazos por encima de la cabeza.", "Al aterrizar, salta rápidamente de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Salto desde Media Sentadilla', 'semi-squat-jump-male.gif', 'cardio', '["Stand with your feet shoulder-width apart.", "Bend your knees and lower your body into a squat position.", "Jump explosively, extending your hips and knees while swinging your arms for momentum.", "Land softly on the balls of your feet and immediately go into the next repetition.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros.", "Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla.", "Salta de forma explosiva, extendiendo las caderas y las rodillas mientras balanceas los brazos para generar impulso.", "Aterriza suavemente sobre la punta de los pies y pasa de inmediato a la siguiente repetición.", "Repite el número de repeticiones deseado."]'),
  ('Salto en Estrella', 'star-jump-male.gif', 'cardio', '["Stand with your feet shoulder-width apart and your arms by your sides.", "Bend your knees slightly and jump up explosively.", "As you jump, spread your legs and extend your arms out to the sides, forming a star shape with your body.", "Land softly on the balls of your feet with your knees slightly bent.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y los brazos a los costados.", "Flexiona ligeramente las rodillas y salta hacia arriba de forma explosiva.", "Mientras saltas, separa las piernas y extiende los brazos hacia los lados, formando una figura de estrella con tu cuerpo.", "Aterriza suavemente sobre la punta de los pies con las rodillas ligeramente flexionadas.", "Repite el número de repeticiones deseado."]'),
  ('Saltos Alternando Piernas (Scissor Jumps)', 'scissor-jumps-male.gif', 'cardio', '["Stand with your feet shoulder-width apart.", "Jump off the ground and simultaneously cross your right leg in front of your left leg.", "As you land, quickly switch legs, crossing your left leg in front of your right leg.", "Continue alternating legs and jumping as quickly as possible.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros.", "Salta del suelo y al mismo tiempo cruza la pierna derecha por delante de la pierna izquierda.", "Al aterrizar, cambia rápidamente de pierna, cruzando la pierna izquierda por delante de la pierna derecha.", "Continúa alternando las piernas y saltando lo más rápido posible.", "Repite el número de repeticiones deseado."]'),
  ('Saltos de Patinador', 'skater-hops.gif', 'cardio', '["Stand with your feet shoulder-width apart.", "Bend your knees slightly and jump to the right, landing on your right foot.", "As you land, swing your left leg behind your right leg and tap the ground with your left toes.", "Immediately jump to the left, landing on your left foot.", "As you land, swing your right leg behind your left leg and tap the ground with your right toes.", "Continue alternating sides, jumping and tapping the ground with each leg.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros.", "Dobla ligeramente las rodillas y salta hacia la derecha, aterrizando sobre el pie derecho.", "Al aterrizar, balancea la pierna izquierda detrás de la pierna derecha y toca el suelo con los dedos del pie izquierdo.", "Salta inmediatamente hacia la izquierda, aterrizando sobre el pie izquierdo.", "Al aterrizar, balancea la pierna derecha detrás de la pierna izquierda y toca el suelo con los dedos del pie derecho.", "Continúa alternando los lados, saltando y tocando el suelo con cada pierna.", "Repite el número de repeticiones deseado."]'),
  ('Zancada Caminando con Rodilla Alta', 'walking-high-knees-lunge.gif', 'cardio', '["Stand with your feet hip-width apart.", "Lift your right knee up towards your chest as high as you can while balancing on your left leg.", "Step forward with your right foot and lower your body into a lunge position, bending both knees to a 90-degree angle.", "Push off with your right foot and bring your left knee up towards your chest.", "Step forward with your left foot and lower your body into a lunge position.", "Continue alternating legs and lunging forward, keeping your core engaged and maintaining a steady pace.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de la cadera.", "Levanta la rodilla derecha hacia el pecho lo más alto que puedas mientras mantienes el equilibrio sobre la pierna izquierda.", "Da un paso adelante con el pie derecho y baja el cuerpo a una posición de zancada, flexionando ambas rodillas a un ángulo de 90 grados.", "Empújate con el pie derecho y lleva la rodilla izquierda hacia el pecho.", "Da un paso adelante con el pie izquierdo y baja el cuerpo a una posición de zancada.", "Continúa alternando las piernas y avanzando con zancadas, manteniendo el core activado y un ritmo constante.", "Repite el número de repeticiones deseado."]'),
  ('Apertura a 1 Brazo con Mancuerna en Banco Plano', 'dumbbell-one-arm-bench-fly.gif', 'chest', '["Sit on a flat bench with a dumbbell in one hand, resting it on top of your thigh.", "Lie back on the bench, keeping the dumbbell pressed against your thigh.", "Using your free hand, help lift the dumbbell up to the starting position.", "Hold the dumbbell directly above your shoulder with your arm extended and palm facing inward.", "Lower the dumbbell out to the side in a wide arc, keeping a slight bend in your elbow.", "Pause when your arm is parallel to the ground, then reverse the movement and bring the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch arms and repeat."]', '["Siéntate en un banco plano con una mancuerna en una mano, apoyándola sobre el muslo.", "Recuéstate en el banco, manteniendo la mancuerna presionada contra el muslo.", "Usando la mano libre, ayuda a levantar la mancuerna hasta la posición inicial.", "Sostén la mancuerna directamente sobre el hombro con el brazo extendido y la palma hacia adentro.", "Baja la mancuerna hacia el lado describiendo un amplio arco, manteniendo una ligera flexión en el codo.", "Haz una pausa cuando el brazo esté paralelo al suelo, luego invierte el movimiento y lleva la mancuerna de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de brazo y repite."]'),
  ('Apertura a 1 Brazo con Mancuerna sobre Fitball', 'dumbbell-one-arm-chest-fly-on-exercise-ball.gif', 'chest', '["Sit on an exercise ball with a dumbbell in one hand and your feet flat on the ground.", "Walk your feet forward, rolling the ball until your upper back is supported on the ball and your head, neck, and shoulders are off the ball.", "Extend your arm with the dumbbell straight up above your chest, palm facing inward.", "Slowly lower the dumbbell out to the side, keeping a slight bend in your elbow.", "Pause for a moment when your arm is parallel to the ground.", "Engage your chest muscles to bring the dumbbell back up to the starting position.", "Repeat for the desired number of repetitions, then switch arms."]', '["Siéntate sobre un balón de estabilidad con una mancuerna en una mano y los pies apoyados en el suelo.", "Camina con los pies hacia adelante, haciendo rodar el balón hasta que la parte superior de la espalda quede apoyada en el balón y la cabeza, el cuello y los hombros queden fuera de él.", "Extiende el brazo con la mancuerna recto hacia arriba sobre el pecho, con la palma hacia adentro.", "Baja lentamente la mancuerna hacia el lado, manteniendo una ligera flexión en el codo.", "Haz una pausa por un momento cuando el brazo esté paralelo al suelo.", "Activa los músculos del pecho para llevar la mancuerna de nuevo hacia arriba hasta la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de brazo."]'),
  ('Apertura a 1 Brazo en Polea sobre Fitball', 'cable-one-arm-fly-on-exercise-ball.gif', 'chest', '["Sit on an exercise ball with your feet flat on the ground and your back straight.", "Hold a cable handle in one hand and extend your arm out to the side, parallel to the ground.", "Keep your elbow slightly bent and your palm facing forward.", "Slowly bring your arm across your body, squeezing your chest muscles.", "Pause for a moment at the end of the movement, then slowly return to the starting position.", "Repeat for the desired number of repetitions, then switch sides."]', '["Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta.", "Sujeta una agarradera del cable con una mano y extiende el brazo hacia el lado, paralelo al suelo.", "Mantén el codo ligeramente flexionado y la palma hacia adelante.", "Lleva lentamente el brazo a través del cuerpo, apretando los músculos del pecho.", "Haz una pausa por un momento al final del movimiento, luego regresa lentamente a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de lado."]'),
  ('Apertura Declinada a 1 Brazo con Mancuerna', 'dumbbell-decline-one-arm-fly.gif', 'chest', '["Lie down on a decline bench with a dumbbell in one hand, resting it on your thigh.", "Using your thigh to help raise the dumbbell, lift it up to shoulder width with your palm facing your torso.", "Rotate your wrist so that the palm of your hand is facing forward.", "As you breathe in, lower the dumbbell slowly to the side until you feel a stretch in your chest.", "Exhale and use your chest muscles to bring the dumbbell back up to the starting position.", "Repeat for the desired number of repetitions, then switch arms."]', '["Túmbate en un banco declinado con una mancuerna en una mano, apoyándola sobre el muslo.", "Usando el muslo para ayudar a levantar la mancuerna, álzala hasta la altura de los hombros con la palma mirando hacia el torso.", "Gira la muñeca de modo que la palma de la mano quede mirando hacia adelante.", "Mientras inhalas, baja la mancuerna lentamente hacia el lado hasta sentir un estiramiento en el pecho.", "Exhala y usa los músculos del pecho para llevar la mancuerna de nuevo hacia arriba hasta la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de brazo."]'),
  ('Apertura Declinada a 1 Brazo en Polea', 'cable-one-arm-decline-chest-fly.gif', 'chest', '["Attach a D-handle to a low pulley cable machine and set the bench to a decline angle.", "Lie down on the bench with your head towards the machine and grab the handle with your right hand.", "Extend your arm straight up above your chest, keeping a slight bend in your elbow.", "With a controlled motion, lower your arm out to the side until your hand is in line with your shoulder.", "Pause for a moment, then reverse the motion and bring your arm back to the starting position.", "Repeat for the desired number of repetitions, then switch to your left arm and repeat the exercise."]', '["Sujeta una agarradera en D a una máquina de cable con polea baja y coloca el banco en un ángulo declinado.", "Túmbate en el banco con la cabeza orientada hacia la máquina y agarra la agarradera con la mano derecha.", "Extiende el brazo recto por encima del pecho, manteniendo una ligera flexión en el codo.", "Con un movimiento controlado, baja el brazo hacia el lado hasta que la mano quede alineada con el hombro.", "Haz una pausa por un momento y luego invierte el movimiento para regresar el brazo a la posición inicial.", "Repite el número de repeticiones deseado y luego cambia al brazo izquierdo y repite el ejercicio."]'),
  ('Apertura en el Suelo con Barra', 'floor-fly-with-barbell.gif', 'chest', '["Lie flat on your back on the floor with your knees bent and feet flat on the ground.", "Hold a barbell with an overhand grip, arms extended straight up over your chest.", "Slowly lower the barbell out to the sides, keeping a slight bend in your elbows.", "Lower the barbell until your arms are parallel to the floor, feeling a stretch in your chest.", "Pause for a moment, then squeeze your chest muscles to bring the barbell back to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate boca arriba en el suelo con las rodillas flexionadas y los pies planos sobre el suelo.", "Sostén una barra con agarre prono, brazos extendidos rectos por encima del pecho.", "Baja lentamente la barra hacia los lados, manteniendo una ligera flexión en los codos.", "Baja la barra hasta que los brazos queden paralelos al suelo, sintiendo un estiramiento en el pecho.", "Haz una pausa breve, luego contrae los músculos del pecho para llevar la barra de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Apertura Inclinada a 1 Brazo con Mancuerna', 'dumbbell-incline-one-arm-fly.gif', 'chest', '["Adjust the incline bench to a 30-45 degree angle.", "Sit on the bench with a dumbbell in one hand, resting it on your thigh.", "Lie back on the bench, keeping your feet flat on the ground.", "Hold the dumbbell with your arm extended straight up over your chest.", "Lower the dumbbell out to the side in a wide arc, keeping a slight bend in your elbow.", "Pause when your arm is parallel to the ground, then reverse the motion to bring the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch arms."]', '["Ajusta el banco inclinado a un ángulo de 30-45 grados.", "Siéntate en el banco con una mancuerna en una mano, apoyándola sobre el muslo.", "Recuéstate en el banco, manteniendo los pies apoyados en el suelo.", "Sostén la mancuerna con el brazo extendido recto hacia arriba sobre el pecho.", "Baja la mancuerna hacia el lado describiendo un amplio arco, manteniendo una ligera flexión en el codo.", "Haz una pausa cuando el brazo esté paralelo al suelo, luego invierte el movimiento para llevar la mancuerna de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de brazo."]'),
  ('Apertura Inclinada a 1 Brazo con Mancuerna sobre Fitball', 'dumbbell-incline-one-arm-fly-on-exercise-ball.gif', 'chest', '["Sit on an exercise ball with a dumbbell in one hand.", "Walk your feet forward and roll your body down until your head, neck, and upper back are supported on the ball.", "Hold the dumbbell with your arm extended straight up over your chest, palm facing inwards.", "Slowly lower the dumbbell out to the side, keeping a slight bend in your elbow.", "Pause for a moment when your arm is parallel to the ground.", "Engage your chest muscles to bring the dumbbell back up to the starting position.", "Repeat for the desired number of repetitions, then switch arms."]', '["Siéntate sobre un balón de estabilidad con una mancuerna en una mano.", "Camina con los pies hacia adelante y baja el cuerpo rodando hasta que la cabeza, el cuello y la parte superior de la espalda queden apoyados sobre el balón.", "Sostén la mancuerna con el brazo extendido recto hacia arriba sobre el pecho, con la palma hacia adentro.", "Baja lentamente la mancuerna hacia el lado, manteniendo una ligera flexión en el codo.", "Haz una pausa por un momento cuando el brazo esté paralelo al suelo.", "Activa los músculos del pecho para llevar la mancuerna de nuevo hacia arriba hasta la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de brazo."]'),
  ('Apertura Inclinada a 1 Brazo en Polea sobre Fitball', 'cable-one-arm-incline-fly-on-exercise-ball.gif', 'chest', '["Sit on an exercise ball with your feet flat on the ground and your back against an incline bench.", "Hold a cable handle in one hand with your arm extended and palm facing inward.", "Keeping a slight bend in your elbow, slowly lower your arm out to the side until your hand is in line with your shoulder.", "Pause for a moment, then squeeze your chest muscles to bring your arm back to the starting position.", "Repeat for the desired number of repetitions, then switch arms."]', '["Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda contra un banco inclinado.", "Sujeta una agarradera del cable con una mano, con el brazo extendido y la palma hacia adentro.", "Manteniendo una ligera flexión en el codo, baja lentamente el brazo hacia el lado hasta que la mano quede alineada con el hombro.", "Haz una pausa por un momento y luego aprieta los músculos del pecho para regresar el brazo a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de brazo."]'),
  ('Aperturas Altas con Mancuernas Sentado', 'hyght-dumbbell-fly.gif', 'chest', '["Lie flat on a bench with a dumbbell in each hand, palms facing each other.", "Extend your arms straight up over your chest, with a slight bend in your elbows.", "Keeping a slight bend in your elbows, lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.", "Pause for a moment, then reverse the movement and bring the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate boca arriba en un banco con una mancuerna en cada mano, con las palmas enfrentadas entre sí.", "Extiende los brazos rectos hacia arriba sobre el pecho, con una ligera flexión en los codos.", "Manteniendo una ligera flexión en los codos, baja las mancuernas hacia los lados describiendo un amplio arco hasta sentir un estiramiento en el pecho.", "Haz una pausa por un momento, luego invierte el movimiento y lleva las mancuernas de nuevo hacia arriba hasta la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Aperturas con Mancuernas a 1 Pierna sobre Fitball', 'dumbbell-one-leg-fly-on-exercise-ball.gif', 'chest', '["Sit on an exercise ball with a dumbbell in each hand, palms facing each other.", "Place one foot on the ground and extend the other leg straight out in front of you.", "Lean forward slightly and bring your arms out to the sides, keeping a slight bend in your elbows.", "Slowly lower the dumbbells down and out to the sides, feeling a stretch in your chest.", "Pause for a moment at the bottom, then squeeze your chest muscles to bring the dumbbells back up to the starting position.", "Repeat for the desired number of repetitions, then switch legs and repeat."]', '["Siéntate sobre un balón de estabilidad con una mancuerna en cada mano, con las palmas enfrentadas entre sí.", "Coloca un pie en el suelo y extiende la otra pierna recta hacia adelante.", "Inclínate ligeramente hacia adelante y lleva los brazos hacia los lados, manteniendo una ligera flexión en los codos.", "Baja lentamente las mancuernas hacia abajo y hacia los lados, sintiendo un estiramiento en el pecho.", "Haz una pausa por un momento en la parte inferior, luego contrae los músculos del pecho para llevar las mancuernas de nuevo hacia arriba hasta la posición inicial.", "Repite el número de repeticiones deseado y luego cambia de pierna y repite."]'),
  ('Aperturas con Mancuernas sobre Fitball', 'dumbbell-fly-on-exercise-ball.gif', 'chest', '["Sit on an exercise ball and hold a dumbbell in each hand.", "Walk your feet forward and roll your body down until your head, neck, and upper back are supported by the ball.", "Extend your arms straight up above your chest, palms facing each other.", "Bend your elbows slightly and lower your arms out to the sides in a wide arc until you feel a stretch in your chest.", "Pause for a moment, then reverse the movement and squeeze your chest muscles as you bring the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate sobre un balón de estabilidad y sostén una mancuerna en cada mano.", "Camina con los pies hacia adelante y baja el cuerpo rodando hasta que la cabeza, el cuello y la parte superior de la espalda queden apoyados sobre el balón.", "Extiende los brazos rectos por encima del pecho, con las palmas enfrentadas entre sí.", "Flexiona ligeramente los codos y baja los brazos hacia los lados describiendo un amplio arco hasta sentir un estiramiento en el pecho.", "Haz una pausa por un momento, luego invierte el movimiento y contrae los músculos del pecho mientras llevas las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Aperturas Declinadas con Giro con Mancuernas', 'dumbbell-decline-twist-fly.gif', 'chest', '["Lie down on a decline bench with your head lower than your hips.", "Hold a dumbbell in each hand with your palms facing each other and your arms extended straight up over your chest.", "Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.", "As you lower the dumbbells, twist your wrists so that your palms face forward at the bottom of the movement.", "Reverse the motion and bring the dumbbells back up to the starting position, squeezing your chest muscles at the top.", "Repeat for the desired number of repetitions."]', '["Túmbate en un banco declinado con la cabeza más baja que las caderas.", "Sostén una mancuerna en cada mano con las palmas enfrentadas entre sí y los brazos extendidos rectos hacia arriba sobre el pecho.", "Baja las mancuernas hacia los lados describiendo un amplio arco hasta sentir un estiramiento en el pecho.", "Mientras bajas las mancuernas, gira las muñecas de modo que las palmas queden mirando hacia adelante en la parte inferior del movimiento.", "Invierte el movimiento y lleva las mancuernas de nuevo hacia arriba hasta la posición inicial, contrayendo los músculos del pecho en la parte superior.", "Repite el número de repeticiones deseado."]'),
  ('Aperturas Declinadas con Mancuernas', 'dumbbell-decline-fly.gif', 'chest', '["Lie on a decline bench with your feet secured and your head lower than your hips.", "Hold a dumbbell in each hand with your palms facing each other and your arms extended above your chest.", "Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.", "Pause for a moment, then squeeze your chest muscles to bring the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate en un banco declinado con los pies sujetos y la cabeza más baja que las caderas.", "Sostén una mancuerna en cada mano con las palmas enfrentadas entre sí y los brazos extendidos por encima del pecho.", "Baja las mancuernas hacia los lados describiendo un amplio arco hasta sentir un estiramiento en el pecho.", "Haz una pausa por un momento, luego contrae los músculos del pecho para llevar las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Aperturas Inclinadas con Giro con Mancuernas', 'dumbbell-incline-twisted-flyes.gif', 'chest', '["Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing each other.", "Lie back on the bench and press the dumbbells up to the starting position, directly above your chest, with your arms extended.", "Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.", "As you lower the dumbbells, rotate your wrists so that your palms face forward at the bottom of the movement.", "Reverse the motion and bring the dumbbells back up to the starting position, squeezing your chest muscles together at the top.", "Repeat for the desired number of repetitions."]', '["Ajusta un banco inclinado a un ángulo de 45 grados y siéntate en él con una mancuerna en cada mano, con las palmas enfrentadas entre sí.", "Recuéstate en el banco y empuja las mancuernas hacia arriba hasta la posición inicial, directamente por encima del pecho, con los brazos extendidos.", "Baja las mancuernas hacia los lados describiendo un amplio arco hasta sentir un estiramiento en el pecho.", "Mientras bajas las mancuernas, gira las muñecas de modo que las palmas queden mirando hacia adelante en la parte inferior del movimiento.", "Invierte el movimiento y lleva las mancuernas de nuevo hacia arriba hasta la posición inicial, contrayendo los músculos del pecho en la parte superior.", "Repite el número de repeticiones deseado."]'),
  ('Aperturas Inclinadas con Mancuernas', 'dumbbell-incline-fly.gif', 'chest', '["Set an incline bench to a 45-degree angle.", "Sit on the bench with a dumbbell in each hand, palms facing each other.", "Lie back on the bench and press the dumbbells up to the starting position, directly above your chest.", "Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.", "Pause for a moment, then squeeze your chest muscles to bring the dumbbells back up to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta un banco inclinado a un ángulo de 45 grados.", "Siéntate en el banco con una mancuerna en cada mano, con las palmas enfrentadas entre sí.", "Recuéstate en el banco y empuja las mancuernas hacia arriba hasta la posición inicial, directamente por encima del pecho.", "Baja las mancuernas hacia los lados describiendo un amplio arco hasta sentir un estiramiento en el pecho.", "Haz una pausa por un momento, luego contrae los músculos del pecho para llevar las mancuernas de nuevo hacia arriba hasta la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Aperturas Inclinadas con Mancuernas sobre Fitball', 'dumbbell-incline-fly-on-exercise-ball.gif', 'chest', '["Set up an incline bench at a 45-degree angle.", "Sit on an exercise ball and roll forward until your upper back is resting on the incline bench.", "Hold a dumbbell in each hand with your palms facing each other and your arms extended above your chest.", "Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.", "Pause for a moment, then squeeze your chest muscles to bring the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."]', '["Coloca un banco inclinado a un ángulo de 45 grados.", "Siéntate sobre un balón de estabilidad y rueda hacia adelante hasta que la parte superior de la espalda quede apoyada en el banco inclinado.", "Sostén una mancuerna en cada mano con las palmas enfrentadas entre sí y los brazos extendidos por encima del pecho.", "Baja las mancuernas hacia los lados describiendo un amplio arco hasta sentir un estiramiento en el pecho.", "Haz una pausa por un momento, luego contrae los músculos del pecho para llevar las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Aperturas Inclinadas en Polea sobre Fitball', 'cable-incline-fly-on-stability-ball.gif', 'chest', '["Set up a stability ball at an incline angle.", "Attach the cable handles to the high pulleys of a cable machine.", "Sit on the stability ball facing away from the machine, with your feet firmly planted on the ground.", "Grasp the cable handles with an overhand grip, palms facing forward.", "Lean forward slightly, keeping your back straight and core engaged.", "With a controlled motion, bring your arms out to the sides, keeping a slight bend in your elbows.", "Continue the motion until your arms are parallel to the ground.", "Pause for a moment, then slowly return to the starting position.", "Repeat for the desired number of repetitions."]', '["Coloca un balón de estabilidad en un ángulo inclinado.", "Sujeta las agarraderas del cable a las poleas altas de una máquina de cable.", "Siéntate sobre el balón de estabilidad de espaldas a la máquina, con los pies firmemente apoyados en el suelo.", "Sujeta las agarraderas del cable con un agarre prono, con las palmas hacia adelante.", "Inclínate ligeramente hacia adelante, manteniendo la espalda recta y el core activado.", "Con un movimiento controlado, lleva los brazos hacia los lados, manteniendo una ligera flexión en los codos.", "Continúa el movimiento hasta que los brazos queden paralelos al suelo.", "Haz una pausa por un momento, luego regresa lentamente a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Aperturas Tumbado en Polea', 'cable-lying-fly.gif', 'chest', '["Attach the handles to the cables and lie flat on a bench with your feet flat on the ground.", "Hold the handles with your palms facing each other and your arms extended straight above your chest.", "Keeping a slight bend in your elbows, lower your arms out to the sides in a wide arc until you feel a stretch in your chest.", "Pause for a moment, then squeeze your chest muscles to bring your arms back to the starting position.", "Repeat for the desired number of repetitions."]', '["Sujeta las agarraderas a los cables y túmbate boca arriba en un banco con los pies apoyados planos en el suelo.", "Sujeta las agarraderas con las palmas una frente a la otra y los brazos extendidos rectos por encima del pecho.", "Manteniendo una ligera flexión en los codos, baja los brazos hacia los lados en un amplio arco hasta sentir un estiramiento en el pecho.", "Haz una pausa por un momento y luego aprieta los músculos del pecho para regresar los brazos a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Contracción Isométrica de Pecho', 'isometric-chest-squeeze.gif', 'chest', '["Stand with your feet shoulder-width apart and your knees slightly bent.", "Extend your arms straight out in front of you, parallel to the ground, with your palms facing each other.", "Squeeze your chest muscles together as hard as you can, while keeping your arms straight.", "Hold this position for a few seconds, focusing on contracting your chest muscles.", "Release the squeeze and relax your chest muscles.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.", "Extiende los brazos rectos frente a ti, paralelos al suelo, con las palmas una frente a la otra.", "Aprieta los músculos del pecho con la mayor fuerza posible, manteniendo los brazos rectos.", "Mantén esta posición durante unos segundos, concentrándote en contraer los músculos del pecho.", "Suelta la contracción y relaja los músculos del pecho.", "Repite el número de repeticiones deseado."]'),
  ('Cruce de Poleas (Variante)', 'cable-cross-over-variation.gif', 'chest', '["Adjust the cable pulleys to chest height.", "Stand in the center of the cable machine with one foot in front of the other.", "Grasp the handles with your palms facing down and your arms extended out to the sides.", "Take a step forward, keeping your arms slightly bent.", "With a slight bend in your elbows, bring your hands together in front of your chest.", "Pause for a moment, then slowly return your arms back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta las poleas del cable a la altura del pecho.", "Ponte de pie en el centro de la máquina de cable con un pie delante del otro.", "Sujeta las agarraderas con las palmas hacia abajo y los brazos extendidos hacia los lados.", "Da un paso hacia adelante, manteniendo los brazos ligeramente flexionados.", "Con una ligera flexión en los codos, junta las manos frente al pecho.", "Haz una pausa breve, luego vuelve lentamente los brazos a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Cruce de Poleas de Pie con Torso Erguido', 'cable-standing-up-straight-crossovers.gif', 'chest', '["Stand in the middle of a cable machine with your feet shoulder-width apart.", "Hold the handles of the cables with your palms facing down and your arms extended straight out to the sides.", "Keeping your arms straight, bring your hands together in front of your body, crossing them over each other.", "Pause for a moment, then slowly return to the starting position, keeping your arms extended.", "Repeat for the desired number of repetitions."]', '["Ponte de pie en el medio de una máquina de cable con los pies separados a la altura de los hombros.", "Sujeta los mangos de los cables con las palmas hacia abajo y los brazos extendidos hacia los lados.", "Manteniendo los brazos rectos, junta las manos frente a tu cuerpo, cruzándolas una sobre la otra.", "Haz una pausa breve, luego regresa lentamente a la posición inicial, manteniendo los brazos extendidos.", "Repite el número de repeticiones deseado."]'),
  ('Cruce de Poleas para Pecho Superior', 'cable-upper-chest-crossovers.gif', 'chest', '["Attach the handles to the cables at chest height.", "Stand in the center of the cable machine with one foot slightly in front of the other.", "Grasp the handles with your palms facing down and your arms extended out to the sides.", "Keep a slight bend in your elbows and engage your core.", "Pull the cables together in front of your chest, crossing them over each other.", "Squeeze your chest muscles at the peak of the movement.", "Slowly release the cables back to the starting position.", "Repeat for the desired number of repetitions."]', '["Coloca los mangos en los cables a la altura del pecho.", "Ponte de pie en el centro de la máquina de cable con un pie ligeramente delante del otro.", "Sujeta las agarraderas con las palmas hacia abajo y los brazos extendidos hacia los lados.", "Mantén una ligera flexión en los codos y activa el core.", "Tira de los cables juntos frente al pecho, cruzándolos uno sobre el otro.", "Aprieta los músculos del pecho en el punto máximo del movimiento.", "Suelta lentamente los cables de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación de Hombros con Barra en Banco Inclinado', 'barbell-incline-shoulder-raise.gif', 'chest', '["Set up an incline bench at a 45-degree angle.", "Sit on the bench with your back against the pad and feet flat on the ground.", "Hold a barbell with an overhand grip, slightly wider than shoulder-width apart.", "Lift the barbell up to shoulder height, keeping your elbows slightly bent.", "Slowly raise the barbell overhead, extending your arms fully.", "Pause for a moment at the top, then slowly lower the barbell back to shoulder height.", "Repeat for the desired number of repetitions."]', '["Coloca un banco inclinado a un ángulo de 45 grados.", "Siéntate en el banco con la espalda apoyada en el respaldo y los pies planos sobre el suelo.", "Sujeta una barra con un agarre pronado, un poco más ancho que la separación de los hombros.", "Levanta la barra hasta la altura de los hombros, manteniendo los codos ligeramente flexionados.", "Levanta lentamente la barra por encima de la cabeza, extendiendo completamente los brazos.", "Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la altura de los hombros.", "Repite el número de repeticiones deseado."]'),
  ('Elevación de Hombros con Mancuernas en Banco Inclinado', 'dumbbell-incline-shoulder-raise.gif', 'chest', '["Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing down.", "Rest the dumbbells on your thighs and lean back onto the bench.", "Use your thighs to help raise the dumbbells to shoulder height, then rotate your wrists so that your palms are facing forward.", "Exhale and slowly raise the dumbbells above your head, keeping a slight bend in your elbows.", "Pause for a moment at the top, then inhale and slowly lower the dumbbells back to shoulder height.", "Repeat for the desired number of repetitions."]', '["Ajusta un banco inclinado a un ángulo de 45 grados y siéntate en él con una mancuerna en cada mano, con las palmas hacia abajo.", "Apoya las mancuernas sobre los muslos y recuéstate en el banco.", "Usa los muslos para ayudar a levantar las mancuernas hasta la altura de los hombros, luego gira las muñecas de modo que las palmas queden mirando hacia adelante.", "Exhala y levanta lentamente las mancuernas por encima de la cabeza, manteniendo una ligera flexión en los codos.", "Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente las mancuernas de vuelta a la altura de los hombros.", "Repite el número de repeticiones deseado."]'),
  ('Elevación de Hombros en Banco Inclinado en Máquina Smith', 'smith-incline-shoulder-raises.gif', 'chest', '["Adjust the smith machine to an incline position.", "Stand facing the machine with your feet shoulder-width apart.", "Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.", "Keep your back straight and core engaged.", "Raise the barbell up towards the ceiling, leading with your elbows.", "Pause for a moment at the top, then slowly lower the barbell back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta la máquina Smith a una posición inclinada.", "Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.", "Sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros.", "Mantén la espalda recta y el core activado.", "Eleva la barra hacia el techo, guiando el movimiento con los codos.", "Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación Frontal y Pullover con Barra', 'barbell-front-raise-and-pullover.gif', 'chest', '["Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, palms facing down.", "Keep your arms straight and raise the barbell in front of you until it reaches shoulder height.", "Pause for a moment at the top, then slowly lower the barbell back down to the starting position.", "Next, lower the barbell behind your head, keeping your arms straight.", "Pause for a moment at the bottom, then raise the barbell back up to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con un agarre pronado, con las palmas hacia abajo.", "Mantén los brazos rectos y levanta la barra frente a ti hasta que alcance la altura de los hombros.", "Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.", "A continuación, baja la barra detrás de la cabeza, manteniendo los brazos rectos.", "Haz una pausa breve en la parte baja y luego levanta la barra de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación Lateral Inclinada a 1 Brazo en Polea', 'cable-one-arm-lateral-bent-over.gif', 'chest', '["Stand with your feet shoulder-width apart, facing a cable machine.", "Grasp the handle with one hand and step back to create tension on the cable.", "Bend forward at the waist, keeping your back straight and your core engaged.", "Extend your arm out to the side, parallel to the ground, with a slight bend in your elbow.", "Slowly bring your arm back to the starting position, maintaining control throughout the movement.", "Repeat for the desired number of repetitions, then switch sides."]', '["Ponte de pie con los pies separados a la altura de los hombros, frente a una máquina de cable.", "Sujeta la agarradera con una mano y retrocede un paso para crear tensión en el cable.", "Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y el core activado.", "Extiende el brazo hacia el lado, paralelo al suelo, con una ligera flexión en el codo.", "Regresa lentamente el brazo a la posición inicial, manteniendo el control durante todo el movimiento.", "Repite el número de repeticiones deseado, luego cambia de lado."]'),
  ('Empuje de Pecho con Balón Medicinal (Respuesta Múltiple)', 'medicine-ball-chest-push-multiple-response.gif', 'chest', '["Stand with your feet shoulder-width apart, holding a medicine ball at chest level.", "Extend your arms forward, pushing the medicine ball away from your chest.", "Pause for a moment, then slowly bring the medicine ball back to your chest.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo un balón medicinal a la altura del pecho.", "Extiende los brazos hacia adelante, alejando el balón medicinal de tu pecho.", "Haz una pausa por un momento y luego lleva lentamente el balón medicinal de vuelta al pecho.", "Repite el número de repeticiones deseado."]'),
  ('Empuje de Pecho con Balón Medicinal (Respuesta Simple)', 'medicine-ball-chest-push-single-response.gif', 'chest', '["Stand with your feet shoulder-width apart, holding the medicine ball at chest level.", "Extend your arms forward, pushing the medicine ball away from your chest.", "Pause for a moment, then slowly bring the medicine ball back to your chest.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo el balón medicinal a la altura del pecho.", "Extiende los brazos hacia adelante, alejando el balón medicinal de tu pecho.", "Haz una pausa por un momento y luego lleva lentamente el balón medicinal de vuelta al pecho.", "Repite el número de repeticiones deseado."]'),
  ('Empuje de Pecho con Balón Medicinal desde 3 Apoyos', 'medicine-ball-chest-push-from-3-point-stance.gif', 'chest', '["Start in a 3 point stance with one hand on the medicine ball and the other hand on the ground.", "Extend your legs and position your body in a straight line.", "Lower your chest towards the ground while keeping your back straight.", "Push the medicine ball away from your body, extending your arm fully.", "Return to the starting position and repeat for the desired number of repetitions."]', '["Comienza en una posición de apoyo de 3 puntos con una mano sobre el balón medicinal y la otra en el suelo.", "Extiende las piernas y coloca tu cuerpo en línea recta.", "Baja el pecho hacia el suelo manteniendo la espalda recta.", "Empuja el balón medicinal alejándolo de tu cuerpo, extendiendo completamente el brazo.", "Vuelve a la posición inicial y repite el número de repeticiones deseado."]'),
  ('Empuje de Pecho con Balón Medicinal y Salida en Carrera', 'medicine-ball-chest-push-with-run-release.gif', 'chest', '["Stand with your feet shoulder-width apart, holding a medicine ball at chest level.", "Step forward with your right foot and simultaneously push the medicine ball forward, extending your arms fully.", "As you push the ball forward, release it and let it roll forward.", "Quickly run forward and catch the ball before it hits the ground.", "Once you catch the ball, bring it back to your chest and repeat the movement with your left foot forward.", "Continue alternating legs and repeating the exercise for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo un balón medicinal a la altura del pecho.", "Da un paso adelante con el pie derecho y, al mismo tiempo, empuja el balón medicinal hacia adelante, extendiendo completamente los brazos.", "Mientras empujas el balón hacia adelante, suéltalo y déjalo rodar.", "Corre rápidamente hacia adelante y atrapa el balón antes de que toque el suelo.", "Una vez que atrapes el balón, llévalo de vuelta al pecho y repite el movimiento con el pie izquierdo adelante.", "Continúa alternando piernas y repitiendo el ejercicio el número de repeticiones deseado."]'),
  ('Empuje y Tirón con Peso Corporal', 'push-and-pull-bodyweight.gif', 'chest', '["Start in a push-up position with your hands slightly wider than shoulder-width apart and your body in a straight line.", "Lower your chest towards the ground by bending your elbows, keeping your body straight.", "Push through your palms to extend your arms and return to the starting position.", "From the push-up position, pull your chest towards the ground by bending your elbows, keeping your body straight.", "Push through your palms to extend your arms and return to the starting position.", "Repeat for the desired number of repetitions."]', '["Comienza en posición de flexión con las manos un poco más separadas que la anchura de los hombros y el cuerpo en línea recta.", "Baja el pecho hacia el suelo flexionando los codos, manteniendo el cuerpo recto.", "Empuja con las palmas para extender los brazos y regresar a la posición inicial.", "Desde la posición de flexión, tira del pecho hacia el suelo flexionando los codos, manteniendo el cuerpo recto.", "Empuja con las palmas para extender los brazos y regresar a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Ergómetro de Brazos', 'hands-bike.gif', 'chest', '["Adjust the seat height and handlebar position to a comfortable level.", "Sit on the ergometer with your back straight and feet on the pedals.", "Grasp the handles with your hands and position your arms at a 90-degree angle.", "Start pedaling with your hands, pushing and pulling the handles in a controlled motion.", "Continue pedaling for the desired duration or number of repetitions."]', '["Ajusta la altura del asiento y la posición del manillar a un nivel cómodo.", "Siéntate en el ergómetro con la espalda recta y los pies sobre los pedales.", "Sujeta las asas con las manos y coloca los brazos en un ángulo de 90 grados.", "Comienza a pedalear con las manos, empujando y tirando de las asas con un movimiento controlado.", "Continúa pedaleando durante el tiempo o el número de repeticiones deseado."]'),
  ('Estiramiento Asistido de Pecho con Manos tras la Cabeza', 'behind-head-chest-stretch.gif', 'chest', '["Stand tall with your feet shoulder-width apart.", "Interlace your fingers behind your head with your elbows pointing outwards.", "Slowly squeeze your shoulder blades together and push your chest forward.", "Hold the stretch for 15-30 seconds.", "Release the stretch and repeat as desired."]', '["Ponte de pie con la espalda recta y los pies separados a la altura de los hombros.", "Entrelaza los dedos detrás de la cabeza con los codos apuntando hacia afuera.", "Junta lentamente los omóplatos y empuja el pecho hacia adelante.", "Mantén el estiramiento durante 15-30 segundos.", "Suelta el estiramiento y repite cuantas veces lo desees."]'),
  ('Estiramiento Asistido de Pectoral Sentado en Fitball', 'assisted-seated-pectoralis-major-stretch-with-stability-ball.gif', 'chest', '["Sit on a stability ball with your feet flat on the ground and your back straight.", "Hold a stability ball with both hands and extend your arms straight out in front of you.", "Slowly lower the stability ball towards your chest, feeling a stretch in your pectoral muscles.", "Hold the stretch for a few seconds, then slowly return to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate sobre un balón de estabilidad con los pies apoyados en el suelo y la espalda recta.", "Sostén un balón de estabilidad con ambas manos y extiende los brazos rectos frente a ti.", "Baja lentamente el balón de estabilidad hacia el pecho, sintiendo un estiramiento en los pectorales.", "Mantén el estiramiento durante unos segundos, luego regresa lentamente a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Estiramiento de Pecho con Fitball', 'chest-stretch-with-exercise-ball.gif', 'chest', '["Sit on the stability ball with your feet flat on the ground and your back straight.", "Hold the exercise ball with both hands and extend your arms straight out in front of you.", "Slowly bring the exercise ball towards your chest, feeling a stretch in your chest muscles.", "Hold the stretch for a few seconds, then slowly return to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en el balón de estabilidad con los pies planos en el suelo y la espalda recta.", "Sujeta el balón de ejercicio con ambas manos y extiende los brazos rectos frente a ti.", "Lleva lentamente el balón de ejercicio hacia tu pecho, sintiendo un estiramiento en los músculos del pecho.", "Mantén el estiramiento durante unos segundos, luego regresa lentamente a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Estiramiento de Pecho y Hombro Anterior', 'chest-and-front-of-shoulder-stretch.gif', 'chest', '["Stand tall with your feet shoulder-width apart.", "Extend your arms straight out in front of you at shoulder height.", "Cross your arms in front of your body, with your right arm on top of your left arm.", "Interlace your fingers and press your palms together.", "Gently squeeze your shoulder blades together and push your hands forward, feeling a stretch in your chest and front of your shoulders.", "Hold the stretch for 20-30 seconds, then release.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con la espalda recta y los pies separados a la altura de los hombros.", "Extiende los brazos rectos frente a ti a la altura de los hombros.", "Cruza los brazos frente a tu cuerpo, con el brazo derecho sobre el brazo izquierdo.", "Entrelaza los dedos y presiona las palmas entre sí.", "Aprieta suavemente los omóplatos entre sí y empuja las manos hacia adelante, sintiendo un estiramiento en el pecho y la parte delantera de los hombros.", "Mantén el estiramiento durante 20-30 segundos, luego suelta.", "Repite el número de repeticiones deseado."]'),
  ('Estiramiento Dinámico de Pecho', 'dynamic-chest-stretch-male.gif', 'chest', '["Stand tall with your feet shoulder-width apart.", "Extend your arms straight out to the sides, parallel to the ground.", "Slowly bring your arms forward, crossing them in front of your body.", "Feel the stretch in your chest muscles.", "Hold the stretch for 10-30 seconds.", "Return to the starting position and repeat for the desired number of repetitions."]', '["Ponte de pie con la espalda recta y los pies separados a la altura de los hombros.", "Extiende los brazos hacia los lados, paralelos al suelo.", "Lleva lentamente los brazos hacia adelante, cruzándolos frente al cuerpo.", "Siente el estiramiento en los músculos del pecho.", "Mantén el estiramiento durante 10-30 segundos.", "Vuelve a la posición inicial y repite el número de repeticiones deseado."]'),
  ('Flexión a 1 Brazo', 'single-arm-push-up.gif', 'chest', '["Start in a push-up position with your hands shoulder-width apart and one hand placed slightly wider than the other.", "Engage your core and lower your body towards the ground by bending your elbows, keeping your back straight.", "As you lower yourself, shift your weight to one side and lift the opposite arm off the ground, extending it straight out to the side.", "Push through your chest and triceps to raise your body back up to the starting position, while simultaneously lowering your extended arm back to the ground.", "Repeat the movement, alternating the arm you extend with each repetition."]', '["Comienza en posición de flexión con las manos separadas a la altura de los hombros y una mano colocada un poco más ancha que la otra.", "Activa el core y baja el cuerpo hacia el suelo flexionando los codos, manteniendo la espalda recta.", "Al bajar, traslada el peso hacia un lado y levanta el brazo opuesto del suelo, extendiéndolo recto hacia el lado.", "Empuja con el pecho y los tríceps para subir el cuerpo de nuevo a la posición inicial, mientras bajas simultáneamente el brazo extendido de vuelta al suelo.", "Repite el movimiento, alternando el brazo que extiendes en cada repetición."]'),
  ('Flexión Arquero', 'archer-push-up.gif', 'chest', '["Start in a push-up position with your hands slightly wider than shoulder-width apart.", "Extend one arm straight out to the side, parallel to the ground.", "Lower your body by bending your elbows, keeping your back straight and core engaged.", "Push back up to the starting position.", "Repeat on the other side, extending the opposite arm out to the side.", "Continue alternating sides for the desired number of repetitions."]', '["Comienza en posición de flexión de brazos con las manos un poco más separadas que el ancho de los hombros.", "Extiende un brazo hacia el lado, paralelo al suelo.", "Baja el cuerpo flexionando los codos, manteniendo la espalda recta y el core activado.", "Empuja hacia arriba para volver a la posición inicial.", "Repite del otro lado, extendiendo el brazo opuesto hacia el lado.", "Continúa alternando lados durante el número de repeticiones deseado."]'),
  ('Flexión con Agarre Abierto', 'wide-hand-push-up.gif', 'chest', '["Start in a high plank position with your hands wider than shoulder-width apart.", "Keep your body in a straight line from head to toe.", "Lower your chest towards the ground by bending your elbows, keeping them close to your sides.", "Push through your palms to extend your arms and return to the starting position.", "Repeat for the desired number of repetitions."]', '["Comienza en una posición de plancha alta con las manos más separadas que la anchura de los hombros.", "Mantén el cuerpo en línea recta de la cabeza a los pies.", "Baja el pecho hacia el suelo flexionando los codos, manteniéndolos cerca de los costados.", "Empuja con las palmas para extender los brazos y regresar a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Flexión con Balón Medicinal', 'push-up-medicine-ball.gif', 'chest', '["Start in a high plank position with your hands on the medicine ball, shoulder-width apart.", "Engage your core and lower your body towards the ground by bending your elbows, keeping your back straight.", "Push through your palms to extend your arms and return to the starting position.", "Repeat for the desired number of repetitions."]', '["Comienza en una posición de plancha alta con las manos sobre el balón medicinal, separadas a la altura de los hombros.", "Activa el core y baja el cuerpo hacia el suelo flexionando los codos, manteniendo la espalda recta.", "Empuja con las palmas para extender los brazos y regresar a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Flexión con Caída (Drop Push-Up)', 'drop-push-up.gif', 'chest', '["Start in a high plank position with your hands slightly wider than shoulder-width apart.", "Lower your chest towards the ground, keeping your elbows close to your body.", "Once your chest is just above the ground, quickly drop your knees to the ground.", "Push yourself back up to the starting position by extending your arms.", "Repeat for the desired number of repetitions."]', '["Comienza en posición de plancha alta con las manos un poco más separadas que el ancho de los hombros.", "Baja el pecho hacia el suelo, manteniendo los codos cerca del cuerpo.", "Una vez que tu pecho esté justo por encima del suelo, baja rápidamente las rodillas al suelo.", "Empuja tu cuerpo de vuelta a la posición inicial extendiendo los brazos.", "Repite el número de repeticiones deseado."]'),
  ('Flexión con Caída con Lastre', 'weighted-drop-push-up.gif', 'chest', '["Start in a high plank position with your hands slightly wider than shoulder-width apart and your feet together.", "Lower your chest towards the ground, keeping your elbows close to your body.", "Once your chest is just above the ground, explosively push yourself up, lifting your hands off the ground.", "As you push up, quickly move your hands out to the sides and slightly forward, allowing your body to drop down towards the ground.", "Catch yourself with your hands in the wider position and immediately lower your chest towards the ground again.", "Repeat the push-up motion, dropping down and catching yourself with your hands in the narrower position.", "Continue alternating between the wider and narrower hand positions for the desired number of repetitions."]', '["Comienza en una posición de plancha alta con las manos un poco más separadas que la anchura de los hombros y los pies juntos.", "Baja el pecho hacia el suelo, manteniendo los codos cerca del cuerpo.", "Cuando el pecho esté justo por encima del suelo, empújate hacia arriba de forma explosiva, levantando las manos del suelo.", "Mientras te empujas hacia arriba, mueve rápidamente las manos hacia los lados y un poco hacia adelante, permitiendo que tu cuerpo caiga hacia el suelo.", "Recíbete con las manos en la posición más ancha y baja de nuevo el pecho inmediatamente hacia el suelo.", "Repite el movimiento de flexión, bajando y recibiéndote con las manos en la posición más estrecha.", "Continúa alternando entre las posiciones de manos más ancha y más estrecha el número de repeticiones deseado."]'),
  ('Flexión con Elevación de Brazo', 'raise-single-arm-push-up.gif', 'chest', '["Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.", "Extend one arm straight out to the side, parallel to the ground.", "Lower your body towards the ground by bending your elbows, keeping your back straight and core engaged.", "Push back up to the starting position, using your chest muscles to lift your body.", "Repeat with the other arm extended."]', '["Comienza en posición de flexión con las manos un poco más separadas que la anchura de los hombros y los pies juntos.", "Extiende un brazo hacia el lado, paralelo al suelo.", "Baja el cuerpo hacia el suelo flexionando los codos, manteniendo la espalda recta y el core activado.", "Empuja de vuelta a la posición inicial, usando los músculos del pecho para elevar el cuerpo.", "Repite con el otro brazo extendido."]'),
  ('Flexión con Manos sobre Fitball', 'push-up-on-stability-ball.gif', 'chest', '["Place the stability ball on the ground and position yourself facing down with your hands on the ball, shoulder-width apart.", "Extend your legs straight out behind you, balancing on your toes.", "Engage your core and lower your chest towards the ball by bending your elbows, keeping your body in a straight line.", "Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.", "Repeat for the desired number of repetitions."]', '["Coloca el balón de estabilidad en el suelo y ponte boca abajo con las manos sobre el balón, separadas a la altura de los hombros.", "Extiende las piernas rectas detrás de ti, equilibrándote sobre los dedos de los pies.", "Activa el core y baja el pecho hacia el balón flexionando los codos, manteniendo el cuerpo en línea recta.", "Haz una pausa breve en la parte baja, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos.", "Repite el número de repeticiones deseado."]'),
  ('Flexión con Palmada', 'clap-push-up.gif', 'chest', '["Start in a high plank position with your hands slightly wider than shoulder-width apart.", "Lower your body towards the ground by bending your elbows, keeping your core engaged.", "Push through your palms explosively to propel your body off the ground.", "While in mid-air, clap your hands together before landing back in the starting position.", "Repeat for the desired number of repetitions."]', '["Comienza en posición de plancha alta con las manos un poco más separadas que el ancho de los hombros.", "Baja el cuerpo hacia el suelo flexionando los codos, manteniendo el core activado.", "Empuja con las palmas de forma explosiva para impulsar tu cuerpo fuera del suelo.", "Mientras estás en el aire, junta las manos en un aplauso antes de aterrizar de vuelta en la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Flexión con Toque de Hombro', 'shoulder-tap-push-up.gif', 'chest', '["Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line from head to heels.", "Lower your body towards the ground by bending your elbows, keeping them close to your sides.", "As you push back up, lift your right hand off the ground and tap your left shoulder.", "Return your right hand to the ground and repeat the push-up, this time lifting your left hand and tapping your right shoulder.", "Continue alternating shoulder taps with each push-up repetition.", "Maintain a stable core and avoid excessive hip rotation throughout the exercise.", "Repeat for the desired number of repetitions."]', '["Comienza en una posición de plancha alta con las manos un poco más separadas que la anchura de los hombros y el cuerpo en línea recta desde la cabeza hasta los talones.", "Baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados.", "Mientras empujas hacia arriba, levanta la mano derecha del suelo y toca el hombro izquierdo.", "Vuelve a colocar la mano derecha en el suelo y repite la flexión, esta vez levantando la mano izquierda y tocando el hombro derecho.", "Continúa alternando los toques de hombro en cada repetición de la flexión.", "Mantén el core estable y evita una rotación excesiva de la cadera durante todo el ejercicio.", "Repite el número de repeticiones deseado."]'),
  ('Flexión con Toque de Pecho', 'chest-tap-push-up-male.gif', 'chest', '["Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line.", "Lower your body towards the ground by bending your elbows, keeping them close to your sides.", "As you lower yourself, tap your chest with your right hand.", "Push yourself back up to the starting position.", "Repeat the movement, this time tapping your chest with your left hand.", "Continue alternating sides for the desired number of repetitions."]', '["Comienza en posición de plancha alta con las manos un poco más separadas que el ancho de los hombros y el cuerpo en línea recta.", "Baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados.", "Mientras te bajas, toca tu pecho con la mano derecha.", "Empújate de vuelta hacia arriba hasta la posición inicial.", "Repite el movimiento, esta vez tocando tu pecho con la mano izquierda.", "Continúa alternando lados durante el número de repeticiones deseado."]'),
  ('Flexión contra la Pared', 'push-up-wall.gif', 'chest', '["Stand facing a wall, about arm''s length away.", "Place your hands on the wall at shoulder height, slightly wider than shoulder-width apart.", "Step back a few feet, keeping your body straight and your feet hip-width apart.", "Bend your elbows and lower your chest towards the wall, keeping your body in a straight line.", "Push back up to the starting position, straightening your arms.", "Repeat for the desired number of repetitions."]', '["Ponte de pie frente a una pared, a una distancia aproximada de un brazo.", "Coloca las manos en la pared a la altura de los hombros, un poco más separadas que la anchura de los hombros.", "Da un paso atrás, manteniendo el cuerpo recto y los pies separados a la altura de las caderas.", "Flexiona los codos y baja el pecho hacia la pared, manteniendo el cuerpo en línea recta.", "Empuja de vuelta a la posición inicial, estirando los brazos.", "Repite el número de repeticiones deseado."]'),
  ('Flexión de Rodillas', 'kneeling-push-up-male.gif', 'chest', '["Start by kneeling on the ground with your hands shoulder-width apart, fingers pointing forward.", "Extend your legs behind you, resting on the balls of your feet, so that your body forms a straight line from head to heels.", "Engage your core and lower your body towards the ground by bending your elbows, keeping them close to your sides.", "Continue lowering until your chest is just above the ground, then push back up to the starting position by straightening your arms.", "Repeat for the desired number of repetitions."]', '["Comienza arrodillado en el suelo con las manos separadas a la altura de los hombros, los dedos apuntando hacia adelante.", "Extiende las piernas hacia atrás, apoyándote en la punta de los pies, de modo que tu cuerpo forme una línea recta desde la cabeza hasta los talones.", "Activa el core y baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados.", "Continúa bajando hasta que el pecho esté justo encima del suelo, luego empuja hacia arriba a la posición inicial enderezando los brazos.", "Repite el número de repeticiones deseado."]'),
  ('Flexión Declinada', 'decline-push-up.gif', 'chest', '["Place your hands on the ground slightly wider than shoulder-width apart, with your feet elevated on a stable surface.", "Keep your body in a straight line from head to toe, engaging your core muscles.", "Lower your chest towards the ground by bending your elbows, keeping them close to your body.", "Push through your palms to extend your arms and return to the starting position.", "Repeat for the desired number of repetitions."]', '["Coloca las manos en el suelo un poco más separadas que el ancho de los hombros, con los pies elevados sobre una superficie estable.", "Mantén el cuerpo en línea recta de la cabeza a los pies, activando los músculos del core.", "Baja el pecho hacia el suelo flexionando los codos, manteniéndolos cerca del cuerpo.", "Empuja con las palmas para extender los brazos y regresar a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Flexión en Pica sobre Fitball', 'exercise-ball-pike-push-up.gif', 'chest', '["Start in a push-up position with your hands on the floor and your shins resting on the stability ball.", "Engage your core and lift your hips up towards the ceiling, rolling the ball towards your hands.", "Keep your legs straight and your body in a pike position, forming an inverted V shape.", "Bend your elbows and lower your upper body towards the floor, keeping your head in line with your hands.", "Push through your hands and extend your arms to return to the starting position.", "Repeat for the desired number of repetitions."]', '["Comienza en posición de flexión de brazos con las manos en el suelo y las espinillas apoyadas sobre el balón de estabilidad.", "Activa el core y levanta las caderas hacia el techo, haciendo rodar el balón hacia las manos.", "Mantén las piernas rectas y el cuerpo en posición de pica, formando una V invertida.", "Dobla los codos y baja la parte superior del cuerpo hacia el suelo, manteniendo la cabeza alineada con las manos.", "Empuja con las manos y extiende los brazos para volver a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Flexión en Plancha Completa (Planche)', 'full-planche-push-up.gif', 'chest', '["Start in a push-up position with your hands placed slightly wider than shoulder-width apart.", "Engage your core and lower your body down towards the ground, keeping your elbows close to your sides.", "As you lower yourself, lean your body forward and lift your feet off the ground, balancing on your hands.", "Continue to lower your body until your chest is just above the ground.", "Push through your hands and extend your arms to lift your body back up to the starting position.", "Maintain a straight line from your head to your heels throughout the movement.", "Repeat for the desired number of repetitions."]', '["Comienza en posición de flexión de brazos con las manos un poco más separadas que el ancho de los hombros.", "Activa el core y baja el cuerpo hacia el suelo, manteniendo los codos cerca de los costados.", "Mientras te bajas, inclina el cuerpo hacia adelante y levanta los pies del suelo, equilibrándote sobre las manos.", "Continúa bajando el cuerpo hasta que el pecho quede justo por encima del suelo.", "Empuja con las manos y extiende los brazos para volver a subir el cuerpo a la posición inicial.", "Mantén una línea recta desde la cabeza hasta los talones durante todo el movimiento.", "Repite el número de repeticiones deseado."]'),
  ('Flexión en Reloj', 'clock-push-up.gif', 'chest', '["Start in a high plank position with your hands directly under your shoulders and your body in a straight line.", "Lower your body towards the ground by bending your elbows, keeping them close to your sides.", "As you lower, rotate your body to the left, extending your left arm straight out to the side.", "Push back up to the starting position, while rotating your body to the center.", "Repeat the push-up, this time rotating your body to the right and extending your right arm out to the side.", "Continue alternating sides with each repetition."]', '["Comienza en una posición de plancha alta con las manos justo debajo de los hombros y el cuerpo en línea recta.", "Baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados.", "Mientras bajas, gira el cuerpo hacia la izquierda, extendiendo el brazo izquierdo recto hacia el lado.", "Empuja de vuelta hacia arriba hasta la posición inicial, mientras giras el cuerpo hacia el centro.", "Repite la flexión de brazos, esta vez girando el cuerpo hacia la derecha y extendiendo el brazo derecho hacia el lado.", "Continúa alternando lados en cada repetición."]'),
  ('Flexión en Suspensión (TRX)', 'suspended-push-up.gif', 'chest', '["Find a suspension trainer and adjust it to an appropriate height.", "Stand facing away from the anchor point and hold the handles with an overhand grip.", "Walk your feet forward, leaning your body forward until your weight is supported by the suspension trainer.", "Keep your body straight from head to heels, engage your core, and lower your chest towards the handles.", "Push through your chest and arms to return to the starting position.", "Repeat for the desired number of repetitions."]', '["Busca un entrenador de suspensión y ajústalo a una altura adecuada.", "Ponte de pie de espaldas al punto de anclaje y sostén las asas con un agarre prono.", "Camina hacia adelante con los pies, inclinando el cuerpo hacia adelante hasta que tu peso quede sostenido por el entrenador de suspensión.", "Mantén el cuerpo recto desde la cabeza hasta los talones, activa el core y baja el pecho hacia las asas.", "Empuja con el pecho y los brazos para volver a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Flexión Escapular', 'scapula-push-up.gif', 'chest', '["Start in a high plank position with your hands directly under your shoulders and your body in a straight line.", "Lower your chest towards the ground, keeping your elbows close to your body.", "As you lower, squeeze your shoulder blades together and push your chest forward.", "Pause for a moment at the bottom, then push back up to the starting position.", "Repeat for the desired number of repetitions."]', '["Comienza en una posición de plancha alta con las manos justo debajo de los hombros y el cuerpo en línea recta.", "Baja el pecho hacia el suelo, manteniendo los codos cerca del cuerpo.", "A medida que bajas, junta las escápulas y empuja el pecho hacia delante.", "Haz una pausa por un momento en la posición baja, luego empuja de nuevo hacia arriba hasta la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Flexión Escapular Inclinada', 'incline-scapula-push-up.gif', 'chest', '["Set up an incline bench at a 45-degree angle.", "Place your hands on the bench slightly wider than shoulder-width apart.", "Position your feet on the ground, hip-width apart.", "Lower your chest towards the bench, keeping your elbows tucked in.", "As you lower, retract your shoulder blades, squeezing your scapulae together.", "Push through your palms to extend your arms and return to the starting position.", "Repeat for the desired number of repetitions."]', '["Coloca un banco inclinado a un ángulo de 45 grados.", "Coloca las manos en el banco, ligeramente más separadas que la altura de los hombros.", "Coloca los pies en el suelo, separados a la altura de las caderas.", "Baja el pecho hacia el banco, manteniendo los codos pegados al cuerpo.", "Mientras bajas, retrae los omóplatos, apretándolos entre sí.", "Empuja con las palmas para extender los brazos y regresar a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Flexión Hindú Modificada', 'modified-hindu-push-up-male.gif', 'chest', '["Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet hip-width apart.", "Lower your body towards the ground, bending your elbows and keeping your core engaged.", "As you lower your body, shift your weight back and lift your hips up towards the ceiling, creating an inverted V shape with your body.", "Continue to lower your body until your chest is just above the ground, then reverse the movement, pushing your hips back down and extending your arms to return to the starting position.", "Repeat for the desired number of repetitions."]', '["Comienza en posición de flexión con las manos un poco más separadas que la anchura de los hombros y los pies separados a la altura de las caderas.", "Baja el cuerpo hacia el suelo, flexionando los codos y manteniendo el core activado.", "Mientras bajas el cuerpo, desplaza el peso hacia atrás y eleva las caderas hacia el techo, formando una V invertida con tu cuerpo.", "Sigue bajando el cuerpo hasta que el pecho quede justo por encima del suelo y luego invierte el movimiento, empujando las caderas hacia abajo y extendiendo los brazos para volver a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Flexión Inclinada', 'incline-push-up.gif', 'chest', '["Place your hands on an elevated surface, such as a bench or step, slightly wider than shoulder-width apart.", "Extend your legs behind you, resting on the balls of your feet, creating a straight line from your head to your heels.", "Lower your chest towards the elevated surface by bending your elbows, keeping your body in a straight line.", "Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.", "Repeat for the desired number of repetitions."]', '["Coloca las manos sobre una superficie elevada, como un banco o un escalón, ligeramente más separadas que la altura de los hombros.", "Extiende las piernas detrás de ti, apoyándote en la punta de los pies, formando una línea recta desde la cabeza hasta los talones.", "Baja el pecho hacia la superficie elevada doblando los codos, manteniendo el cuerpo en línea recta.", "Haz una pausa breve en la parte baja, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos.", "Repite el número de repeticiones deseado."]'),
  ('Flexión Inclinada con Agarre Invertido', 'incline-reverse-grip-push-up.gif', 'chest', '["Place your hands on the edge of a bench or elevated surface, slightly wider than shoulder-width apart.", "Extend your legs behind you, resting on the balls of your feet, creating a straight line from your head to your heels.", "Lower your chest towards the bench by bending your elbows, keeping them close to your sides.", "Pause for a moment at the bottom, then push yourself back up to the starting position by extending your arms.", "Repeat for the desired number of repetitions."]', '["Coloca las manos en el borde de un banco o una superficie elevada, ligeramente más separadas que la altura de los hombros.", "Extiende las piernas detrás de ti, apoyándote en la punta de los pies, formando una línea recta desde la cabeza hasta los talones.", "Baja el pecho hacia el banco doblando los codos, manteniéndolos cerca de los costados.", "Haz una pausa breve en la parte baja, luego empújate de nuevo hacia arriba a la posición inicial extendiendo los brazos.", "Repite el número de repeticiones deseado."]'),
  ('Flexión Pliométrica', 'plyo-push-up.gif', 'chest', '["Start in a high plank position with your hands slightly wider than shoulder-width apart.", "Lower your chest towards the ground by bending your elbows, keeping your body in a straight line.", "Push explosively off the ground, using your chest muscles to propel your upper body off the ground.", "Land softly with your hands back in the starting position.", "Repeat for the desired number of repetitions."]', '["Comienza en posición de plancha alta con las manos un poco más separadas que el ancho de los hombros.", "Baja el pecho hacia el suelo flexionando los codos, manteniendo el cuerpo en línea recta.", "Empuja explosivamente contra el suelo, usando los músculos del pecho para impulsar la parte superior del cuerpo fuera del suelo.", "Aterriza suavemente con las manos de vuelta en la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Flexión Pliométrica con Kettlebell', 'kettlebell-plyo-push-up.gif', 'chest', '["Start in a high plank position with your hands on the kettlebells, shoulder-width apart.", "Lower your chest towards the ground, keeping your elbows close to your body.", "Push through your hands explosively, lifting your hands off the kettlebells and extending your arms fully.", "Land softly back on the kettlebells and immediately lower your chest back down for the next repetition.", "Repeat for the desired number of repetitions."]', '["Comienza en una posición de plancha alta con las manos sobre las pesas rusas, separadas a la altura de los hombros.", "Baja el pecho hacia el suelo, manteniendo los codos cerca del cuerpo.", "Empuja con las manos de forma explosiva, levantándolas de las pesas rusas y extendiendo los brazos por completo.", "Aterriza suavemente sobre las pesas rusas y baja el pecho de inmediato para la siguiente repetición.", "Repite el número de repeticiones deseado."]'),
  ('Flexión Pliométrica desde Banco (Depth Jump)', 'incline-push-up-depth-jump.gif', 'chest', '["Find an elevated surface, such as a bench or step, and place your hands shoulder-width apart on the edge.", "Step your feet back, keeping your body in a straight line from head to heels.", "Lower your chest towards the edge of the surface, bending your elbows and keeping your body aligned.", "Push through your palms to extend your arms and return to the starting position.", "Jump off the edge of the surface, landing softly with your knees slightly bent.", "Repeat the push-up and depth jump for the desired number of repetitions."]', '["Busca una superficie elevada, como un banco o un escalón, y coloca las manos separadas a la altura de los hombros en el borde.", "Da un paso hacia atrás con los pies, manteniendo el cuerpo en línea recta desde la cabeza hasta los talones.", "Baja el pecho hacia el borde de la superficie, doblando los codos y manteniendo el cuerpo alineado.", "Empuja con las palmas para extender los brazos y regresar a la posición inicial.", "Salta desde el borde de la superficie, aterrizando suavemente con las rodillas ligeramente flexionadas.", "Repite la flexión de brazos y el salto en profundidad durante el número de repeticiones deseado."]'),
  ('Flexión Plus (Protracción Escapular)', 'push-up-plus.gif', 'chest', '["Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line from head to heels.", "Lower your body towards the ground by bending your elbows, keeping them close to your sides.", "Once your chest is just above the ground, push through your hands to extend your arms and lift your upper body up.", "At the top of the movement, protract your shoulder blades by pushing your upper back towards the ceiling.", "Pause for a moment, then reverse the movement by retracting your shoulder blades and lowering your body back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Comienza en una posición de plancha alta con las manos un poco más separadas que la anchura de los hombros y el cuerpo en línea recta desde la cabeza hasta los talones.", "Baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados.", "Cuando el pecho esté justo por encima del suelo, empuja con las manos para extender los brazos y levantar la parte superior del cuerpo.", "En la parte alta del movimiento, separa las escápulas empujando la parte superior de la espalda hacia el techo.", "Haz una pausa por un momento y luego invierte el movimiento juntando las escápulas y bajando el cuerpo de nuevo a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Flexión Profunda con Mancuernas', 'deep-push-up.gif', 'chest', '["Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line.", "Lower your chest towards the ground by bending your elbows, keeping them close to your body.", "Push through your palms to extend your arms and return to the starting position.", "Repeat for the desired number of repetitions."]', '["Comienza en posición de plancha alta con las manos un poco más separadas que el ancho de los hombros y el cuerpo en línea recta.", "Baja el pecho hacia el suelo flexionando los codos, manteniéndolos cerca del cuerpo.", "Empuja con las palmas para extender los brazos y regresar a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Flexión sobre Bosu', 'push-up-bosu-ball.gif', 'chest', '["Place the bosu ball on the ground with the flat side facing up.", "Position yourself in a push-up position with your hands on the outer edges of the bosu ball.", "Engage your core and lower your body down towards the bosu ball by bending your elbows.", "Push yourself back up to the starting position by extending your arms.", "Repeat for the desired number of repetitions."]', '["Coloca el bosu en el suelo con el lado plano hacia arriba.", "Colócate en posición de flexión con las manos en los bordes exteriores del bosu.", "Activa el core y baja el cuerpo hacia el bosu flexionando los codos.", "Empuja tu cuerpo de vuelta a la posición inicial extendiendo los brazos.", "Repite el número de repeticiones deseado."]'),
  ('Flexión Superman', 'superman-push-up.gif', 'chest', '["Start in a high plank position with your hands slightly wider than shoulder-width apart and your feet together.", "Engage your core and lower your body towards the ground, keeping your elbows close to your sides.", "As you lower your body, simultaneously lift your right arm and left leg off the ground, extending them straight out.", "Pause for a moment at the top, then lower your arm and leg back down while pushing yourself back up to the starting position.", "Repeat the movement, this time lifting your left arm and right leg.", "Continue alternating sides for the desired number of repetitions."]', '["Comienza en una posición de plancha alta con las manos un poco más separadas que la anchura de los hombros y los pies juntos.", "Activa el core y baja el cuerpo hacia el suelo, manteniendo los codos cerca de los costados.", "Mientras bajas el cuerpo, levanta simultáneamente el brazo derecho y la pierna izquierda del suelo, extendiéndolos completamente.", "Haz una pausa de un momento en la parte superior, luego baja el brazo y la pierna mientras te empujas de nuevo hacia arriba a la posición inicial.", "Repite el movimiento, esta vez levantando el brazo izquierdo y la pierna derecha.", "Continúa alternando lados durante el número de repeticiones deseado."]'),
  ('Fondos Coreanos', 'korean-dips.gif', 'chest', '["Position yourself between two parallel bars with your arms extended and supporting your body weight.", "Lower your body by bending your elbows until your upper arms are parallel to the ground.", "Pause for a moment, then push yourself back up to the starting position by straightening your arms.", "Repeat for the desired number of repetitions."]', '["Colócate entre dos barras paralelas con los brazos extendidos sosteniendo el peso de tu cuerpo.", "Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo.", "Haz una pausa breve, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos.", "Repite el número de repeticiones deseado."]'),
  ('Fondos de Pecho Asistidos con Agarre Abierto (de Rodillas)', 'assisted-wide-grip-chest-dip-kneeling.gif', 'chest', '["Adjust the machine to your desired height and secure your knees on the pad.", "Grasp the handles with a wide grip and keep your elbows slightly bent.", "Lower your body by bending your elbows until your upper arms are parallel to the floor.", "Push yourself back up to the starting position by extending your arms.", "Repeat for the desired number of repetitions."]', '["Ajusta la máquina a la altura deseada y asegura las rodillas sobre la almohadilla.", "Agarra las agarraderas con un agarre amplio y mantén los codos ligeramente flexionados.", "Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo.", "Empuja tu cuerpo de vuelta a la posición inicial extendiendo los brazos.", "Repite el número de repeticiones deseado."]'),
  ('Fondos de Pecho Asistidos en Máquina (de Rodillas)', 'assisted-chest-dip-kneeling.gif', 'chest', '["Adjust the machine to your desired height and secure your knees on the pad.", "Grasp the handles with your palms facing down and your arms fully extended.", "Lower your body by bending your elbows until your upper arms are parallel to the floor.", "Pause for a moment, then push yourself back up to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta la máquina a la altura deseada y asegura las rodillas sobre la almohadilla.", "Agarra las agarraderas con las palmas hacia abajo y los brazos completamente extendidos.", "Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo.", "Haz una pausa por un momento, luego empuja tu cuerpo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Fondos de Pecho con Agarre Abierto en Paralelas Altas', 'wide-grip-chest-dip-on-high-parallel-bars.gif', 'chest', '["Position yourself on the parallel bars with your arms fully extended and your body suspended in the air.", "Lean forward slightly and lower your body by bending your elbows until your chest is just above the bars.", "Pause for a moment, then push yourself back up to the starting position by straightening your arms.", "Repeat for the desired number of repetitions."]', '["Colócate sobre las barras paralelas con los brazos completamente extendidos y el cuerpo suspendido en el aire.", "Inclínate ligeramente hacia adelante y baja el cuerpo flexionando los codos hasta que el pecho quede justo por encima de las barras.", "Haz una pausa breve, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos.", "Repite el número de repeticiones deseado."]'),
  ('Fondos de Pecho en Barra Recta', 'chest-dip-on-straight-bar.gif', 'chest', '["Grab the parallel bars with your palms facing down and your arms fully extended.", "Bend your knees and cross your ankles.", "Lower your body by bending your arms until your shoulders are below your elbows.", "Push yourself back up to the starting position by straightening your arms.", "Repeat for the desired number of repetitions."]', '["Agarra las barras paralelas con las palmas hacia abajo y los brazos completamente extendidos.", "Flexiona las rodillas y cruza los tobillos.", "Baja el cuerpo flexionando los brazos hasta que los hombros queden por debajo de los codos.", "Empújate de vuelta hacia arriba a la posición inicial extendiendo los brazos.", "Repite el número de repeticiones deseado."]');
insert into public.exercises (name, video_url, body_part_id, instructions_en, instructions_es)
